export const topicEnglishDataset: Record<string, { explanation: string; codeExplanation: string }> = {
  'intro-to-html': {
    explanation: `**HTML (HyperText Markup Language)** is the skeleton of web pages. It tells you what elements are on the page - headings, paragraphs, images, links, and forms. HTML uses **tags** written in angle brackets like <h1> and <p>. Each tag has a specific meaning. When you open a website in your browser, the browser reads the HTML code and displays it visually. This is the foundation upon which CSS (styling) and JavaScript (interactivity) are built. **Without HTML, web pages simply cannot exist.** That's why learning HTML is the first and most important step in web development.

The best thing about HTML is that it's **beginner-friendly** - you can create your first page in just a few minutes. But that doesn't mean it's weak. Professional websites use complex HTML structures optimized for accessibility, SEO, and performance. That's why keeping your fundamentals strong is very important.`,
    codeExplanation: `This code shows a **basic HTML page**. The first line <!DOCTYPE html> tells the browser this is HTML5. <html lang="en"> sets the page language - this is important for accessibility. The <head> section contains metadata about the page like the title and character encoding. <body> contains everything visible to the user. <h1> is the **main heading** - there should only be one per page. <p> is a **paragraph**. <img> adds an image, and the \`alt\` attribute provides a description for screen readers. <a> is a **hyperlink** that takes you to another page. **Every tag must be properly closed** - like <p>...</p> - otherwise the browser can get confused.`
  },
  'html-elements-tags': {
    explanation: `**HTML elements** are the building blocks that make up web pages. Every element consists of three things: an **opening tag** (<tagname>), **content** (what the user sees), and a **closing tag** (</tagname>). Some elements are **void** elements like <img> and <br> - they don't have a closing tag. Elements come in two types: **block-level** (take up the full width, start on a new line - like <div>, <p>, <h1>) and **inline** (take up only as much space as needed, staying on the same line - like <span>, <a>, <strong>).

The most common mistake is putting everything in a <div>. <div> has no semantic meaning - it's just a container. Instead, you should use **semantic elements** like <header>, <nav>, <main>, <article>, <section>, and <footer>. These help search engines and screen readers understand the page structure. **Properly nesting elements** is also important - close tags in the reverse order you opened them.`,
    codeExplanation: `This code is an example of **semantic HTML**. <header> represents the top section of the page - it contains the heading and navigation. <nav> is a specific element for navigation links - screen reader users can jump directly to navigation. <main> wraps the primary content - **there should only be one <main> per page**. <article> is self-contained content like a blog post. <strong> is an inline element that makes text **bold** and indicates importance. <footer> shows copyright information at the bottom of the page. **Block elements** (<header>, <main>, <article>, <footer>) start on a new line, while **inline elements** (<a>, <strong>) stay on the same line.`
  },
  'html-forms-input': {
    explanation: `**HTML forms** are the standard way to collect data from users. When you sign up on a website, log in, or perform a search, you're using a form. The <form> element wraps everything, the \`action\` attribute specifies where to send the data, and the \`method\` attribute specifies how (GET or POST).

**Input types** are very important - \`type="text"\` for simple text, \`type="email"\` for email validation, \`type="password"\` to hide the password, \`type="checkbox"\` for multiple selections, and \`type="radio"\` for single selection. **Every input must have a <label>** - the label is linked to the input via the \`for\` attribute, which matches the \`id\`. Labels are also essential for screen readers. **Fieldset and legend** group related inputs together - like a "Personal Information" section. The **required attribute** tells the browser that this field must be filled in - the form won't submit if left empty.`,
    codeExplanation: `This form is for **user registration**. <fieldset> groups related fields both visually and semantically, and <legend> provides a caption for the group. Each <label>'s \`for\` attribute is linked to the matching <input>'s \`id\` - the benefit is that when the user clicks the label, the input automatically gets focus. \`type="email"\` lets the browser perform automatic validation - if the user doesn't include @, an error will appear. \`type="password"\` hides the characters. \`minlength="8"\` enforces a minimum password length. The \`required\` attribute checks the field before the form is submitted. <button type="submit"> submits the form when clicked. **All of this validation works without JavaScript** - these are built-in HTML5 features.`
  },
  'semantic-html': {
    explanation: `**Semantic HTML** means using **meaningful tags** that describe the purpose of your content. For example, <div> is just a generic container, but <nav> clearly indicates that navigation links are here. Similarly, <article> indicates self-contained content, and <aside> indicates supplementary content.

Semantic HTML has **two major benefits**. First: **SEO (Search Engine Optimization)** - search engines like Google identify and rank semantic tags. Second: **Accessibility** - screen reader users can use semantic landmarks to jump to different sections of the page. For example, a blind user can tell their screen reader to "go to main content" and it will jump directly to the <main> tag. **Heading hierarchy** is also part of semantic HTML - only one <h1> per page, then <h2>, <h3> in order, without skipping levels.`,
    codeExplanation: `This code shows a **proper semantic structure**. <header> is the site header with the title and navigation. <nav> wraps navigation links. <main> contains the primary content - **exactly one <main> per page**. <article> is self-contained content that can exist independently (like a blog post). <section> is a group of related content. <aside> contains tangential content not directly related to the main content. <footer> contains copyright and contact information. **Semantic tags don't change visual appearance** - <nav> and <div> look the same. The difference is in meaning, which is important for search engines and screen readers.`
  },
  'html5-apis': {
    explanation: `**HTML5 APIs** are built-in features in modern web browsers that provide powerful functionality **through JavaScript**. No third-party libraries are needed for these APIs. The most commonly used APIs include: **localStorage** (permanently stores data in the user's browser), **Geolocation API** (accesses the user's location), **Canvas API** (creates graphics and drawings), and **Drag and Drop API** (allows dragging elements).

**localStorage** is the most common API. It stores data in **key-value pairs**, and the data persists even after closing the browser. The storage limit is 5-10MB per origin. Data is stored only as **strings**, so for objects you need to use \`JSON.stringify()\` and \`JSON.parse()\`. **sessionStorage** is similar to localStorage, but data is deleted when the tab is closed. **Always do feature detection** - some browsers or older versions may not have these APIs available. Check with \`if (typeof Storage !== "undefined")\`.`
  },
  'css-box-model': {
    explanation: `The **CSS Box Model** is the most important concept in CSS. Every HTML element is a rectangular box, and the box model defines how its size and spacing are calculated. It consists of four layers from inside to outside: **content** (the actual text/image), **padding** (space between content and border), **border** (the edge of the box), and **margin** (space outside the border).

The total width of an element is calculated as: \`content width + padding-left + padding-right + border-left + border-right + margin-left + margin-right\`. This means that adding 20px padding to a 100px wide box actually makes it 140px wide. **This surprises many beginners.** The \`box-sizing: border-box\` property changes this behavior so that padding and border are included in the total width - this makes layout much easier. **Always use \`box-sizing: border-box\` on all elements.** This simplifies layout calculations.`,
    codeExplanation: `This code demonstrates the **box model**. The first box (.box-a) has \`width: 300px\` and \`box-sizing: content-box\` (default). With 20px padding and 2px border, its total width becomes \`300 + 20 + 20 + 2 + 2 = 344px\`. The second box (.box-b) has \`box-sizing: border-box\` - here the 300px width **includes** padding and border, so the content area is only \`300 - 20 - 20 - 2 - 2 = 256px\`. **margin: 20px auto** centers the box horizontally. **border-radius: 8px** rounds the corners. **box-shadow** adds a shadow effect using horizontal offset, vertical offset, blur, spread, and color.`
  },
  'css-flexbox': {
    explanation: `**Flexbox (Flexible Box Layout)** is a one-dimensional CSS layout model that makes it incredibly easy to arrange items in rows or columns. Before flexbox, developers struggled with floats, positioning, and inline-block hacks. Flexbox solves all that.

**Key concepts:** The **flex container** (parent with \`display: flex\`) controls the layout of its **flex items** (children). The **main axis** is defined by \`flex-direction\` (row or column), and the **cross axis** is perpendicular to it. \`justify-content\` aligns items along the main axis, while \`align-items\` aligns along the cross axis. The **\`flex\` shorthand** (\`flex-grow flex-shrink flex-basis\`) is the most powerful part - it controls how items grow, shrink, and set their initial size. **Flexbox is ideal for navigation bars, centering, card layouts, and responsive designs.** It works great for components but not for full page layouts (use CSS Grid for that).`,
    codeExplanation: `This code shows a typical **flexbox navbar**. \`display: flex\` on .navbar makes all children flex items arranged in a row. \`justify-content: space-between\` pushes the logo to the left and links to the right - the remaining space is distributed between them. \`align-items: center\` vertically centers items. .nav-links is also a flex container - \`gap: 20px\` adds space between links (replaces the older margin approach). **\`flex-wrap: wrap\`** allows items to wrap to the next line on small screens - without it, items would overflow or shrink. Each .nav-links a has \`padding: 10px 15px\` for larger clickable areas.`
  },
  'css-grid': {
    explanation: `**CSS Grid Layout** is a two-dimensional layout system that handles both rows and columns simultaneously. While flexbox is for one-dimensional layouts (either row OR column), grid is for two-dimensional layouts (row AND column together). This makes it the perfect choice for page-level layouts, image galleries, and complex component layouts.

**Key properties:** \`grid-template-columns\` and \`grid-template-rows\` define the track sizes. You can use fixed values (\`200px\`), flexible values (\`1fr\`), or auto. The **\`fr\` unit** distributes available space - like \`1fr 2fr\` means the second column gets twice the space of the first. \`gap\` (formerly \`grid-gap\`) adds spacing between grid items. \`grid-column\` and \`grid-row\` are placed on child elements to make them span multiple tracks. **Grid's \`auto-fit\` and \`minmax()\` combination creates responsive layouts without media queries** - \`grid-template-columns: repeat(auto-fit, minmax(250px, 1fr))\` automatically adjusts the number of columns based on available space.`,
    codeExplanation: `This code creates a **magazine-style layout** using CSS Grid. The container has \`display: grid\` with three columns: the first and third are 1fr each (take up remaining space), and the middle is 3fr (three times wider). \`grid-template-rows: auto 1fr auto\` creates a header, main content area, and footer - the \`1fr\` makes the main content fill remaining vertical space. \`gap: 20px\` adds spacing between grid cells. The .sidebar element uses \`grid-row: 2\` to place it in the second row. \`min-height: 100vh\` ensures the grid is at least the full viewport height. **This is a complete page layout with very little code.**`
  },
  'css-positioning': {
    explanation: `**CSS positioning** controls how elements are placed in relation to their normal position and other elements. There are five position values: **static** (default - elements flow naturally), **relative** (offset from normal position, but original space is preserved), **absolute** (removed from normal flow, positioned relative to nearest positioned ancestor), **fixed** (removed from normal flow, positioned relative to the viewport - stays in place during scroll), and **sticky** (a hybrid - acts as relative until scroll threshold, then becomes fixed).

The **\`top\`, \`right\`, \`bottom\`, \`left\`** properties work differently with each position value. With \`relative\`, they offset from the element's normal position. With \`absolute\` or \`fixed\`, they set distance from the containing element's edges. **\`position: absolute\` is commonly used for overlays, modals, tooltips, and dropdown menus.** When using absolute positioning, the parent must have \`position: relative\` to act as a reference point - otherwise the element positions relative to the viewport. **Always set a positioning context** when using absolute children.`,
    codeExplanation: `This code demonstrates all **five position values**. The .container has \`position: relative\` - this creates a positioning context for the absolutely positioned element inside. .relative-box has \`position: relative; top: 20px; left: 20px\` - it moves 20px down and right from its normal position. .absolute-box has \`position: absolute; top: 0; right: 0\` - it's positioned at the top-right corner of the .container (because .container is its positioned ancestor). .fixed-box has \`position: fixed; bottom: 20px; right: 20px\` - it stays fixed at the bottom-right of the viewport even when scrolling. .sticky-box has \`position: sticky; top: 0\` - it scrolls normally until it reaches the top of the viewport, then sticks there.`
  },
  'css-specificity': {
    explanation: `**CSS Specificity** is the algorithm browsers use to determine which CSS rule takes precedence when multiple rules target the same element. It's a point-based system: **inline styles** (1000 points), **IDs** (100 points each), **classes, attributes, and pseudo-classes** (10 points each), and **elements and pseudo-elements** (1 point each). The \`!important\` declaration overrides everything, but should be avoided in most cases.

For example, \`#header .nav a\` has specificity: 1 ID (100) + 1 class (10) + 1 element (1) = 111. A selector with higher specificity always wins, regardless of order in the stylesheet. **When specificity is equal, the later rule wins.** Common specificity mistakes: using IDs for styling (they're too specific, making overrides difficult), deep nesting in SCSS (creates overly specific selectors), and relying on \`!important\` (creates specificity wars). **Best practice:** keep selectors as simple as possible, use classes for styling, and avoid IDs except for JavaScript hooks.`,
    codeExplanation: `This code demonstrates **specificity in action**. The <p> has four competing styles. The inline style (\`color: orange\`) has the highest specificity (1000 points), so it wins. If it were removed, the ID selector (#myParagraph) would win with 100 points. Without that, the class selector (.highlight) wins with 10 points. The element selector (p) has only 1 point. **Specificity is calculated, not inherited** - even if a parent has a high-specificity selector, a child's own selector takes precedence. The \`!important\` example shows how to override everything (but it's marked as bad practice). **Always check specificity when styles aren't applying as expected.**`
  },
  'css-selectors': {
    explanation: `**CSS Selectors** are patterns used to select and style specific HTML elements. They are the most fundamental part of CSS - without selectors, you can't apply any styles. There are several types: **element selectors** (\`p\`, \`h1\`, \`div\`), **class selectors** (\`.classname\`), **ID selectors** (\`#idname\`), **attribute selectors** (\`[type="text"]\`), **pseudo-classes** (\`:hover\`, \`:first-child\`), and **pseudo-elements** (\`::before\`, \`::after\`).

The **descendant selector** (\`div p\`) selects all <p> inside <div>. The **child selector** (\`div > p\`) selects direct children only. The **adjacent sibling** (\`h2 + p\`) selects the first <p> immediately after <h2>. The **general sibling** (\`h2 ~ p\`) selects all <p> that follow <h2>. **Combinators are powerful** - they let you target elements based on their relationship to other elements. But **overly complex selectors** can be hard to maintain. Prefer simple class-based selectors for most cases.`,
    codeExplanation: `This code demonstrates **different selector types**. \`nav a\` is a descendant selector - it selects all <a> inside <nav>, even if nested deeper. \`nav > a\` is a child selector - it selects only direct <a> children of <nav>. \`h2 + p\` is an adjacent sibling selector - it selects the first <p> right after <h2>. \`[data-active="true"]\` is an attribute selector - it matches any element with that attribute. \`a:hover\` is a pseudo-class that applies when hovering. \`li:first-child\` selects the first list item. \`.highlight::before\` is a pseudo-element that inserts content before the element. **Pseudo-elements (\`::\`) create new virtual elements, while pseudo-classes (\`:\`) describe a state.**`
  },
  'css-animations': {
    explanation: `**CSS animations** bring web pages to life. They make elements move, fade, rotate, and change over time without JavaScript. There are two approaches: **transitions** (smooth changes between two states, triggered by state changes like hover) and **animations** (more complex multi-step sequences defined with \`@keyframes\`).

**Transitions** are simpler - you specify \`transition: property duration timing-function delay\`. For example, \`transition: transform 0.3s ease\` smoothly animates transform changes over 0.3 seconds. **Animations** use \`@keyframes\` to define steps: \`from { opacity: 0; } to { opacity: 1; }\` or percentage-based steps at 0%, 50%, 100%. The \`animation\` shorthand includes name, duration, timing function, delay, iteration count, direction, and fill mode. **Best practices:** use \`transform\` and \`opacity\` for animations (they're GPU-accelerated and performant). Avoid animating \`width\`, \`height\`, \`top\`, \`left\` (they trigger layout recalculations). Prefer \`transform: translate()\` for movement.`,
    codeExplanation: `This code demonstrates both **transitions and animations**. The .button uses \`transition: transform 0.3s ease, box-shadow 0.3s ease\` - on hover, the transform and box-shadow change smoothly. \`ease\` makes the animation start and end gradually. The .fade-in element uses \`@keyframes fadeInSlide\` defined with percentage steps: 0% (starting state), 100% (ending state). \`animation: fadeInSlide 1s ease-out forwards\` applies it - \`forwards\` keeps the final state after animation ends. The .bounce element uses a more complex keyframe with \`transform: scale()\` and \`translateY()\` to create a bouncing effect. \`infinite\` makes it repeat forever. **Always use \`transform\` for position changes** - it's much smoother than animating \`top\` or \`left\`.`
  },
  'css-variables': {
    explanation: `**CSS Custom Properties (CSS Variables)** are values that you define once and reuse throughout your stylesheet. They start with \`--\` and are accessed with \`var()\`. For example: \`:root { --primary-color: #3498db; }\` and \`color: var(--primary-color)\`.

CSS variables are **inherited** through the DOM tree, which means you can redefine them within specific elements or media queries. This makes them powerful for theming and responsive design. **They can be changed at runtime via JavaScript** (\`element.style.setProperty('--primary-color', 'red')\`), which enables dynamic theming without reloading stylesheets. The \`var()\` function accepts a fallback: \`var(--primary, blue)\` uses blue if \`--primary\` is not defined. **Best practice:** define all theme colors, spacing, fonts, and sizing as CSS variables on \`:root\`. This keeps your stylesheet consistent and easy to update. CSS variables are now widely supported in all modern browsers.`,
    codeExplanation: `This code shows **theming with CSS variables**. \`:root\` defines global variables for colors, border radius, and spacing. The variables are named semantically: \`--primary-color\`, \`--bg-color\`, \`--text-color\`, \`--border-radius\`. Inside .card, these variables are used with \`var()\` - for example, \`background: var(--bg-color)\`. The .theme-switcher can change \`--bg-color: #1a1a2e\` and \`--text-color: #eee\` to switch to dark mode. **Variable redefinition is scoped** - changing \`--primary-color\` inside a media query or a specific component only affects that scope. The \`var(--spacing, 8px)\` syntax shows a fallback - if \`--spacing\` isn't defined, 8px is used. **CSS variables are not the same as preprocessor variables** (Sass/LESS) - they're live in the browser and can be changed dynamically.`
  },
  'css-responsive': {
    explanation: `**Responsive CSS** makes websites look good on all devices - from large desktop monitors to small mobile phones. The key idea is that the layout should adapt to the screen size, not the other way around. The most important techniques are: **media queries**, **relative units**, **flexible images**, and **mobile-first design**.

**Media queries** use \`@media (max-width: 768px)\` to apply styles only below a certain width. **Relative units** like \`%\`, \`em\`, \`rem\`, \`vh\`, \`vw\`, and \`fr\` adapt to the viewport or parent size instead of being fixed. **Mobile-first design** means starting with styles for small screens and using \`min-width\` media queries to enhance for larger screens. This approach is simpler and future-friendly. **Best practice:** use \`rem\` for font sizes (respects user's browser settings), \`%\` or \`fr\` for widths, \`vh/vw\` for full-screen sections, and avoid fixed pixel values for layout. Combine flexbox/grid with media queries for truly responsive layouts. **Test on real devices** - browser DevTools device mode is useful but not perfect.`,
    codeExplanation: `This code shows a **mobile-first responsive layout**. The base styles (outside media queries) are for mobile: single column, stacked items, small font sizes. The first media query \`@media (min-width: 768px)\` targets tablets - changes to 2 columns, larger padding. The second \`@media (min-width: 1024px)\` targets desktops - 3 columns, sidebar appears. .container uses \`max-width: 1200px\` with \`margin: 0 auto\` for centering. Images use \`max-width: 100%\` and \`height: auto\` to never overflow their container. \`font-size: clamp(1rem, 2.5vw, 1.5rem)\` fluidly scales font between 1rem and 1.5rem based on viewport width. **Never use \`max-width\` for mobile-first design** - use \`min-width\` so base styles are for mobile and you add complexity for larger screens.`
  },
  'css-pseudo': {
    explanation: `**CSS pseudo-elements** (\`::before\`, \`::after\`, \`::first-line\`, \`::first-letter\`) let you style specific parts of an element or insert virtual elements into the page without adding HTML. They are the most powerful and commonly used: \`::before\` and \`::after\` insert content before or after an element's actual content.

**\`::before\` and \`::after\`** require the \`content\` property to work - even if it's empty (\`content: ""\`). They are commonly used for: decorative elements (icons, quotes), clearfix hacks, tooltips with arrows, gradient overlays, and custom checkboxes. **\`::first-letter\** styles the first letter (used for drop caps in articles). **\`::first-line\** styles the first line (changes as the viewport width changes). **\`::selection\** styles the portion selected by the user. **Pseudo-elements are not real DOM elements** - they can't be targeted by JavaScript, and they don't affect accessibility by default. They're purely visual enhancements. Use two colons (\`::\`) for pseudo-elements and one colon (\`:\`) for pseudo-classes.`,
    codeExplanation: `This code showcases **pseudo-elements in action**. .card::before creates a decorative gradient overlay - it's positioned absolutely, covers the full card, and has a gradient background. The \`content: ""\` is required even though no text is inserted. The .quote block uses ::before and ::after to add decorative quote marks - both have \`position: absolute\` so they don't affect the flow. \`::first-letter\` creates a large drop cap - \`float: left\`, larger font size, and different color. \`::first-line\` makes the first line bold - it only affects the first line which changes dynamically with viewport width. \`::selection\` changes the selection background to a custom color. **Pseudo-elements (\`::\`) create virtual content; pseudo-classes (\`:\`) describe state.**`
  },
  'js-basics': {
    explanation: `**JavaScript (JS)** is the programming language that makes web pages interactive. It can change HTML content, respond to user actions like clicks and keyboard input, communicate with servers, and manipulate the browser. JavaScript runs in the user's browser (client-side) and also on servers (Node.js).

**Key concepts:** Variables store data (\`let\`, \`const\`, \`var\`). Data types include numbers, strings (text), booleans (true/false), arrays (lists), and objects (key-value pairs). Functions are reusable blocks of code. Control flow includes \`if/else\` conditions and loops (\`for\`, \`while\`). **JavaScript is dynamically typed** - you don't declare types, and a variable can change from string to number. The DOM (Document Object Model) is JavaScript's interface to HTML - \`document.querySelector()\` finds elements, \`.textContent\` and \`.style\` modify them, and \`.addEventListener()\` responds to events. **Modern JavaScript (ES6+)** introduced \`const\`/\`let\`, arrow functions, template literals, destructuring, modules, and promises. Always use \`const\` by default, \`let\` when you need to reassign, and never use \`var\`.`,
    codeExplanation: `This code demonstrates **JavaScript basics**. Variables: \`const\` for values that won't change (the button), \`let\` for values that will change (the count). \`document.getElementById()\` finds an element by its ID. \`addEventListener('click', callback)\` runs the callback function when the element is clicked. The \`function() { ... }\` or \`() => { ... }\` (arrow function) is the callback. Inside the callback, \`count++\` increments the counter, and \`counterDisplay.textContent = \\\`Count: \${count}\\\`\` updates the displayed text using a template literal (backticks with \${} interpolation). The \`if (count >= 10)\` condition disables the button by setting \`disabled = true\`. **Template literals with \${} are much cleaner than string concatenation with +.**`
  },
  'js-functions': {
    explanation: `**Functions** are the core building blocks of JavaScript. They are reusable blocks of code that perform a specific task. Functions take **parameters** (inputs), perform operations, and **return** a value. There are several ways to create functions: **function declarations** (\`function add(a, b) { return a + b; }\`), **function expressions** (\`const add = function(a, b) { return a + b; }\`), and **arrow functions** (\`const add = (a, b) => a + b\`).

**Key function concepts:** **Parameters** are listed in the function definition; **arguments** are the actual values passed when calling. The **return** statement specifies the output - if omitted, the function returns \`undefined\`. **Default parameters** (\`function greet(name = "Guest")\`) provide fallback values. **Rest parameters** (\`...args\`) capture any number of arguments into an array. **Higher-order functions** accept or return other functions. **Callbacks** are functions passed as arguments to be called later. **Arrow functions** have a shorter syntax and don't have their own \`this\` binding, which makes them ideal for callbacks. **Best practice:** functions should do one thing and have clear names. Pure functions (same input always gives same output) are easier to test and debug.`,
    codeExplanation: `This code shows **different function types**. \`function greet(name = "Guest")\` is a function declaration with a default parameter - if no argument is passed, "Guest" is used. \`const square = x => x * x\` is an arrow function with implicit return (no braces, no return keyword needed for single expressions). \`const calculate = (a, b, operator)\` is a function expression with a callback - \`operator(a, b)\` calls the function passed as the third argument. The \`...nums\` rest parameter gathers all arguments into an array, and \`.reduce((sum, n) => sum + n, 0)\` sums them up. **.reduce() is a higher-order function** that processes each element and accumulates a result. **Arrow functions are best for short callbacks; function declarations are better for named reusable functions.**`
  },
  'js-arrays': {
    explanation: `**JavaScript arrays** are ordered lists of values. They can hold any data type - numbers, strings, objects, even other arrays. Arrays are zero-indexed, meaning the first element is at index 0. \`const fruits = ["apple", "banana", "orange"]\` creates an array, and \`fruits[0]\` accesses "apple".

**Essential array methods:** \`push()\` adds to the end, \`pop()\` removes from the end, \`unshift()\` adds to the beginning, \`shift()\` removes from the beginning. **Modern array methods** are more powerful: \`map()\` transforms every element and returns a new array, \`filter()\` keeps elements that pass a test, \`reduce()\` reduces all values to a single value, \`find()\` returns the first matching element, \`some()\` checks if any element passes a test, \`every()\` checks if all elements pass. **Important:** \`map()\`, \`filter()\`, and \`reduce()\` do NOT modify the original array - they return new arrays. This is called **immutability** and helps avoid bugs. Use \`forEach()\` when you just need to loop through elements without creating a new array. **Best practice:** prefer \`map/filter/reduce\` over \`for\` loops for data transformation.`,
    codeExplanation: `This code shows **array methods in practice**. \`map()\` transforms each element - here it creates an <li> string for each fruit. The callback \`(fruit, index) => \\\`<li>\${index + 1}. \${fruit}</li>\\\`\` receives both the element and its index. \`filter()\` keeps elements matching the condition - \`num => num % 2 === 0\` keeps only even numbers. \`reduce()\` accumulates a value - \`(sum, num) => sum + num, 0\` sums all numbers starting from 0. \`find()\` returns the first element where the callback returns true - "banana" is the first with length > 5. \`some()\` returns true if ANY element passes the test - here, is there any number > 20? No, so false. \`every()\` returns true only if ALL elements pass. **These methods are chainable** - you can do \`array.filter(...).map(...)\` in sequence.`
  },
  'js-objects': {
    explanation: `**JavaScript objects** are collections of key-value pairs used to represent real-world entities. An object can hold properties (data) and methods (functions). \`const person = { name: "Alice", age: 30, greet() { console.log(\\\`Hi, I'm \${this.name}\\\`); } }\` creates an object with properties \`name\` and \`age\`, and a method \`greet()\`.

**Accessing properties:** dot notation (\`person.name\`) and bracket notation (\`person["name"]\`). Bracket notation is useful when the property name is dynamic or contains special characters. **Adding/updating properties:** \`person.email = "alice@example.com"\` adds a new property; \`person.age = 31\` updates existing. **The \`this\` keyword** inside a method refers to the object that owns the method. **Common operations:** \`Object.keys(obj)\` returns an array of keys, \`Object.values(obj)\` returns values, \`Object.entries(obj)\` returns [key, value] pairs, \`Object.assign({}, source)\` or \`{...source}\` (spread operator) copies an object. **Destructuring** extracts properties into variables: \`const { name, age } = person\`. **Best practice:** use \`const\` for objects (the reference can't change, but properties can). Use spread operator (\`...\`) for copying instead of direct assignment (which creates a reference, not a copy).`,
    codeExplanation: `This code shows **objects and common operations**. A user object is created with name, email, age, and an \`isAdmin\` property. \`Object.keys(user)\` returns \\["name", "email", "age", "isAdmin"\\] - an array of all property names. \`Object.values(user)\` returns the values. \`Object.entries(user)\` returns [key, value] pairs. The spread operator \`{...user, age: 26}\` creates a **shallow copy** of user with age updated - the original user object is not modified. This is important for immutability. \`const { name, email, ...rest }\` is destructuring - it extracts name and email into variables and collects remaining properties into \`rest\`. **The spread operator (\`...\`) creates a shallow copy** - nested objects are still shared by reference. Use \`structuredClone()\` for deep cloning.`,
  },
  'js-dom-manipulation': {
    explanation: `**DOM manipulation** is how JavaScript interacts with HTML. The DOM (Document Object Model) represents the page as a tree of objects that JavaScript can access and modify. Every HTML element is a node in this tree, and JavaScript can add, remove, change, and respond to these nodes.

**Selecting elements:** \`document.getElementById("id")\`, \`document.querySelector(".class")\` (returns first match), \`document.querySelectorAll("div")\` (returns all matches as a NodeList). **Modifying content:** \`element.textContent\` changes text (safe, no HTML parsing), \`element.innerHTML\` changes HTML (dangerous with user input - XSS risk). **Modifying styles:** \`element.style.color = "red"\` changes inline styles. For classes, use \`element.classList.add()\`, \`.remove()\`, \`.toggle()\`, \`.contains()\`. **Creating elements:** \`document.createElement("div")\`, then set content and attributes, then \`parent.appendChild(child)\` or \`parent.prepend(child)\` or \`parent.insertBefore(new, reference)\`. **Removing elements:** \`element.remove()\` (modern) or \`parent.removeChild(child)\` (older). **Performance tip:** batch DOM changes using \`DocumentFragment\` or by hiding the element while making multiple changes - each DOM manipulation triggers a layout recalculation.`,
    codeExplanation: `This code demonstrates **DOM manipulation**. \`document.createElement("div")\` creates a new div element. \`.textContent\` sets its text - this is safe and doesn't parse HTML. \`.className\` sets the class attribute. \`document.getElementById("container").appendChild(newCard)\` adds the new element as a child of the container. The renderCards function processes an array of data using \`map()\` to create HTML strings, then uses \`.innerHTML\` to insert them all at once - this is more performant than appending one by one. **\`textContent\` vs \`innerHTML\`:** use \`textContent\` for user-provided text (prevents XSS attacks). Use \`innerHTML\` only when you control the content. **\`classList.toggle("active")\`** adds the class if missing, removes it if present - perfect for toggling states like dark mode or active navigation.`
  },
  'js-events': {
    explanation: `**JavaScript events** are actions that happen in the browser - clicks, key presses, mouse movements, form submissions, page loads, and more. JavaScript can "listen" for these events and run code in response. This is what makes web pages interactive.

**Adding event listeners:** \`element.addEventListener("click", handler)\` is the modern way. The first argument is the **event type** (\`"click"\`, \`"submit"\`, \`"keydown"\`, \`"mouseover"\`, \`"input"\`, etc.), and the second is the **callback function** (what runs when the event occurs). The callback receives an **event object** (\`e\`, \`event\`) with useful properties: \`e.target\` (the element that triggered the event), \`e.currentTarget\` (the element the listener is attached to), \`e.preventDefault()\` (stops default behavior like form submission), and \`e.stopPropagation()\` (stops event bubbling). **Event bubbling** means events on a child element also trigger listeners on parent elements. You can use this to your advantage with **event delegation** - attaching one listener to a parent instead of many listeners to children. This is more performant and handles dynamically added elements. **Best practice:** use event delegation for lists and tables; use \`passive: true\` for scroll/touch events to improve performance.`,
    codeExplanation: `This code demonstrates **event delegation**. Instead of adding a click listener to each <li>, a single listener is attached to the parent <ul>. \`e.target\` identifies which specific element was clicked. \`e.target.matches(".delete-btn")\` checks if the clicked element has the class "delete-btn" - this handles clicks on the delete button specifically. \`e.target.closest("li")\` finds the closest parent <li> element. \`.remove()\` removes that list item from the DOM. The form handler uses \`e.preventDefault()\` to stop the page from reloading (which is the default form behavior). \`document.querySelector("input").value\` gets the typed text, and a new <li> is created and appended. **Event delegation means the new <li> also works** because the listener is on the parent, which doesn't change. This is much more efficient than adding listeners to each individual item.`,
    codeExplanation: `The second part shows **event properties**. \`e.key\` gives the actual key pressed, \`e.ctrlKey\` checks if Ctrl was held. \`e.clientX / e.clientY\` gives mouse position relative to the viewport. \`e.preventDefault()\` prevents the context menu from appearing on right-click. **Using \`passive: true\`** on scroll/touch events tells the browser you won't call \`preventDefault()\`, allowing the browser to optimize scrolling performance.`
  },
  'js-async': {
    explanation: `**Asynchronous JavaScript** handles operations that take time to complete - like fetching data from an API, reading a file, or waiting for a timer. Instead of stopping (blocking) the entire program while waiting, JavaScript continues running other code and handles the result when it's ready.

**Callbacks** are the traditional approach - a function passed as an argument to be called when the operation completes. But nested callbacks create "callback hell". **Promises** solve this. A Promise is an object representing the eventual completion or failure of an async operation. It has three states: \`pending\`, \`fulfilled\` (resolved), or \`rejected\`. \`fetch()\` returns a Promise. **\`.then()\`** handles fulfillment, **\`.catch()\`** handles rejection, and **\`.finally()\`** runs regardless. **Async/await** (ES2017) is syntactic sugar over Promises - it makes async code look synchronous. An \`async\` function always returns a Promise. \`await\` pauses execution until the Promise resolves. **Error handling** with async/await uses try/catch blocks. **Best practice:** always handle Promise rejections with \`.catch()\` or try/catch. Unhandled rejections can crash your application. Use \`Promise.all()\` to run multiple async operations in parallel, and \`Promise.allSettled()\` when you need results from all regardless of failures.`,
    codeExplanation: `This code compares **Promises vs async/await**. The \`fetchUser(userId)\` function returns a Promise - \`fetch()\` makes an HTTP request, \`.json()\` parses the response. The Promise chain uses \`.then()\` to handle each step. \`.catch()\` catches any error in the chain. The async/await version (\`async function loadUserData(userId)\`) is cleaner - \`await fetch()\` pauses until the fetch completes, then \`await res.json()\` pauses for JSON parsing. try/catch wraps the whole thing. **async/await is always preferred** over raw Promise chains - it's more readable and debugging is easier (stack traces are clearer). The \`fetchUserBad\` example shows what happens **without await** - the function returns a Promise (not the data) immediately. **\`await\` is required to get the actual value.**`
  },
  'js-closures': {
    explanation: `**Closures** are one of JavaScript's most important and frequently misunderstood concepts. A closure occurs when a function "remembers" the variables from its lexical scope even after the outer function has finished executing. In simple terms: a closure gives you access to an outer function's scope from an inner function.

**How it works:** When a function is defined inside another function, the inner function has access to the outer function's variables - even after the outer function has returned. This is because functions in JavaScript form closures around the scope they are created in. **Practical uses:** creating **private variables** (data hiding), **function factories** (functions that create other functions), **partial application** (pre-setting some arguments), and maintaining state in callbacks. **The classic example:** a counter function that maintains a private count variable. Each call increments the count, but the variable can't be accessed from outside. **Common gotcha:** closure in loops - using \`var\` in a loop with async callbacks captures the last value. Fix with \`let\` (which creates a new binding for each iteration) or an IIFE. **Closures are everywhere in JavaScript** - every time you pass a callback or use an event listener, you're likely creating a closure.`,
    codeExplanation: `This code demonstrates **closures**. The \`createCounter()\` function defines \`let count = 0\` (a local variable) and returns an object with increment, decrement, and getCount methods. These methods form a **closure** over the \`count\` variable - even after \`createCounter()\` finishes, the returned methods still have access to \`count\`. The variable is **private** - there's no way to access \`count\` directly from outside. \`createCounter()\` is called twice, creating two **independent** counters (counter1 and counter2) - each has its own private \`count\`. The \`createMultiplier(factor)\` function is a **function factory** - it returns a function that multiplies any number by the given factor. \`double(5)\` returns 10 because the closure remembers \`factor = 2\`. **Closures are the foundation of many JavaScript patterns** - modules, currying, and partial application all rely on closures.`
  },
  'js-prototypes': {
    explanation: `**Prototypes** are JavaScript's mechanism for inheritance and code reuse. Every JavaScript object has an internal link to another object called its **prototype**. When you access a property on an object, JavaScript first checks the object itself, then its prototype, then the prototype's prototype, and so on until it reaches \`Object.prototype\` (which has no prototype). This is called the **prototype chain**.

**Constructor functions** and **classes** both use prototypes under the hood. When you create an instance with \`new Constructor()\`, the instance's prototype is set to \`Constructor.prototype\`. **Methods are typically added to the prototype** rather than the constructor itself - this means all instances share the same method instead of each having their own copy. This is memory efficient. **ES6 classes** are syntactic sugar over prototypes - \`class Dog extends Animal\` creates the same prototype chain. **\`.hasOwnProperty()\`** checks if a property is on the object itself (not the prototype). The **\`instanceof\`** operator checks if an object has a given constructor in its prototype chain. **Modern best practice:** use ES6 classes for object-oriented code. Understanding prototypes is still important for debugging, extending built-in objects, and working with older codebases. **Avoid modifying built-in prototypes** (like Array.prototype) - it can cause conflicts with other code.`,
    codeExplanation: `This code demonstrates **prototypes**. \`function Animal(name)\` is a constructor function - when called with \`new\`, it creates a new object with its prototype set to \`Animal.prototype\`. Methods (speak) are added to \`Animal.prototype\` so all instances share them. \`Dog.prototype = Object.create(Animal.prototype)\` sets up prototypal inheritance - Dog instances get Animal methods through the prototype chain. \`Dog.prototype.constructor = Dog\` fixes the constructor reference (it was pointing to Animal after the \`Object.create\` call). The ES6 class syntax (\`class Cat extends Animal\`) does the same thing more cleanly. \`super(name)\` calls the parent constructor. \`hasOwnProperty("speak")\` returns \`false\` for instances because \`speak\` is on the prototype, not the instance itself. **The prototype chain** for a Dog instance is: instance -> Dog.prototype -> Animal.prototype -> Object.prototype -> null.`
  },
  'js-classes': {
    explanation: `**ES6 Classes** provide a cleaner syntax for creating objects and implementing inheritance in JavaScript. Under the hood, classes are still based on prototypes - the \`class\` keyword is just syntactic sugar. But they make the code more readable and familiar to developers from other OOP languages.

**Key syntax:** \`class Name { constructor() { } method() { } }\`. The \`constructor()\` method is called automatically when you create an instance with \`new Name()\`. **Instance properties** are set inside the constructor using \`this.property = value\`. **Methods** defined inside the class body are added to the prototype. **Static methods** (using \`static\` keyword) are called on the class itself, not on instances - \`Math.round()\` is a static method. **Getters and setters** (\`get prop()\` and \`set prop(value)\`) provide controlled access to properties. **Inheritance** with \`extends\`: \`class Dog extends Animal\` inherits all methods from Animal. \`super()\` calls the parent constructor and must be called before accessing \`this\` in the child constructor. **Private fields** (with \`#\` prefix, like \`#balance\`) are a newer feature - they're truly private and accessible only within the class body. **Best practice:** use classes for domain models and structured data. Keep classes focused on a single responsibility. Prefer composition over deep inheritance chains.`,
    codeExplanation: `This code shows **ES6 class features**. \`class BankAccount\` has a \`#balance\` private field (the \`#\` prefix makes it inaccessible from outside the class). The constructor sets initial values. The \`get balance()\` getter allows reading \`#balance\` like a property (\`account.balance\` not \`account.balance()\`). deposit and withdraw are regular methods. \`class SavingsAccount extends BankAccount\` demonstrates inheritance - \`super(name, initialBalance)\` calls the parent constructor. The \`withdraw\` method is **overridden** - it adds the early withdrawal penalty and then calls \`super.withdraw()\` to reuse the parent logic. \`static validateRoutingNumber(routing)\` is a static method - called as \`SavingsAccount.validateRoutingNumber(...)\`, not on an instance. **Private fields (\`#\`) ensure encapsulation** - the balance can only be modified through deposit/withdraw methods.**`
  },
  'js-modules': {
    explanation: `**JavaScript modules** allow you to split code into separate files, each with its own scope. Before modules, all scripts shared the global scope, leading to naming conflicts and messy dependencies. With modules, variables and functions are private to the file unless explicitly exported.

**Exporting:** \`export const name = value\` (named export), \`export default function() { }\` (default export). A file can have multiple named exports but only one default export. **Named exports** must be imported with matching names in curly braces: \`import { name } from "./file.js"\`. **Default exports** can be imported with any name: \`import AnyName from "./file.js"\`. **Combined imports:** \`import DefaultExport, { named1, named2 } from "./file.js"\`. **Re-exporting:** \`export { name } from "./file.js"\` for barrel files. **Dynamic imports:** \`import("./module.js").then(module => { ... })\` for lazy loading. **\`import.meta.url\`** gives the module's URL. **Key differences from scripts:** modules are automatically \`"use strict"\`, top-level \`this\` is \`undefined\` (not \`window\`), and modules are deferred by default (they don't block HTML parsing). **In the browser:** use \`<script type="module" src="app.js">\`. In Node.js, use \`"type": "module"\` in package.json or \`.mjs\` extension. **Best practice:** one module = one responsibility. Use named exports for utilities and default exports for main components. Avoid circular dependencies.`,
    codeExplanation: `This code shows **ES6 module syntax**. \`math.js\` has a default export (the \`add\` function) and named exports (\`subtract\`, \`multiply\`). \`app.js\` imports all of them. The default export is imported without braces (\`import add\`), named exports require braces (\`import { subtract, multiply }\`). \`import * as mathUtils\` imports ALL exports as a namespace object - accessed as \`mathUtils.add()\`. Dynamic import (\`import("./helpers.js")\`) returns a Promise - useful for lazy loading modules when they're actually needed. \`type="module"\` in the HTML tells the browser to treat the script as a module - it's automatically deferred and has its own scope. **Modules are always strict mode** - undeclared variables throw errors, and \`this\` is undefined in the top-level scope. **Use named exports for related utilities, default exports for the main feature of a file.**`
  },
  'es6-plus': {
    explanation: `**ES6+ (ECMAScript 2015 and later)** introduced major improvements to JavaScript that modern developers use every day. Understanding these features is essential for writing clean, efficient JavaScript.

**Key features:** \`let\` and \`const\` (block-scoped variables replacing \`var\`), **arrow functions** (\`() => {}\` with lexical \`this\`), **template literals** (\`\\\`Hello \${name}\\\`\`), **destructuring** (\`const { name, age } = obj\`, \`const [first, second] = arr\`), **spread operator** (\`{...obj}\`, \`[...arr]\`), **rest parameters** (\`function(...args)\`), **default parameters** (\`function(a = 1)\`), **enhanced object literals** (\`{ name, method() {} }\`), **classes**, **modules**, **Promises**, **Symbols**, **Maps and Sets**, **generators** (\`function*\`), and **Proxy/Reflect**. **ES2017+ features:** async/await, \`Object.entries()\`, \`Object.values()\`, string padding. **ES2018+:** rest/spread for objects, \`Promise.finally()\`, async generators. **ES2019+:** \`Array.flat()\`, \`Array.flatMap()\`, \`Object.fromEntries()\`. **ES2020+:** optional chaining (\`obj?.prop\`), nullish coalescing (\`a ?? b\`), \`Promise.allSettled()\`, \`globalThis\`. **Best practice:** use const by default, let when reassignment is needed. Never use var. Use arrow functions for callbacks. Use template literals instead of string concatenation. Use destructuring for cleaner code.`,
    codeExplanation: `This code demonstrates **ES6+ features**. \`let\` and \`const\` provide block scoping - the \`let i\` inside the if block is separate from the outer \`i\`. **Template literals** (backticks) with \`\${}\` interpolation are cleaner than \`+\` concatenation. **Destructuring** extracts values from objects and arrays in a concise way. **Spread operator** copies arrays (\`[...arr]\`) and objects (\`{...user, age: 26}\`). **Arrow functions** have shorter syntax and inherit \`this\` from the surrounding scope. **Optional chaining** (\`user?.address?.city\`) safely accesses nested properties without throwing if an intermediate value is null/undefined. If \`user.address\` is undefined, the expression returns \`undefined\` instead of throwing. **Nullish coalescing** (\`??\`) returns the right side only if the left is \`null\` or \`undefined\` (not for other falsy values like \`0\` or \`""\`). This is different from \`||\` which treats all falsy values the same. **Modern JavaScript relies heavily on these features** - you'll see them in every codebase.**`
  },
  'js-errors': {
    explanation: `**Error handling** is crucial for building robust JavaScript applications. Without proper error handling, a single unexpected issue can crash your entire application. JavaScript provides the \`try/catch/finally\` statement and the Error object for this purpose.

**\`try { riskyCode() }\`** wraps code that might throw an error. **\`catch (error) { handleError(error) }\`** catches the error and lets you handle it gracefully (show a user-friendly message, log it, retry). The error object has \`.message\`, \`.name\`, and \`.stack\` properties. **\`finally { cleanup() }\`** runs regardless of whether an error occurred - ideal for closing connections, removing loaders, etc. **Creating custom errors:** \`throw new Error("Something went wrong")\` or extend the Error class for specific error types (\`class ValidationError extends Error {}\`). **Error types:** \`Error\`, \`SyntaxError\`, \`TypeError\`, \`ReferenceError\`, \`RangeError\`, \`URIError\`. **Async error handling:** with Promises, use \`.catch()\`; with async/await, use try/catch. Unhandled Promise rejections can be caught with \`window.onunhandledrejection\` (browser) or \`process.on("unhandledRejection")\` (Node.js). **Best practice:** don't catch errors you can't handle. Let them propagate to a global error handler. Always clean up resources in \`finally\`. Throw custom error types for different failure modes. Never swallow errors silently (empty catch blocks). Log errors with sufficient context for debugging.`,
    codeExplanation: `This code shows **error handling patterns**. The \`divide(a, b)\` function throws a custom \`ValidationError\` if b is 0. \`ValidationError extends Error\` creates a custom error type - it sets \`this.name = "ValidationError"\` so you can distinguish it from other errors. The \`try\` block calls risky code. \`catch (error)\` handles different error types: \`if (error instanceof ValidationError)\` shows a specific message for validation failures; otherwise, it logs a generic error. The \`finally\` block always runs - here it just logs "Operation complete". The async function uses \`try/catch\` with \`await\`. If \`fetch()\` fails or \`res.json()\` throws, the catch block handles it. **Always check \`response.ok\`** - fetch doesn't reject on HTTP errors like 404 or 500. You need to check \`if (!res.ok)\` and throw manually. **\`finally\` is guaranteed to run** even if there's a return statement in try or catch.**`
  },
  'react-basics': {
    explanation: `**React** is a JavaScript library for building user interfaces, developed by Meta (Facebook). Its core idea is **components** - reusable, self-contained pieces of UI that manage their own state. Instead of manually manipulating the DOM, you describe what the UI should look like for any given state, and React efficiently updates the DOM when state changes.

**Core concepts:** **JSX** (JavaScript XML) looks like HTML but is written inside JavaScript. JSX expressions use \`{}\` curly braces. **Components** are JavaScript functions that return JSX. **Props** are read-only data passed from parent to child components. **State** (\`useState\` hook) is data that changes over time - when state updates, the component re-renders. **The Virtual DOM** is React's performance optimization - it calculates the difference between the old and new virtual DOM trees, then applies only the minimal changes to the real DOM. **React is declarative** - you describe what the UI should look like, not how to change it. This is the opposite of imperative jQuery-style manipulation. **Best practice:** components should be small and focused. One component = one responsibility. Use meaningful names. Keep components pure (same props always produce the same output). Lift state up when multiple components need to share it.`,
    codeExplanation: `This is a **basic React component**. \`import React, { useState }\` imports the React library and the useState hook. The \`Counter()\` function is a component. \`const [count, setCount] = useState(0)\` is the useState hook - it returns an array with the current state (\`count\`) and a setter function (\`setCount\`). \`0\` is the initial value. When \`setCount(count + 1)\` is called, React updates the state and re-renders the component. The JSX returned uses \`{}\` to embed JavaScript expressions - \`{count}\` displays the current count value. \`onClick={() => setCount(count + 1)}\` is an event handler - the arrow function calls setCount when the button is clicked. **\`useState\` triggers re-renders** - when state changes, React re-runs the component function to get the new JSX. Each click updates count, which updates the displayed value. **This is declarative** - you never write DOM manipulation code.**`
  },
  'react-components': {
    explanation: `**React components** are the building blocks of any React application. They are reusable, self-contained pieces of UI that can manage their own state and receive data through props. There are two types: **functional components** (modern, using hooks) and **class components** (older style, rarely used in new code). Modern React uses only functional components.

**Component structure:** A component is a JavaScript function that takes \`props\` as input and returns JSX describing the UI. **Props** are read-only - a component should never modify its props. Props flow **downward** from parent to child. **Composition** is React's way of combining components - smaller components are nested inside larger ones. \`children\` (via \`props.children\`) allows passing JSX content between opening and closing tags. **Component design principles:** single responsibility (one component does one thing), reusability (design components to be used in multiple contexts), and separation of concerns (UI logic is co-located with markup). **Container vs Presentational:** container components handle data/logic; presentational components only render UI. **Best practice:** default export for the main component in a file. Use named exports for sub-components or utilities. Keep files small - one component per file. Use TypeScript interfaces for props to catch type errors early. Props should be simple and predictable. Avoid prop drilling (passing props through many levels) - use React Context or a state management library instead.`,
    codeExplanation: `This code shows **component composition**. \`UserCard\` is a reusable component that accepts \`name\`, \`email\`, \`avatar\`, and \`children\` as props. The \`children\` prop is whatever JSX is placed between \`<UserCard>\` and \`</UserCard>\` - here it's the \`<p>Joined: January 2024</p>\` element. The \`UserProfile\` component renders multiple \`UserCard\` components with different data. Props are passed as HTML-like attributes (\`name={user.name}\`). The \`user\` data comes from an array, and \`.map()\` creates a UserCard for each user. **Each item in a list needs a \`key\` prop** - React uses it to track which items change. Use a unique ID from the data (\`key={user.id}\`). Avoid using array index as key (causes issues with reordering). **\`children\` is a special prop** that enables flexible, composable components. A component doesn't need to know what its children are - it just renders them. This is the foundation of React's composition model.**`
  },
  'react-hooks': {
    explanation: `**React Hooks** are functions that let you "hook into" React state and lifecycle features from functional components. Introduced in React 16.8 (2019), hooks replaced class components as the primary way to write React components. The most common hooks are \`useState\`, \`useEffect\`, \`useContext\`, \`useRef\`, \`useMemo\`, and \`useCallback\`.

**Rules of Hooks:** hooks must be called at the top level of a component (not inside loops, conditions, or nested functions). Hooks must be called in the same order on every render. Custom hooks (functions starting with \`use\`) allow extracting and reusing stateful logic. **\`useState\`** manages local state. **\`useEffect\`** handles side effects - data fetching, subscriptions, DOM manipulation, timers. The dependency array (\`[]\`) controls when the effect runs: empty = once on mount, omitted = after every render, with values = when those values change. The cleanup function (returned from the effect) runs on unmount or before re-running. **\`useContext\`** accesses React context without prop drilling. **\`useRef\`** holds a mutable value that persists across renders without causing re-renders. **\`useMemo\`** memoizes computed values. **\`useCallback\`** memoizes function references. **Best practice:** keep effects focused on one concern. Extract complex logic into custom hooks. Don't over-optimize with useMemo/useCallback - profile first. Use the exhaustive-deps ESLint rule to catch missing dependencies.`,
    codeExplanation: `This code demonstrates **common hooks**. \`useState(false)\` manages the open/closed state - \`isOpen\` is the current value, \`setIsOpen\` updates it. \`useEffect\` with \`[]\` dependency runs once when the component mounts - it adds a scroll event listener. The cleanup function (\`return () => window.removeEventListener(...)\`) removes the listener when the component unmounts, preventing memory leaks. \`useRef(null)\` creates a ref that holds a DOM element - \`ref={panelRef}\` attaches it to the div, and \`panelRef.current\` gives access to the actual DOM node. The click handler checks if the click was outside the panel (using \`panelRef.current?.contains(e.target)\`) and closes it. \`useMemo(() => expensiveCalculation(count), [count])\` memoizes the calculation result - it only re-computes when \`count\` changes. **useMemo and useCallback are optimization tools** - don't wrap everything with them. Only use when you have measurable performance issues. The dependency array is critical - missing dependencies cause stale closures.**`
  },
  'react-state': {
    explanation: `**State management** in React is about handling data that changes over time. React provides several built-in tools: \`useState\` for local component state, \`useReducer\` for complex state logic, \`useContext\` for shared state across component trees, and \`useRef\` for values that shouldn't trigger re-renders. For larger applications, external libraries like Redux, Zustand, or Jotai are commonly used.

**\`useState\`** is the simplest - good for independent values like form inputs, toggles, counters. **\`useReducer\`** is better when state updates depend on previous state or when the logic is complex - it uses a reducer function (current state + action -> new state) similar to Redux. **\`useContext\`** + \`useReducer\` together can replace Redux for many apps (no external library needed). **State should live as close as possible** to where it's needed. If only one component needs a piece of state, keep it local. If multiple sibling components need it, "lift state up" to their common parent. If many components across the tree need it, use Context or a state management library. **Key concepts:** state updates are **asynchronous** - React batches updates for performance. State should be treated as **immutable** - don't mutate objects/arrays directly, create new copies. For arrays: use \`[...array, newItem]\` to add, \`array.filter()\` to remove, \`array.map()\` to update. **Best practice:** keep state minimal - derive values from existing state rather than storing them separately. A loading state and an error state shouldn't be separate booleans - use a single status: "idle" | "loading" | "success" | "error".`,
    codeExplanation: `This code shows **state management patterns**. \`useReducer\` manages a todo list with a reducer function that handles "ADD_TODO", "TOGGLE_TODO", and "DELETE_TODO" actions. Each action has a \`type\` and a \`payload\`. The reducer returns a new state based on the action - it doesn't mutate the existing state. \`todos.filter(t => t.id !== action.payload)\` creates a new array without the deleted todo (immutability). Context (\`createContext\` + \`useContext\`) allows any nested component to access the todo data without prop drilling. \`TodoProvider\` wraps the application and provides the state and dispatch function. \`dispatch({ type: "ADD_TODO", payload: text })\` is the only way to update state - components never manipulate state directly. **The reducer pattern makes state changes predictable and testable** - the reducer is a pure function with no side effects. **Lift state to the level where it's needed** - here, state is in the Provider because multiple components (input, list, stats) need access.**`
  },
  'react-effects': {
    explanation: `**\`useEffect\`** is the React hook for handling side effects - operations that affect things outside the component, like data fetching, subscriptions, timers, DOM manipulation, and logging. Side effects cannot run during rendering because rendering should be pure (no side effects). That's why React provides useEffect to run them after rendering is complete.

**The dependency array** is the most important part of useEffect. It tells React when to re-run the effect: \`useEffect(() => { ... })\` - runs after every render (avoid when possible). \`useEffect(() => { ... }, [])\` - runs once after the first render (component mount). \`useEffect(() => { ... }, [dep1, dep2])\` - runs when dep1 or dep2 change. **The cleanup function** is returned from the effect and runs before the component unmounts or before re-running the effect. It's essential for canceling subscriptions, clearing timers, and aborting fetch requests. **Common patterns:** fetching data on mount (with loading/error states), subscribing to WebSocket/events (with cleanup), syncing state with localStorage (with debouncing), and updating the document title. **Race conditions** in async effects: a fast subsequent request might resolve after a slow previous one, displaying stale data. Fix with a cleanup flag or AbortController. **Best practice:** keep effects focused on one concern. If an effect does multiple things, split it. Always include all values used inside the effect in the dependency array (use the ESLint exhaustive-deps rule). Consider using custom hooks to encapsulate complex effect logic.`,
    codeExplanation: `This code shows **useEffect patterns**. The first effect fetches data on mount (empty \`[]\` dependency). \`AbortController\` is used for cleanup - if the component unmounts before the fetch completes, \`abort()\` cancels the request. This prevents memory leaks and race conditions. The \`loading\`, \`data\`, \`error\` state pattern handles all three states of the async operation. The second effect (\`useEffect(() => { ... }, [count])\`) syncs \`count\` to localStorage whenever it changes - this makes the state persist across page reloads. The third effect sets up a mouse move event listener on mount and cleans it up on unmount (removes the event listener). **The cleanup function is critical** - without it, event listeners, subscriptions, and timers would accumulate, causing memory leaks and bugs. Mutiple effects are better than one large effect - each effect should handle one concern. The dependency array \`[count]\` ensures the localStorage sync only runs when count changes, not on every render. **Always handle loading, success, and error states** when fetching data.**`
  },
  'react-forms': {
    explanation: `**React forms** handle user input differently from plain HTML. In HTML, form state is managed by the DOM (the browser remembers what's typed). In React, you typically use **controlled components** where React state is the single source of truth - the input value comes from state, and changes update state through \`onChange\` handlers.

**Controlled components:** \`<input value={state} onChange={e => setState(e.target.value)} />\`. The input always displays the current state value, and any keystroke updates the state. This gives you full control - you can validate, transform, or format the input as the user types. **Uncontrolled components** use \`useRef\` to read values from the DOM when needed (like a regular HTML form). Use them for simple cases or when integrating with non-React code. **Form validation** can be done onChange (immediate feedback), onBlur (when leaving the field), or onSubmit (when submitting). A common pattern: maintain a \`touched\` object to track which fields have been visited and only show errors for touched fields. **Form libraries** like React Hook Form or Formik handle complex forms with validation, submission, and error handling. **Best practice:** group related form fields. Use labels for accessibility. Show errors clearly and near the relevant field. Validate on both client and server. Disable the submit button while submitting. Show loading states during submission. Use \`type="submit"\` for submit buttons to allow keyboard submission (Enter key).`,
    codeExplanation: `This is a **controlled form** in React. Each input has \`value\` (from state) and \`onChange\` (updates state). The \`useState\` hook manages \`formData\` as an object with all form fields. \`handleChange\` uses \`[e.target.name]\` (computed property name) to update the correct field without needing separate handlers. \`e.target.type === "checkbox"\` handles the checkbox differently - checkboxes use \`checked\` instead of \`value\`. Validation runs on every change (\`validate(formData)\`) and updates the \`errors\` state. The submit handler calls \`e.preventDefault()\` (stops page reload), validates again, and shows a message. **Controlled components give you real-time control** - you can validate as the user types, disable the button if invalid, or show character counts. The tradeoff is more code per input, but the predictability and control are worth it for most forms.**`
  },
  'react-router': {
    explanation: `**React Router** is the standard library for navigation and routing in React applications. It enables single-page application (SPA) behavior where navigation happens without full page reloads - only the necessary components re-render. The latest version is React Router v6+.

**Core components:** \`<BrowserRouter>\` wraps the entire app and enables routing. \`<Routes>\` and \`<Route>\` define which component renders at which URL path. \`<Link>\` creates navigation links (renders an <a> tag but prevents full page reload). \`<NavLink>\` is like \`<Link>\` but adds active class styling. \`<Outlet>\` renders child routes in layout components. **Nested routes** let you create layouts with shared UI (header, sidebar, footer) that persist while child content changes. **Route parameters** (\`:id\` in the path) capture dynamic values from the URL, accessed via \`useParams()\`. **Query parameters** are handled with \`useSearchParams()\`. **Programmatic navigation** uses \`useNavigate()\`. **Protected routes** check authentication before allowing access to certain pages. **Best practice:** organize routes in a single central file. Use lazy loading with \`React.lazy()\` and \`Suspense\` for code splitting. Use relative links within nested routes. Handle 404s with a catch-all \`<Route path="*" element={<NotFound />} />\`. Keep URLs clean and meaningful (avoid query strings for primary data).`,
    codeExplanation: `This code shows **React Router v6 setup**. \`BrowserRouter\` wraps the entire app. \`Routes\` and \`Route\` define the routing table. \`element\` prop specifies the component for each path. \`path="/"\` is the home page, \`path="/about"\` is about, etc. The \`"/products/:id"\` route uses a **URL parameter** (\`:id\`) - accessed via \`useParams()\` in the ProductDetail component. Nested routes under \`"/dashboard"\` use \`<Outlet />\` in the DashboardLayout component - the layout (sidebar, header) persists while the child content (\`/dashboard\` or \`/dashboard/settings\`) changes. \`<NavLink>\` provides automatic active styling via the \`className\` callback function - \`isActive ? "active" : ""\`. The catch-all \`path="*"\` renders the NotFound component for any undefined route. \`useNavigate()\` enables programmatic navigation - \`navigate("/login")\` redirects after logout. \`<Navigate to="/login" replace />\` is the declarative version for redirects (replace prevents back-button from returning to the protected page). **Nested routes with \`<Outlet>\` reduce code duplication** - the layout is defined once and shared across all dashboard pages.**`
  },
  'react-context': {
    explanation: `**React Context** provides a way to share data across the component tree without passing props through every level (prop drilling). It's built into React and requires no external libraries. Context is ideal for global data like themes, user authentication, language preferences, and UI state.

**How it works:** \`createContext(defaultValue)\` creates a context object. A \`<Context.Provider value={...}>\` component wraps the subtree that needs access. Any component inside the provider can use \`useContext(ContextName)\` to read the value. **Common pattern:** create a custom provider component that manages the state and provides it through context. This keeps the context logic encapsulated. **Performance consideration:** when the provider's value changes, ALL consumers re-render, even if they only read a part of the value that didn't change. Solutions: split contexts (separate context for each concern) or use \`useMemo()\` for the value object. **When to use Context:** themes, auth, localization, global UI state (modals, toasts), and when many components at different nesting levels need the same data. **When NOT to use Context:** for data that only a few closely-related components need (just pass props), for frequently updating data (causes too many re-renders), as a replacement for lifting state up. **Context vs Redux:** Context is simpler and built-in; Redux offers more structure, middleware, DevTools, and performance optimizations. Start with Context + useReducer and migrate to Redux only when needed.`,
    codeExplanation: `This code shows a **Context-based auth system**. \`AuthContext\` is created with \`createContext\`. \`AuthProvider\` is a custom provider that manages auth state (\`user\`, \`login\`, \`logout\`) and provides them via \`value\`. Use \`useMemo\` to memoize the value object - this prevents unnecessary re-renders of consumers whenever the provider re-renders for other reasons. \`useAuth\` is a custom hook that wraps \`useContext(AuthContext)\` and throws an error if used outside the provider - this is a good practice because it catches misuse early. The LoginStatus component consumes the context: \`const { user, login, logout } = useAuth()\`. Multiple providers can be nested - for example, wrapping the app with both \`<AuthProvider>\` and \`<ThemeProvider>\`. **Each context should have its own provider file** - this keeps the code organized. The \`useMemo\` dependency array \`[user]\` ensures the value object only changes when \`user\` changes. **Without \`useMemo\`, every render of AuthProvider would create a new value object, causing all consumers to re-render.**`
  },
  'react-performance': {
    explanation: `**React performance optimization** focuses on minimizing unnecessary re-renders and reducing the amount of work done during rendering. React is already fast for most applications, but optimization becomes important for complex UIs with large lists, frequent updates, or heavy computations.

**Key techniques:** \`React.memo()\` wraps a component to skip re-rendering if its props haven't changed (shallow comparison). \`useMemo()\` memoizes expensive calculations - the value is only recomputed when dependencies change. \`useCallback()\` memoizes function references to prevent child components from re-rendering unnecessarily. \`useTransition()\` marks state updates as non-urgent (keeps the UI responsive during expensive updates). **Code splitting** with \`React.lazy()\` and \`Suspense\` loads components only when needed, reducing initial bundle size. **Virtualization** (react-window, react-virtuoso) renders only visible items in long lists - crucial for performance with thousands of items. **Avoiding common pitfalls:** creating new objects/arrays/functions in render (breaks memoization), lifting too much state up (causes too many re-renders), overusing Context, and unnecessary re-renders of large subtrees. **The profiling approach:** measure first (React DevTools Profiler), identify bottlenecks, then optimize. Don't optimize prematurely. **Best practice:** use \`React.memo\` for leaf components that render often with the same props. Use \`useMemo\` for expensive computations. Keep component state as local as possible. Move state down the tree. Extract expensive parts into separate memoized components.`,
    codeExplanation: `This code demonstrates **performance optimization patterns**. \`ExpensiveList\` is wrapped with \`React.memo\` - it only re-renders if its \`items\` or \`onToggle\` props change. \`onToggle\` uses \`useCallback\` with \`[setItems]\` dependency - the same function reference is preserved across renders, so \`ExpensiveList\` won't re-render just because the parent re-rendered. \`useMemo(() => items.filter(...), [items, searchTerm])\` memoizes the filtered result - it only recomputes when items or searchTerm change. \`useTransition\` wraps the search update (\`startTransition(() => setSearchTerm(value))\`) - this marks the search filter update as low priority, keeping the input responsive during heavy filtering. \`isPending\` is true while the transition is pending - useful for showing a spinner. The toggle item uses \`useCallback(() => onToggle(item.id), [onToggle, item.id])\` in the child component to prevent unnecessary re-renders of list items. **The key insight:** memoization works by reference equality - always use \`useCallback\` for functions and \`useMemo\` for objects passed as props to memoized children. Without memoization, a new function/object is created on every render, making \`React.memo\` useless.**`
  },
  'react-testing': {
    explanation: `**React testing** ensures your components work correctly. The standard approach combines **unit tests** (testing functions and hooks in isolation), **component tests** (testing components with simulated user interactions), and **integration tests** (testing how components work together). The most popular testing tools are Vitest (or Jest) with React Testing Library.

**React Testing Library** encourages testing components from the user's perspective. Instead of testing implementation details (component state, internal methods), you test what the user sees and interacts with. Key queries: \`getByRole()\` (preferred - finds by ARIA role), \`getByText()\`, \`getByLabelText()\` (for form inputs), \`getByTestId()\` (last resort, uses \`data-testid\`). **User events** (\`@testing-library/user-event\`) simulates real user interactions like typing, clicking, and tabbing - it's more realistic than \`fireEvent\`. **Async testing:** \`waitFor()\` and \`findBy*\` queries (which return Promises) handle async behavior like data fetching. **Mocking:**

- \`vi.mock("../api")\` mocks an entire module
- \`vi.spyOn(obj, "method")\` spies on specific methods
- Mock service worker (MSW) intercepts network requests at the protocol level - best for API mocking

**Best practices:** test behavior, not implementation. Use accessible queries (\`getByRole\`, \`getByLabelText\`). Test error states and edge cases. Don't test the library (don't test if useState or useEffect work). Keep tests simple and readable. Use \`screen\` object methods for queries (more resilient to refactoring). One assertion per test or logical group of related assertions. Cover the most important user flows.`,
    codeExplanation: `This code shows **React Testing Library tests**. \`render(<TodoApp />)\` renders the component in a test environment. \`screen.getByRole("textbox", { name: /new todo/i })\` finds the input by its accessible role and label text - this is the recommended approach. \`await user.type(input, "Learn testing{Enter}")\` types into the input and presses Enter - \`userEvent\` simulates real keyboard events. \`await screen.findByText("Learn testing")\` waits for the text to appear (async, because adding a todo might involve state updates). \`expect(screen.getByRole("button", { name: /delete/i })).toBeInTheDocument()\` verifies the delete button exists. \`expect(screen.queryByText("Learn testing")).not.toBeInTheDocument()\` checks that the text is NOT present after deletion - \`queryBy\` doesn't throw, it returns null. \`vi.spyOn(Storage.prototype, "getItem")\` mocks localStorage. \`expect(location.pathname).toBe("/")\` uses \`vi.mock("react-router-dom")\` to verify navigation. **Always use \`userEvent\` over \`fireEvent\`** - \`userEvent\` is more realistic and catches issues like disabled buttons or focus management that \`fireEvent\` misses.**`
  },
  'typescript-basics': {
    explanation: `**TypeScript** is a superset of JavaScript that adds optional static typing. It compiles to plain JavaScript and catches type-related errors at compile time (before the code runs). This makes code more predictable, self-documenting, and easier to refactor. TypeScript is maintained by Microsoft and is the standard for professional JavaScript development.

**Core concepts:** **Type annotations** (\`const name: string = "hello"\`) declare the expected type. **Basic types:** \`string\`, \`number\`, \`boolean\`, \`null\`, \`undefined\`, \`void\`, \`any\` (avoid). **Arrays:** \`number[]\` or \`Array<number>\`. **Objects:** \`{ name: string; age: number }\`. **Interfaces** (\`interface Person { name: string }\`) and **types** (\`type Person = { name: string }\`) define object shapes. **Union types:** \`string | number\` (can be either). **Optional properties:** \`name?: string\`. **Generics:** \`function identity<T>(arg: T): T { return arg }\` - type-safe and reusable. **\`TypeScript doesn't change how JavaScript runs** - all types are erased during compilation. It's a development tool that catches mistakes early. The stricter your TypeScript config, the more errors it catches. **Best practice:** enable \`strict: true\` in tsconfig. Avoid \`any\` (use \`unknown\` if you truly don't know the type). Prefer interfaces for object shapes (they're extendable). Use type aliases for unions, intersections, and utility types. Let TypeScript infer types when the type is obvious (like \`const name = "hello"\`).`,
    codeExplanation: `This code shows **TypeScript features**. \`interface User\` defines the shape of a user object with required (\`id\`, \`name\`, \`email\`) and optional (\`age?\`) properties. \`type Status\` is a union type - \`"active" | "inactive" | "pending"\` means it can only be one of these three string values. \`function greet(user: User): string\` has parameter and return type annotations. The generic function \`function getProperty<T, K extends keyof T>(obj: T, key: K): T[K]\` uses a generic constraint (\`K extends keyof T\`) - \`keyof T\` is a union of all property keys of T. This ensures only valid property names can be passed. \`Partial<User>\` is a utility type that makes all properties optional - \`Partial<User>\` is equivalent to \`{ id?: number; name?: string; ... }\`. \`Pick<User, "id" | "name">\` creates a type with only those properties. **TypeScript catches errors at compile time** - trying to access \`user.nonExistent\` would be a compile error. **Generics provide type safety without sacrificing flexibility** - \`getProperty(user, "id")\` returns \`number\`, and \`getProperty(user, "name")\` returns \`string\`.**`
  },
  'typescript-advanced': {
    explanation: `**Advanced TypeScript** features enable sophisticated type systems that model complex data relationships and enforce business rules at compile time. These features are essential for building large-scale applications with strong type safety.

**Key advanced features:** **Discriminated unions** - types with a common literal property (discriminant) that TypeScript can narrow using switch/if statements. **Template literal types** (\`\`\`type EventName = \`on\${Capitalize<string>}\`\`\`) - create types by manipulating string literals. **Conditional types** (\`T extends U ? X : Y\`) - types that depend on other types. **Mapped types** (\`{ [K in keyof T]: T[K] }\`) - transform existing types. **Infer keyword** - extracts types from within conditional types. **Satisfies operator** - validates type without changing the inferred type. **branded types** - create nominal typing by intersecting with a unique brand (\`type UserId = string & { __brand: "UserId" }\`). **Typed \`this\`** - specify \`this\` parameter type in functions. **Utility types:** \`Awaited<T>\`, \`ReturnType<T>\`, \`Parameters<T>\`, \`InstanceType<T>\`, \`NonNullable<T>\`, \`Record<K, V>\`. **Best practice:** use advanced types to model business rules, not just data shapes. Keep type complexity manageable - overly complex types hurt readability. Extract reusable type utilities. Use \`satisfies\` instead of type annotations when you want inference with validation. Document complex types with comments. Test edge cases of your types.`,
    codeExplanation: `This code demonstrates **advanced TypeScript patterns**. \`type Result<T, E = Error>\` is a **discriminated union** with \`status\` as the discriminant - TypeScript narrows the type when you check \`result.status === "success"\`. Inside the \`if\` block, \`result.data\` is available and typed. \`type DeepReadonly<T>\` is a **recursive mapped type** - it uses conditional types (\`T extends object ? ... : T\`) to deeply make all properties readonly. \`type ExtractPromise<T>\` uses the **\`infer\` keyword** to extract the resolved type from a Promise - \`ExtractPromise<Promise<number>>\` evaluates to \`number\`. \`defineConfig\` uses the **\`satisfies\` operator** - it validates that the return type matches \`Config\` while preserving the literal type inference. Without \`satisfies\`, \`config.port\` would be typed as \`number\`; with \`satisfies\`, it's \`3000\` (literal type). \`type UserId = string & { readonly __brand: unique symbol }\` creates a **branded type** - you can't accidentally pass a plain string where a UserId is expected. **Discriminated unions are the most practical advanced feature** - they make impossible states impossible and exhaustively handle all cases.**`
  },
  'typescript-generics': {
    explanation: `**Generics** in TypeScript allow you to create reusable components that work with multiple types while maintaining type safety. Instead of using \`any\` (which loses type information), generics capture the type as a parameter and preserve it throughout the function or class.

**Syntax:** \`function identity<T>(arg: T): T { return arg }\` - \`T\` is a **type parameter** that captures the actual type passed in. When you call \`identity(42)\`, T becomes \`number\`. When you call \`identity("hello")\`, T becomes \`string\`. **Multiple type parameters:** \`function pair<A, B>(a: A, b: B): [A, B]\`. **Generic constraints:** \`<T extends HasLength>\` restricts T to types that satisfy a certain shape. **Generic interfaces:** \`interface ApiResponse<T> { data: T; error: null }\` creates flexible, reusable types. **Generic classes:** \`class Stack<T> { push(item: T): void; pop(): T | undefined }\`. **Default type parameters:** \`function createArray<T = string>(length: number, value: T): T[]\`. **Type inference vs explicit:** TypeScript usually infers generic types automatically. You can also specify them explicitly: \`identity<number>(42)\`. **Practical examples:** \`Promise<T>\` (resolve value type), \`Array<T>\` (element type), \`React.ComponentProps<typeof Button>\` (extract props type). **Best practice:** use descriptive names for type parameters (\`TItem\` instead of \`T\` for items). Constrain generics when needed (\`extends\`). Use generics to create reusable hooks, utilities, and components. Avoid over-generalizing - if a type only has one use case, it doesn't need to be generic.`,
    codeExplanation: `This code shows **generics in practice**. \`function getFirst<T>(arr: T[]): T | undefined\` is a generic function - it works with any array type and returns the element type. \`getFirst([1, 2, 3])\` infers T as \`number\`, returning \`number | undefined\`. \`interface ApiResponse<T>\` is a generic interface - \`{ data: T; status: number; message: string }\`. Different API endpoints return different data shapes (\`User\` vs \`Product[]\`), so the generic \`T\` captures the specific response type. \`async function fetchApi<T>(url: string): Promise<ApiResponse<T>>\` is a generic async function - the caller specifies the expected response type. \`fetchApi<User>("/api/user/1")\` returns \`Promise<ApiResponse<User>>\`, so \`response.data\` is typed as \`User\`. **\`extends\` constraints** - \`<T extends { id: number }>\` requires T to have an \`id\` property. This is common for database entities. **Generic types are inferred from usage** - in \`fetchApi<User>\`, \`T\` is explicitly \`User\`. In \`getFirst([1, 2, 3])\`, \`T\` is inferred as \`number\`. **Generics make API clients type-safe** - you get autocomplete and compile-time checking for API response shapes.**`
  },
  'typescript-utility-types': {
    explanation: `**TypeScript utility types** are built-in generic types that transform existing types into new types. They're part of the TypeScript standard library and help you avoid writing complex type transformations from scratch. The most commonly used utility types manipulate object properties and function signatures.

**Key utility types:** \`Partial<T>\` makes all properties optional. \`Required<T>\` makes all properties required. \`Readonly<T>\` makes all properties readonly. \`Pick<T, K>\` creates a type with only the specified keys. \`Omit<T, K>\` creates a type without the specified keys. \`Record<K, V>\` creates an object type with keys K and values V. \`Exclude<T, U>\` removes types from a union. \`Extract<T, U>\` extracts types from a union. \`NonNullable<T>\` removes null and undefined. \`ReturnType<T>\` extracts the return type of a function. \`Parameters<T>\` extracts parameter types as a tuple. \`Awaited<T>\` unwraps Promises. \`ConstructorParameters<T>\` extracts constructor parameter types. **Composing utilities:** \`Partial<Pick<User, "name" | "email">>\` makes only those specific fields optional. **Custom utilities:** you can create your own using mapped types, conditional types, and template literal types. **Best practice:** utility types reduce boilerplate and make type transformations clear and readable. Use \`Pick\` and \`Omit\` instead of redefining similar interfaces. Use \`Record<K, V>\` instead of index signatures when keys are known. Use \`ReturnType\` and \`Parameters\` to extract types from existing functions rather than duplicating them. Prefer utility types over manual type transformations.`,
    codeExplanation: `This code demonstrates **utility type usage**. The \`User\` interface has four required properties. \`Partial<User>\` creates a type where all properties are optional - useful for update operations where you only send changed fields. \`Pick<User, "name" | "email">\` creates a type with only name and email - useful for registration forms. \`Omit<User, "passwordHash">\` removes the passwordHash field - useful for API responses (never expose passwords). \`Record<Status, string>\` creates an object type with Status values as keys (\`"active"\`, \`"inactive"\`, \`"pending"\`) and string values - \`{ active: string; inactive: string; pending: string }\`. \`ReturnType<typeof fetchUser>\` extracts the return type of the \`fetchUser\` function (\`Promise<User>\`). \`Parameters<typeof fetchUser>\` extracts the parameter types (\[number\]). \`Awaited<ReturnType<typeof fetchUser>>\` gives the resolved type (\`User\`). **Utility types compose well** - \`Partial<Pick<User, "email">>\` makes only the email field optional. **Use utility types instead of redefining types** - they keep your code DRY and maintain type consistency.**`
  },
  'typescript-interfaces': {
    explanation: `**TypeScript Interfaces** define the shape of objects. They are the primary way to describe contracts in your code - what properties and methods an object should have, and their types. Interfaces support inheritance, merging, and can describe both data shapes and function signatures.

**Interface vs Type:** interfaces can be **extended** (\`extends\`) and **merged** (declaration merging - same interface name adds properties). Type aliases cannot be merged but can represent unions, intersections, and primitive types. **\`interface User extends Person, HasId\`** inherits from multiple interfaces. **Declaration merging:** if you declare \`interface User { name: string }\` and later \`interface User { age: number }\`, the final User has both properties. This is useful for extending third-party types. **\`readonly\` modifier** makes properties immutable after creation (\`readonly id: number\`). **\`? \` modifier** marks optional properties. **Index signatures** (\`[key: string]: unknown\`) describe objects with dynamic keys. **Call/construct signatures** define function and constructor types. **Generic interfaces** (\`interface ApiResponse<T> { data: T }\`). **Best practice:** prefer interfaces for public API contracts and object shapes that might be extended. Use type aliases for unions, intersections, and utility types. Use \`interface\` for React component props and state. Name interfaces with PascalCase. Keep interfaces focused on one responsibility. Use \`extends\` instead of copy-pasting shared properties. Mark input-only properties as \`readonly\` to signal they shouldn't be mutated.`,
    codeExplanation: `This code shows **interface features**. \`interface Animal\` has \`name\` and \`speak()\` method. \`interface Dog extends Animal\` inherits both - \`Dog\` has \`name\`, \`speak()\`, AND \`breed\`. \`interface Pet\` adds \`owner\`. \`interface Dog extends Animal, Pet\` demonstrates **multiple inheritance** - Dog gets properties from both Animal and Pet. \`interface JsonSerializable\` shows a **method signature** - \`toJSON(): string\`. The \`Dog\` class \`implements Dog, JsonSerializable\` - implements both interfaces. \`interface ApiConfig\` shows **readonly** (\`readonly baseUrl\`), **optional** (\`timeout?\`), and **index signature** (\`[key: string]: unknown\` for additional properties). Declaration merging happens on lines 28 and 31 - both declare \`interface UserResponse\`, and TypeScript merges them. **Interfaces are open for extension** - you can add properties to an existing interface anywhere in your codebase. This makes them ideal for augmenting third-party library types.**`
  },
  'sql-basics': {
    explanation: `**SQL (Structured Query Language)** is the standard language for managing relational databases. It allows you to create, read, update, and delete data (CRUD operations), define database schemas, and perform complex data analysis. SQL is used with databases like PostgreSQL, MySQL, SQLite, and Microsoft SQL Server.

**Core operations:** \`SELECT\` retrieves data (\`SELECT * FROM users WHERE age > 18\`). \`INSERT\` adds new rows. \`UPDATE\` modifies existing rows. \`DELETE\` removes rows. \`WHERE\` filters results. \`ORDER BY\` sorts results. \`LIMIT\` / \`OFFSET\` controls pagination. **Joins** combine data from multiple tables: \`INNER JOIN\` (matching rows only), \`LEFT JOIN\` (all from left, matching from right), \`RIGHT JOIN\`, \`FULL JOIN\`. **Aggregation:** \`COUNT()\`, \`SUM()\`, \`AVG()\`, \`MAX()\`, \`MIN()\` with \`GROUP BY\` for grouping. The \`HAVING\` clause filters groups (like WHERE for groups). **Subqueries:** queries nested inside other queries. **Indexes** speed up queries at the cost of write performance and storage. **Normalization** organizes data to reduce redundancy (splitting into multiple related tables). **Transactions** (\`BEGIN\`, \`COMMIT\`, \`ROLLBACK\`) ensure data integrity - either all operations succeed or none do. **Best practice:** use appropriate data types (don't use TEXT for boolean). Index columns used in WHERE and JOIN conditions. Use parameterized queries to prevent SQL injection. Always use transactions for related operations. Use EXPLAIN to analyze slow queries. Prefer JOINs over subqueries for better performance.`,
    codeExplanation: `This code shows **essential SQL operations**. The CREATE TABLE statement defines the schema with types, constraints (\`NOT NULL\`, \`DEFAULT\`), and a **primary key** (\`PRIMARY KEY\`). The INSERT adds a new user - the \`id\` is auto-generated (SERIAL). The SELECT query uses \`WHERE\` to filter, \`ORDER BY created_at DESC\` to sort (newest first), and \`LIMIT 10 OFFSET 0\` for pagination (first page of 10). The **JOIN** query combines users with their orders - \`LEFT JOIN\` ensures users with no orders are still included (order fields will be NULL). Aggregation with \`GROUP BY\` counts orders per user - \`COUNT(o.id)\` counts the orders, \`LEFT JOIN\` includes users with 0 orders. \`COALESCE(COUNT(o.id), 0)\` replaces NULL with 0 (users with no orders). **Parameterized queries** (\`$1\`) prevent SQL injection - never concatenate user input into SQL strings. **Transactions** (\`BEGIN...COMMIT\`) ensure both the order insert AND the inventory update succeed or fail together.**`
  },
  'sql-joins': {
    explanation: `**SQL JOINs** combine rows from two or more tables based on a related column. They are the most powerful feature of relational databases - allowing you to connect related data without duplicating it. Understanding joins is essential for working with normalized databases.

**Types of JOINs:** \`INNER JOIN\` returns rows where there's a match in both tables. If a customer has no orders, they won't appear. \`LEFT JOIN\` (or \`LEFT OUTER JOIN\`) returns ALL rows from the left table and matching rows from the right. Non-matching right-side columns are NULL. \`RIGHT JOIN\` is the opposite - all rows from the right table. \`FULL JOIN\` (or \`FULL OUTER JOIN\`) returns all rows from both tables, with NULLs where there's no match. \`CROSS JOIN\` creates a Cartesian product (every row of table A paired with every row of table B). \`SELF JOIN\` joins a table with itself (using aliases) - useful for hierarchical data like employees and managers. **JOIN condition:** specified with \`ON\` - \`ON users.id = orders.user_id\`. You can also join on multiple conditions. **Natural JOIN** automatically matches columns with the same name (avoid - it's implicit and fragile). **Performance:** joins are expensive on large tables. Indexes on join columns are essential. **Best practice:** start with INNER JOIN and widen as needed (LEFT JOIN if you need non-matching rows). Alias table names for readability (\`FROM users u JOIN orders o ON u.id = o.user_id\'). Specify the join condition explicitly with ON. Avoid joining more tables than necessary. Use EXPLAIN to verify the query plan.`,
    codeExplanation: `This query finds **customers with their orders and payments**. It uses three JOINs. \`INNER JOIN orders\` keeps only customers with orders. \`LEFT JOIN payments\` includes orders even without payments (payment fields will be NULL). \`SELECT c.name, o.id, o.total, p.amount, p.status\` selects specific columns from each table. Table aliases (\`c\`, \`o\`, \`p\`) make the query readable. **The join order matters** - customers joined with orders first, then the result is joined with payments. The second query shows a \`SELF JOIN\` - \`employees e\` is joined with \`employees m\` (managers). \`ON e.manager_id = m.id\` matches each employee to their manager. \`LEFT JOIN employees m\` ensures employees without managers are still included (CEO). \`COALESCE(m.name, 'No Manager')\` handles NULL manager names. **LEFT JOIN is the most commonly used join** - you usually want to keep primary entities even when related data doesn't exist.**`
  },
  'sql-indexes': {
    explanation: `**SQL indexes** are data structures that speed up data retrieval at the cost of slower writes and increased storage. Think of an index like a book's table of contents - instead of reading every page to find a topic, you look up the topic in the index and jump directly to the right page. Without an index, the database performs a "full table scan" (reads every row).

**How indexes work:** The most common type is the **B-tree index** (default in most databases). It maintains a balanced tree structure that allows logarithmic-time lookups, range queries, and sorting. **When to index:** columns used in \`WHERE\`, \`JOIN\`, \`ORDER BY\`, and \`GROUP BY\` clauses. Primary keys and unique constraints automatically create indexes. Foreign keys should be indexed for join performance. **Types of indexes:** \`UNIQUE\` index (prevents duplicates), \`COMPOSITE\` index (multiple columns - order matters: put most selective column first), \`PARTIAL\` index (only a subset of rows), \`COVERING\` index (includes all columns needed for a query - no table access needed). **Index drawbacks:** each index slows down \`INSERT\`, \`UPDATE\`, and \`DELETE\` (the index must be updated). Don't over-index - benchmark before adding indexes. Use \`EXPLAIN ANALYZE\` to check if queries use indexes. **Best practice:** index foreign keys, columns in WHERE clauses, and columns used for sorting. Create composite indexes when filtering by multiple columns. Monitor slow queries and add indexes as needed. Remove unused indexes. Regular \`VACUUM\` and \`ANALYZE\` keep indexes efficient. Index only what you need - each index adds overhead.`,
    codeExplanation: `This SQL creates **indexes for a typical application**. The \`CREATE INDEX idx_users_email ON users(email)\` creates an index for lookups by email - login queries benefit immediately. The **composite index** \`idx_orders_user_date ON orders(user_id, created_at DESC)\` handles the common query pattern "get recent orders for a user". The column order matters - \`user_id\` first (equality), \`created_at\` second (range/sort). **Partial index** \`idx_orders_active ON orders(status) WHERE status = 'pending'\` only indexes pending orders - it's smaller and faster than a full index. **Unique index** \`idx_products_sku ON products(sku)\` ensures no duplicate SKUs. The query examples show how indexes speed up lookups. The \`EXPLAIN ANALYZE\` output shows the query plan - \`Index Scan\` means the index is being used. **\`EXPLAIN ANALYZE\` is your best tool for understanding query performance** - it shows whether indexes are being used, the estimated and actual row counts, and execution time. A query without an appropriate index will show \`Seq Scan\` (sequential scan).**`
  },
  'nosql-databases': {
    explanation: `**NoSQL databases** are non-relational databases designed for specific use cases where traditional SQL databases fall short. They emerged to handle large-scale web applications, unstructured data, and the need for flexible schemas. There are four main types: **document stores**, **key-value stores**, **column-family stores**, and **graph databases**.

**Document stores** (MongoDB, Firestore) store data as JSON-like documents. Each document can have different fields (schema flexibility). Great for content management, catalogs, and rapid prototyping. **Key-value stores** (Redis, DynamoDB) are the simplest - every item is a key-value pair. Extremely fast for lookups and caching. **Column-family stores** (Cassandra, HBase) store data in columns rather than rows, optimized for write-heavy workloads and analytics across large datasets. **Graph databases** (Neo4j) store nodes and relationships - ideal for social networks, recommendation engines, and fraud detection. **When to use NoSQL:** when you need flexible schemas, horizontal scaling, high write throughput, or when your data is naturally document-oriented or graph-like. **When NOT to use:** when you need ACID transactions, complex joins, or strict data consistency. Many modern applications use a polyglot approach - PostgreSQL for core data, Redis for caching, MongoDB for logs. **Best practice:** choose the database based on data access patterns, not trends. Start with a SQL database by default - switch to NoSQL only when you have a specific need that SQL doesn't handle well. Understand the CAP theorem (Consistency vs Availability vs Partition tolerance).`,
    codeExplanation: `This code shows **NoSQL data models**. MongoDB stores a user as a BSON document with nested data (address as an object, hobbies as an array). The schema is flexible - different users can have different fields. Redis key-value pairs show caching - \`SET user:1 "..."\` with \`EX 3600\` (expires in 1 hour). Redis can also store complex data structures (hashes, lists, sets). The Cassandra column-family model shows a wide-column design optimized for time-series queries - "user_events" stores events per user, and you can efficiently query recent events by timestamp. MongoDB queries use a JSON-like syntax - \`find({ age: { $gt: 25 } })\` finds users older than 25. \`aggregate()\` with \`$group\` and \`$sum\` performs aggregation. **The key difference from SQL:** MongoDB's aggregation pipeline processes documents step by step, while SQL uses declarative SELECT with JOIN and GROUP BY. **NoSQL trades ACID guarantees for performance and scalability** - understand the tradeoffs before choosing.**`
  },
  'nodejs-basics': {
    explanation: `**Node.js** is a JavaScript runtime built on Chrome's V8 engine that allows JavaScript to run on the server (outside the browser). It uses an **event-driven, non-blocking I/O model** that makes it lightweight and efficient for building scalable network applications. Created by Ryan Dahl in 2009, Node.js revolutionized server-side development by bringing JavaScript to the backend.

**Key concepts:** Node.js runs on a **single thread** but uses an **event loop** to handle many concurrent connections efficiently. Instead of creating a new thread for each request (like traditional servers), the event loop processes requests asynchronously using callbacks. **CommonJS modules** (\`require()\`, \`module.exports\`) are the traditional module system, but **ES modules** (\`import/export\`) are now fully supported with \`"type": "module"\` in package.json. **The \`fs\` module** handles file operations. **\`http\`/**\`https\`** create HTTP servers. **\`path\`** handles file paths. **\`os\`** provides OS-level utilities. **npm (Node Package Manager)** is the largest package ecosystem in the world. The **\`package.json\`** file manages dependencies, scripts, and metadata. **NODE_ENV** environment variable controls behavior (development vs production). **Best practice:** always handle errors in async code - unhandled Promise rejections crash the process. Use the built-in \`fs/promises\` API (promises-based) instead of callback-based \`fs\`. Use environment variables for configuration (never hardcode secrets). Use \`process.on('uncaughtException')\` and \`process.on('unhandledRejection')\` for global error handling. Prefer modern ES modules over CommonJS.`,
    codeExplanation: `This code shows a **basic Node.js HTTP server**. \`http.createServer((req, res) => {...})\` creates a server - the callback runs on every request. \`req\` is the request object (method, url, headers). \`res\` is the response object. \`res.writeHead(200, { 'Content-Type': 'application/json' })\` sets the status code and headers. \`res.end(JSON.stringify({ message, timestamp }))\` sends the response. The server listens on \`process.env.PORT || 3000\`. The \`fs.readFile\` example shows the **async file system API** - reading users.json and parsing it. The \`/api/users\` route reads the file and returns users. Error handling: \`if (err) { ... res.writeHead(500) }\` - always handle file read errors. \`res.writeHead(404, { 'Content-Type': 'text/plain' })\` for unknown routes. **In production, you'd use Express.js or Fastify instead of raw \`http\`** - they provide routing, middleware, and error handling. The \`async/await\` version uses \`import { readFile } from 'fs/promises'\` for cleaner code. **Always handle async errors in Node.js** - unhandled rejections in the request handler will crash the server.**`
  },
  'express-js': {
    explanation: `**Express.js** is a minimal and flexible Node.js web application framework that provides a robust set of features for building web applications and APIs. It's the most popular framework for Node.js and the foundation for many other frameworks (like Next.js API routes and NestJS).

**Core concepts:** **Routing** defines how the app responds to client requests at specific endpoints. \`app.get('/users', handler)\`, \`app.post('/users', handler)\`. **Route parameters** (\`:id\`) capture URL segments. **Middleware** functions have access to the request, response, and the next middleware in the chain (\`next()\`). They can modify request/response objects, end the request, or call the next middleware. **Common middleware:** \`express.json()\` parses JSON bodies, \`express.urlencoded()\` parses form data, \`cors()\` enables CORS, \`morgan\` logs requests, \`helmet\` sets security headers. **Error handling:** special middleware with 4 parameters (\`err, req, res, next\`) catches errors. **Static files:** \`express.static('public')\` serves files from a directory. **Best practice:** use the Router to organize routes by resource (\`router.get('/users', ...)\`). Keep middleware in separate files. Validate request data (use Zod or Joi). Use environment variables for configuration (PORT, DATABASE_URL). Structure your app: routes -> controllers -> services -> models. Implement proper error handling middleware. Never expose stack traces in production. Use compression and helmet for production deployments.`,
    codeExplanation: `This code shows **Express.js API structure**. \`express()\` creates the app. \`app.use(express.json())\` is middleware that parses JSON request bodies. The \`errorHandler\` middleware has 4 parameters - Express recognizes it as error-handling middleware. \`createUser\` is a controller using **async/await** with try/catch for error handling - \`next(error)\` passes errors to the error handler. The router (\`express.Router()\`) groups user routes. \`router.route('/:id')\` chains multiple handlers for the same path. \`app.use('/api/users', userRouter)\` mounts the router at /api/users. The \`catchAsync\` wrapper catches errors from async route handlers - without it, Express wouldn't catch Promise rejections automatically. **Always wrap async route handlers** - unhandled Promise rejections in Express can cause requests to hang without a response. The error handler returns a JSON response with status code and message. In development, include the \`stack\` trace; in production, omit it. **Validation middleware** (using Zod) ensures request data is valid before it reaches the controller - never trust user input.**`
  },
  'rest-apis': {
    explanation: `**REST (Representational State Transfer)** is an architectural style for designing networked applications. REST APIs use HTTP methods to perform CRUD operations on resources, which are identified by URLs. A well-designed REST API is stateless, cacheable, and uses standard HTTP status codes and methods.

**HTTP methods and CRUD:** \`GET\` (read), \`POST\` (create), \`PUT\` (replace/update), \`PATCH\` (partial update), \`DELETE\` (delete). **URL structure:** resources are nouns, not verbs. \`/api/users\` (collection), \`/api/users/42\` (specific resource). \`/api/users/42/orders\` (related resources). **HTTP status codes:** 200 (OK), 201 (Created), 204 (No Content), 301 (Moved), 400 (Bad Request), 401 (Unauthorized), 403 (Forbidden), 404 (Not Found), 409 (Conflict), 422 (Unprocessable Entity), 429 (Too Many Requests), 500 (Internal Server Error). **Best practices:** use consistent naming conventions (plural nouns, lowercase, kebab-case). Version your API (\`/api/v1/users\`). Use query parameters for filtering, sorting, and pagination (\`?status=active&sort=name&page=1&limit=20\`). Return appropriate status codes. Include error details in the response body. Use HATEOAS (links to related resources). Implement rate limiting. Use pagination for list endpoints. Support content negotiation (\`Accept\` header). Document your API (OpenAPI/Swagger). **GraphQL vs REST:** REST uses multiple endpoints with fixed response structures; GraphQL uses a single endpoint where clients request exactly what they need. REST is simpler to cache and monitor; GraphQL is flexible and reduces over-fetching. Choose based on your use case.`,
    codeExplanation: `This code shows **REST API best practices**. The router defines endpoints following REST conventions. \`GET /api/v1/users\` returns a paginated list - supports \`?\` query parameters for filtering, sorting, and pagination. The response includes \`data\` (the actual items), \`pagination\` metadata (page, limit, total, hasMore), and \`links\` (HATEOAS links for navigation). \`POST /api/v1/users\` creates a user - returns 201 Created with the new resource in the body and a \`Location\` header pointing to the new resource. \`GET /api/v1/users/:id\` returns a single user or 404. \`PATCH /api/v1/users/:id\` partially updates a user (only sends changed fields - PUT would replace the entire resource). \`DELETE /api/v1/users/:id\` deletes and returns 204 No Content. Error responses have a consistent structure: \`{ error: { message, status, ...details } }\`. The HttpError class extends Error with status code. **Consistent error handling** makes API consumption predictable. Pagination prevents clients from fetching too much data at once - always paginate list endpoints. **Always return \`Location\` header for created resources** - it helps clients navigate the API.**`
  },
  'authentication': {
    explanation: `**Authentication** verifies who a user is (identity), while **authorization** determines what they can access (permissions). Authentication is the first line of security for any web application. The most common approaches are session-based auth and token-based auth (JWT).

**Session-based auth:** the server creates a session, stores it in memory/database, and sends a session cookie to the client. The client sends the cookie with every request. Traditional and secure, but doesn't scale well horizontally (need shared session store like Redis). **JWT (JSON Web Token):** the server creates a signed token containing user info (claims). The client stores the token and sends it in the \`Authorization: Bearer <token>\` header. The server verifies the signature without needing to look up the session. JWTs are stateless and scale easily. **JWT structure:** \`header.payload.signature\` - base64url encoded. The signature is created with a secret (HMAC) or private key (RSA/ECDSA). **\`accessToken\`** (short-lived, 15min) and **\`refreshToken\`** (long-lived, 7 days) pattern: the access token is sent with requests, and the refresh token is used to get new access tokens without requiring login. **Security best practices:** hash passwords with bcrypt (never plain text, never MD5/SHA1). Use HTTPS everywhere. Set HttpOnly and Secure flags on cookies. Implement rate limiting on login endpoints. Use CORS properly. Validate all user input. Store secrets in environment variables. Use CSRF tokens for cookie-based auth. Token expiry and rotation. Implement account lockout after failed attempts. Log security events. **OAuth 2.0 / OpenID Connect:** delegated authorization (login with Google, GitHub). The standard for third-party authentication.`,
    codeExplanation: `This code shows **JWT authentication**. \`POST /auth/register\` receives email and password, hashes the password with \`bcrypt.hash()\`, creates the user, and generates tokens. \`POST /auth/login\` verifies the password with \`bcrypt.compare()\` and returns tokens. \`generateAccessToken\` creates a JWT with user id and role, expires in 15 minutes. \`generateRefreshToken\` creates a longer-lived token. \`authenticate\` middleware extracts the token from the \`Authorization\` header (\`req.header('Authorization')?.replace('Bearer ', '')\`), verifies it with \`jwt.verify()\`, and attaches the decoded user to \`req.user\`. \`authorize('admin')\` is middleware that checks if the user's role includes the required role. The refresh token endpoint exchanges a valid refresh token for new tokens. **Passwords are NEVER stored in plain text** - bcrypt hashing with salt makes rainbow table attacks infeasible. **\`HttpOnly\` cookies** (alternative to header-based auth) prevent JavaScript XSS attacks from stealing tokens. **Always use HTTPS** in production - tokens sent over HTTP can be intercepted. The authenticate middleware is applied to protected routes - anything after \`app.use('/api', authenticate)\` requires authentication.**`
  },
  'git-basics': {
    explanation: `**Git** is a distributed version control system created by Linus Torvalds in 2005. It tracks changes to files, enables collaboration, and allows you to revert to previous versions. Unlike centralized systems (SVN), every developer has a complete copy of the repository history.

**Core concepts:** A **repository** (repo) is a project tracked by Git. **Commits** are snapshots of changes with a message describing what changed. Each commit has a unique hash (SHA-1). The **working directory** is your current files; the **staging area (index)** is where you prepare changes before committing. **Branches** are separate lines of development - the default branch is \`main\` (or \`master\`). **HEAD** points to your current position (usually the latest commit on the current branch). **Remote** repositories are hosted (GitHub, GitLab). **Common commands:** \`git init\` creates a repo. \`git clone <url>\` copies a remote repo. \`git add <file>\` stages changes. \`git commit -m "message"\` creates a commit. \`git push\` uploads local commits to remote. \`git pull\` downloads and merges remote changes. \`git branch\` lists/manages branches. \`git checkout <branch>\` switches branches. \`git merge <branch>\` merges changes. \`git log\` shows commit history. \`git status\` shows current state. **Best practice:** commit often with meaningful messages. One commit = one logical change. Branch for features/fixes. Write commit messages in imperative mood ("Add login feature" not "Added login feature"). Keep the main branch deployable. Review changes before committing (\`git diff\`). Never commit secrets, API keys, or large binary files. Use \`.gitignore\` to exclude build artifacts, dependencies, and environment files. Learn to use interactive rebase for clean history (\`git rebase -i\`).`,
    codeExplanation: `This shows **essential Git workflows**. Feature branch workflow: \`git checkout -b feature/login\` creates and switches to a new branch. After making changes, \`git add .\` stages everything (or specify specific files), and \`git commit -m "feat: add login form"\` commits with a conventional commit message. \`git push -u origin feature/login\` pushes the branch and sets upstream tracking. After code review and merge (on GitHub/GitLab), delete the remote branch. The second example shows **rebasing** to incorporate main changes: \`git checkout main && git pull\` gets latest main, \`git checkout feature\` switches back, \`git rebase main\` replays feature commits on top of main (creates a linear history). \`git log --oneline --graph --all\` shows a visual commit graph. **Resolving merge conflicts:** when Git can't automatically merge, it marks the conflicting files. You edit them (keep your changes, theirs, or both), remove the conflict markers, then \`git add\` and commit. **Interactive rebase** (\`git rebase -i HEAD~3\`) lets you squash, reorder, or edit recent commits. **Never rebase shared/pushed branches** - it rewrites history. Use merge for integrating shared branches, rebase for local cleanup. The conventional commit format (\`feat:\`, \`fix:\`, \`chore:\`) is widely used and enables automatic changelog generation.**`
  },
  'data-structures': {
    explanation: `**Data structures** are ways of organizing and storing data so that it can be used efficiently. Different data structures excel at different operations - some are fast for searching, others for insertion, others for ordered access. Choosing the right data structure is a fundamental skill in programming.

**Arrays** (contiguous memory, O(1) index access, O(n) insertion/deletion). **Linked Lists** (non-contiguous, O(n) access, O(1) insertion at ends). **Stacks** (LIFO - Last In, First Out) - used for function calls, undo operations, parsing. **Queues** (FIFO - First In, First Out) - used for task scheduling, request processing. **Hash Tables** (dictionaries/objects/maps) - O(1) average lookup, insertion, deletion. The hash function maps keys to buckets; collisions are handled by chaining or open addressing. **Trees** - hierarchical structures with a root node and children. **Binary Search Trees** - O(log n) search, insert, delete (average case). **Heaps** - complete binary trees where parent is always greater (max-heap) or smaller (min-heap) than children. Used for priority queues. **Graphs** - nodes connected by edges. Can be directed/undirected, weighted/unweighted. Used for social networks, maps, recommendation systems. **Time complexity matters** - O(1) is ideal, O(log n) is great, O(n) is acceptable for small data, O(n log n) is typical for sorting, O(n^2) and above should be avoided for large inputs. **Best practice:** understand the operations you need most (read-heavy vs write-heavy) and choose accordingly. Measure before optimizing. The right data structure can make the difference between a program that finishes in seconds vs one that never finishes.`,
    codeExplanation: `This code shows **essential data structures**. The \`Stack\` uses an array with \`push/pop\` - only adds/removes from the end, so all operations are O(1). The \`Queue\` uses a class with a separate object (\`items\`) and indexes (\`frontIndex\`, \`backIndex\`) - enqueue adds at the back, dequeue removes from the front. This avoids O(n) array shift operations. The \`HashTable\` implements a simple hash map with **separate chaining** (each bucket is an array of [key, value] pairs). The hash function uses a prime number (31) and modulus to distribute keys. Collisions are handled by storing multiple entries in the same bucket. The Binary Search Tree (\`find\`) demonstrates recursive search - compare the value, go left if smaller, right if larger, return the node when found. **BST search is O(log n) on average** but O(n) in worst case (unbalanced tree). **For production, use built-in data structures** (\`Map\`, \`Set\`, arrays) rather than implementing from scratch. Understanding the internals helps you choose the right one. **Time complexity determines scalability** - an O(n) algorithm with 1M elements means 1M operations; an O(log n) algorithm means ~20 operations.**`
  },
  'algorithms': {
    explanation: `**Algorithms** are step-by-step procedures for solving problems. Understanding common algorithms and their time/space complexity is essential for writing efficient code and passing technical interviews. The key is recognizing which algorithm to apply to which problem.

**Sorting Algorithms:** \`Bubble Sort\` (O(n^2) - educational only), \`Merge Sort\` (O(n log n) - stable, divide and conquer), \`Quick Sort\` (O(n log n) average, O(n^2) worst - in-place, widely used), \`Insertion Sort\` (O(n^2) but fast for nearly-sorted data). **Searching:** \`Linear Search\` (O(n) - unsorted data), \`Binary Search\` (O(log n) - sorted data only). **Two Pointers** - using left and right pointers to find pairs in sorted arrays. **Sliding Window** - maintaining a window over a subset of data (max sum subarray, longest substring). **Recursion** - a function that calls itself, with a base case to terminate. Every recursive solution can be written iteratively (and vice versa). **Divide and Conquer** - break problem into subproblems, solve each, combine results. **Greedy Algorithms** - make the locally optimal choice at each step. **Dynamic Programming** - break problems into overlapping subproblems and store results (memoization). Used for optimization problems (Fibonacci, knapstack, shortest path). **Graph Algorithms:** \`BFS\` (shortest path in unweighted graphs), \`DFS\` (exploring all paths), \`Dijkstra\` (shortest path in weighted graphs), \`Union-Find\` (detecting cycles, connected components). **Best practice:** analyze time and space complexity before coding. Start with brute force, then optimize. Test with edge cases (empty input, single element, large input). Know when to use built-in methods vs implementing from scratch. Practice recognizing patterns (two pointers, sliding window, BFS/DFS).`,
    codeExplanation: `This code shows **common algorithm patterns**. \`binarySearch\` works on a sorted array - it repeatedly divides the search space in half. O(log n) time, O(1) space. \`twoSum\` uses a **hash map** for O(n) time instead of O(n^2) brute force. As it iterates, it stores each number's index. For each number, it checks if the complement (target - num) was already seen. \`maxSubarraySum\` is a **sliding window** - O(n) instead of O(n*k). It maintains a sum of the current window and slides it across the array, updating the max. \`fibonacci\` uses **dynamic programming with memoization** - it stores computed results in a Map to avoid recalculating. Without memoization, this would be O(2^n); with memoization, it's O(n). \`hasCycle\` (linked list) uses **Floyd's Tortoise and Hare** - two pointers moving at different speeds. If they meet, there's a cycle. O(n) time, O(1) space. **The key insight:** recognizing the pattern determines the approach. Sorted array + search -> binary search. Unsorted array + pair sum -> hash map. Subarray property -> sliding window. Overlapping subproblems -> DP. Cycle detection -> fast/slow pointers.**`
  },
  'system-design': {
    explanation: `**System design** is the process of defining the architecture, components, modules, interfaces, and data flow of a system to satisfy specific requirements. It's a crucial skill for senior engineers and a common topic in technical interviews. Good system design produces scalable, maintainable, and reliable systems.

**Key principles:** **Scalability** - the system should handle growth in users, data, and traffic. Horizontal scaling (adding more servers) is preferred over vertical scaling (upgrading a single server). **Reliability** - the system should work correctly despite failures. Use redundancy, failover, and graceful degradation. **Availability** - measured as uptime percentage (99.9% = three nines, ~8.7 hours/yr downtime). **Performance** - low latency (response time) and high throughput (requests/second). **Consistency vs Availability (CAP theorem)** - in a distributed system, you can have at most two of: Consistency, Availability, and Partition Tolerance. Most systems choose Availability + Partition Tolerance (eventual consistency). **Common building blocks:** **Load balancers** distribute traffic across servers. **CDNs** cache static content at edge locations. **Databases** (SQL for structured data with relationships, NoSQL for flexible/high-throughput data). **Caching** (Redis/Memcached) reduces database load. **Message queues** (Kafka, RabbitMQ) decouple services and handle async processing. **Microservices** vs **Monolith**: microservices offer independent scaling and deployment but add complexity. **Best practice:** start simple and evolve. Identify bottlenecks (database, network, CPU). Cache aggressively. Use databases for persistence, not for computation. Design for failure (redundancy, graceful degradation). Monitor everything. Consider tradeoffs - every architectural decision involves tradeoffs. Understand the business requirements before designing.`,
    codeExplanation: `This text describes a **URL shortener design**. The architecture includes: **Load balancer** (distributes traffic, handles SSL termination), **Web servers** (stateless, horizontally scalable), **Cache** (Redis for hot URLs), **Database** (PostgreSQL for persistent storage), and **Analytics service** (async processing with message queue). Key design decisions: \`base62 encoding\` for short URLs (62^7 = ~3.5 trillion combinations for 7 characters). The encode/decode flow: encode checks the cache first, then the database; decode does the reverse. **Cache with TTL** speeds up reads for popular URLs. **Database index on short_code** ensures fast lookups. Rate limiting per user/IP prevents abuse. **The write path:** POST request -> validate -> generate short code -> store in DB -> invalidate cache -> return. **The read path:** GET request -> check cache -> if miss, query DB -> update cache -> redirect (301). **Tradeoffs:** SQL DB ensures data integrity; cache adds complexity but improves performance. 301 redirects are cached by browsers, reducing load. Async analytics processing means analytics might be slightly delayed but won't slow down the core redirect flow. **Always consider tradeoffs** in system design - there's no single right answer.**`
  },
  'oauth': {
    explanation: `**OAuth 2.0** is an authorization framework that allows third-party applications to access user data without exposing the user's credentials. It's the standard behind "Login with Google/GitHub/Facebook". OAuth 2.0 is about **authorization** (what you can access), not authentication (who you are) - though OpenID Connect (OIDC) builds on OAuth 2.0 for authentication.

**Key roles:** **Resource Owner** (the user), **Client** (the application requesting access), **Authorization Server** (issues tokens), **Resource Server** (hosts protected data). **Authorization Grant types:** **Authorization Code** (most common for server-side apps) - the client gets a code, then exchanges it for tokens. **PKCE** (Proof Key for Code Exchange) - enhanced version for mobile/native apps. **Client Credentials** (server-to-server communication, no user involved). **Refresh Token** - used to get new access tokens without user interaction. **Token types:** **Access Token** (short-lived, sent with API requests), **Refresh Token** (long-lived, used to get new access tokens), **ID Token** (JWT with user identity info - from OIDC). **Best practices:** always use HTTPS. Use the Authorization Code flow with PKCE for single-page apps and mobile apps. Store tokens securely (HttpOnly cookies for web apps, secure storage for mobile). Never expose client secrets in client-side code. Validate the \`state\` parameter to prevent CSRF attacks. Validate redirect URIs strictly. Use short-lived access tokens (15 minutes). Implement token rotation. Scope tokens to minimum necessary permissions. Revoke tokens when users log out. Understand the difference between OAuth (authorization) and OIDC (authentication). OAuth without OIDC doesn't tell you who the user is - just that they authorized access.`,
    codeExplanation: `This code shows **OAuth 2.0 Authorization Code flow** with Passport.js and Google. \`passport.use(new GoogleStrategy({...}))\` configures the Google OAuth provider with client ID, client secret, callback URL, and requested scopes (\`profile\`, \`email\`). The callback function receives \`accessToken\`, \`refreshToken\`, \`profile\`, and \`done\`. The \`verifyCallback\` finds or creates a user in the database then calls \`done(null, user)\`. Routes: \`GET /auth/google\` starts the OAuth flow; \`GET /auth/google/callback\` handles the callback. \`passport.authenticate('google', { session: false })\` is middleware - \`session: false\` means we're using JWT instead of sessions. After successful authentication, we generate a JWT and redirect. The \`scope\` parameter specifies what data we're requesting. **The \`state\` parameter** (automatically handled by Passport) prevents CSRF attacks. **The flow:** user clicks "Login with Google" -> redirected to Google -> user consents -> Google redirects back to callback with code -> server exchanges code for tokens -> server creates/updates user -> server generates JWT -> redirect user to frontend with JWT. **Passwords are NEVER involved** - Google handles authentication, you just receive the verified identity.**`
  },
  'docker': {
    explanation: `**Docker** is a platform for developing, shipping, and running applications in containers. Containers are lightweight, standalone packages that include everything needed to run an application: code, runtime, system tools, libraries, and settings. Unlike virtual machines, containers share the host OS kernel, making them much more efficient.

**Key concepts:** **Images** are read-only templates (like a class in OOP). **Containers** are running instances of images (like objects). **Dockerfile** is a text file with instructions to build an image. **Layers** - each instruction in a Dockerfile creates a layer; layers are cached and reused, making builds faster. **Registry** stores images (Docker Hub, ECR, GCR). **Volumes** persist data generated by containers (database data, uploads). **Networks** connect containers (bridge, host, overlay). **Docker Compose** defines multi-container applications in a YAML file - start everything with \`docker compose up\`. **Key Dockerfile instructions:** \`FROM\` (base image), \`WORKDIR\` (working directory), \`COPY\` (copy files), \`RUN\` (build-time commands), \`EXPOSE\` (document port), \`CMD\` (default command), \`ENV\` (environment variables). **Best practice:** use multi-stage builds to reduce image size (one stage for dependencies, one for runtime). Use specific base image tags (not \`latest\`). Order Dockerfile instructions from least to most frequently changing to maximize layer caching. Use \`.dockerignore\` to exclude unnecessary files. Run containers as non-root user. Scan images for vulnerabilities. Use health checks. Keep containers stateless (use volumes for state). Don't run multiple processes in one container. Use Docker Compose for development environments. Use orchestration (Kubernetes) for production.`,
    codeExplanation: `This code shows **Docker best practices**. The Dockerfile uses a **multi-stage build**: Stage 1 (\`node:18-alpine AS builder\`) installs dependencies and builds the app. Stage 2 starts fresh from a clean Alpine image, copies only the built artifacts (\`COPY --from=builder\`), and adds a non-root user (\`USER node\`). The final image is much smaller (no build tools, no node_modules with dev dependencies). \`HEALTHCHECK\` tells Docker how to check if the container is healthy. \`CMD ["node", "dist/server.js"]\` is the default command. The Docker Compose file defines three services: \`app\` (the Node.js app with environment variables and port mapping), \`db\` (PostgreSQL with a named volume for data persistence), and \`redis\` (cache). The \`app_data\` volume persists database data even when containers are removed. Environment variables are defined directly (use \`.env\` file in real projects). **Production app:** uses the \`production\` profile with no bind mount (the code is built into the image). **Backup command:** \`docker run --rm -v app_data:/data -v /backup:/backup alpine tar czf /backup/app_data.tar.gz -C /data .\` - temporary Alpine container to compress volume data. **Best practice:** Use named volumes for databases. Use bind mounts for development only. Never store secrets in volumes (use Docker secrets or environment variables).**`
  },
  'accessible-html': {
    explanation: `**Web accessibility** means your website is usable by everyone, including people with disabilities who use screen readers or keyboard navigation. WCAG (Web Content Accessibility Guidelines) requires accessible websites to be **perceivable, operable, understandable, and robust**.

**Most important practices:** **Descriptive \`alt\` text for every image** - essential for screen reader users. If an image is purely decorative, use \`alt=""\` (empty) so the screen reader ignores it. **Proper heading hierarchy** - don't skip heading levels (don't jump from h1 to h3). **Labels on all form inputs** - every input needs a visible label. **Sufficient color contrast** - text and background contrast must meet WCAG AA standards. **Keyboard navigation** - every interactive element must be accessible via keyboard (Tab, Enter, Space). Use ARIA landmarks to supplement semantic HTML, not replace it. **Best practice:** test with a screen reader (NVDA, VoiceOver) and keyboard-only navigation. Use tools like axe DevTools or Lighthouse for automated checks. Accessibility is not just about compliance - it improves the experience for all users. Semantic HTML is the foundation of accessibility - use proper elements before reaching for ARIA.`,
    codeExplanation: `This code shows **accessible form with ARIA**. The \`<label for="email">\` is linked to the input by matching \`for\` and \`id\` - clicking the label focuses the input. \`aria-describedby="email-hint"\` connects the hint text to the input - screen readers will read the hint when the input is focused. The image has a descriptive \`alt\` attribute describing what the chart shows. \`aria-label="Main navigation"\` on the \`<nav>\` element distinguishes it from other nav elements on the page (helps screen reader users navigate landmarks). **alt text should describe the content and function of the image**, not just say "image" or "chart". For decorative images, use \`alt=""\` (empty) - this tells screen readers to skip it entirely. **Keyboard accessibility** is tested by tabbing through all interactive elements - they should have visible focus indicators. **Color contrast** can be checked with browser DevTools. **Semantic HTML elements like \`<nav>\`, \`<main>\`, \`<header>\`** provide built-in landmarks that screen readers use for navigation - this is why semantic HTML is the first step in accessibility.`
  },
  'css-fundamentals': {
    explanation: `**CSS (Cascading Style Sheets)** is the language used to style HTML documents. It controls colors, fonts, spacing, layout, and animations. CSS follows a **cascading** rule system where multiple styles can apply to the same element, and the order and specificity determine which one wins. CSS can be written inline (in HTML), internally (in a \`<style>\` tag), or externally (in a \`.css\` file linked with \`<link>\`).

**Core concepts:** **Selectors** target HTML elements (\`element\`, \`.class\`, \`#id\`). **Properties and values** define styles (\`color: red\`, \`font-size: 16px\`). **The cascade** means styles can come from multiple sources - browser defaults, user styles, author styles. Later rules override earlier ones, and more specific selectors override less specific ones. **Inheritance** - some properties (like \`color\` and \`font-family\`) are inherited from parent to child elements. **The Box Model** - every element is a box with content, padding, border, and margin areas. **Layout** historically used \`float\` and \`position\`, but modern CSS uses **Flexbox** (for one-dimensional layouts) and **Grid** (for two-dimensional layouts). **Units:** \`px\` (fixed), \`em\` (relative to parent font-size), \`rem\` (relative to root font-size), \`%\` (relative to parent), \`vh/vw\` (relative to viewport). **Best practice:** use external stylesheets (separate content from presentation). Use classes for reusable styles. Avoid inline styles. Use a CSS methodology (BEM, utility-first with Tailwind) for maintainability. Keep specificity low and flat. Use CSS custom properties for theming. Always reset or normalize browser defaults.`,
    codeExplanation: `This code shows **CSS fundamentals**. The \`* { box-sizing: border-box; margin: 0; padding: 0; }\` is a **CSS reset** - it removes default margins/padding from all elements and makes box-sizing consistent (padding and border are included in total width). External CSS is linked with \`<link rel="stylesheet" href="styles.css">\` in the HTML head. The \`.card\` class selector styles a card component - \`max-width: 300px\` limits width, \`margin: 20px auto\` centers horizontally (auto margins), \`padding: 20px\` adds internal space, \`border-radius: 8px\` rounds corners, \`box-shadow\` adds a shadow (x-offset, y-offset, blur, color). \`h2\` in \`.card\` inherits the \`color\` and \`font-family\` from the parent but overrides \`font-size\`. **Inheritance** - \`color\` and \`font-family\` are inherited by default; \`margin\`, \`padding\`, \`border\` are not. **The cascade** - if two rules have equal specificity, the one that appears later in the stylesheet wins. If specificity differs, the more specific selector wins regardless of order. **Always include a CSS reset** - different browsers have different default styles.**`
  },
  'css-layouts': {
    explanation: `**CSS layouts** control how elements are arranged on a web page. Modern CSS provides powerful layout tools: **Flexbox** for one-dimensional layouts (rows or columns) and **Grid** for two-dimensional layouts (rows AND columns). Understanding both is essential for building any website layout.

**Flexbox** is ideal for navigation bars, centering items, card rows, and component-level layouts. Key properties: \`display: flex\` (container), \`justify-content\` (main axis alignment), \`align-items\` (cross axis alignment), \`flex-direction\` (row or column), \`flex-wrap\`, and \`gap\`. Flex items can grow/shrink with \`flex: grow shrink basis\`. **CSS Grid** is best for page-level layouts, image galleries, and complex arrangements. Key properties: \`grid-template-columns\`, \`grid-template-rows\`, \`gap\`, \`grid-column\`, \`grid-row\`. The \`fr\` unit distributes available space. \`repeat(auto-fit, minmax(250px, 1fr))\` creates responsive grids without media queries. **Grid vs Flexbox:** use Flexbox for content-first layouts (distribute items along one axis). Use Grid for layout-first designs (divide space into rows and columns). They work great together - Grid for the page layout, Flexbox for components inside grid cells. **Best practice:** don't use \`float\` for layouts (it's for text wrapping around images). Don't use \`display: inline-block\` for layouts (Flexbox and Grid are better). Learn both and use the right tool for each job.`,
    codeExplanation: `This code shows **Flexbox and Grid layouts**. The \`.navbar\` uses Flexbox - \`display: flex\`, \`justify-content: space-between\` (pushes items apart), \`align-items: center\` (vertical centering). The \`.nav-links\` is also flex with \`gap: 20px\` for spacing. The \`.card-grid\` uses CSS Grid - \`grid-template-columns: repeat(auto-fit, minmax(250px, 1fr))\` creates responsive columns that automatically adjust based on container width. When space is limited, fewer columns are shown; when space is available, more columns fit. **\`auto-fit\` vs \`auto-fill\`:** \`auto-fit\` collapses empty tracks, \`auto-fill\` preserves them. The \`.page-layout\` shows a complete page grid with \`grid-template-areas\` - this creates a named grid template that's very readable. \`grid-template-columns: 250px 1fr\` (sidebar + main), \`grid-template-rows: auto 1fr auto\` (header + content + footer). \`grid-area: header\` places elements in named areas. **\`min-height: 100vh\`** makes the layout fill the full viewport height. **Grid with \`grid-template-areas\` is the most intuitive way to create page layouts** - you can see the structure directly in CSS.**`
  },
  'responsive-design': {
    explanation: `**Responsive design** ensures websites look good on all devices - from mobile phones to desktop monitors. The core principle is that layout should adapt to screen size, not the other way around. Responsive design relies on three key techniques: **fluid grids** (relative units like \`%\`, \`fr\`, \`vw\`), **flexible images** (\`max-width: 100%\`), and **media queries** (CSS rules that apply at specific screen widths).

**Mobile-first design** is the recommended approach: start with styles for small screens (the base CSS), then use \`min-width\` media queries to enhance for larger screens. This is simpler and ensures mobile users don't download desktop-sized resources. **Breakpoints** are the screen widths where your layout changes. Common breakpoints: 480px (phones), 768px (tablets), 1024px (desktops), 1200px+ (large screens). Choose breakpoints based on your content, not specific devices. **Modern responsive techniques:** CSS Grid with \`auto-fit\`/\`auto-fill\` + \`minmax()\` reduces the need for media queries. \`clamp()\` fluidly scales values between min and max (\`font-size: clamp(1rem, 2.5vw, 2rem)\`). Container queries (newer) allow components to respond to their container size, not just the viewport. **Best practice:** design for mobile first. Use \`rem\` for typography (respects user's font-size settings). Use relative units for layout. Test on real devices. Optimize images for different screen sizes (\`srcset\` and \`sizes\` attributes). Touch targets should be at least 48x48px. Don't hide content on mobile - prioritize and reorganize it.`,
    codeExplanation: `This code is a **mobile-first responsive layout**. Base styles (no media query) are for mobile: \`.container\` is a single column (\`grid-template-columns: 1fr\`), padding is smaller (\`padding: 0 16px\`). The first media query \`@media (min-width: 768px)\` targets tablets - switches to 2 columns, larger font (\`clamp\`), more padding. The second \`@media (min-width: 1024px)\` targets desktops - 3 columns, sidebar appears, larger spacing. Images use \`max-width: 100%\` and \`height: auto\` - they never overflow their container and maintain aspect ratio. \`font-size: clamp(1rem, 2.5vw, 1.5rem)\` fluidly scales font size between 1rem (minimum) and 1.5rem (maximum) based on viewport width. **Mobile-first means the base CSS is for mobile, and \`min-width\` queries add complexity for larger screens.** This is better than \`max-width\` (desktop-first) because mobile browsers don't need to download and then override desktop styles. The \`container-type: inline-size\` and \`@container (min-width: 400px)\` shows **container queries** - the component responds to its container width, not the viewport. This is useful for reusable components that might appear in different-width contexts.**`
  },
  'css-preprocessors': {
    explanation: `**CSS preprocessors** (Sass/SCSS, Less, Stylus) extend CSS with features that make stylesheets more maintainable and powerful. They compile to regular CSS. The most popular is **Sass** (Syntactically Awesome Style Sheets) with SCSS syntax (which is a superset of CSS).

**Key features:** **Variables** (\`$primary-color: #3498db\`) - store reusable values (colors, fonts, sizes). **Nesting** - write nested selectors that reflect HTML structure (\`.card { .title { color: red } }\`). **Mixins** (\`@mixin flex-center\`) - reusable chunks of CSS, can accept parameters. **Functions** (\`darken($color, 10%)\`) - manipulate values. **Partials and Import** (\`@use 'variables'\`) - split CSS into multiple files and combine them. **Extend/Inheritance** (\`@extend .btn\`) - share CSS properties between selectors. **Control directives** (\`@if\`, \`@for\`, \`@each\`) - logic in stylesheets. **Pros of preprocessors:** variables, mixins, nesting, file organization. **Cons:** adds build step, nesting can create overly specific selectors, may encourage bad practices (deep nesting). **Modern CSS has caught up** - CSS custom properties replace variables, \`:is()\` and \`:where()\` reduce the need for nesting, and CSS native nesting is now available. **Best practice:** use a preprocessor if your project already uses one. For new projects, consider whether you need it. Modern CSS with custom properties, native nesting, and utility classes often eliminates the need for a preprocessor. If using Sass, limit nesting to 3 levels max. Use mixins for browser prefixes and reusable patterns.`,
    codeExplanation: `This SCSS code shows **Sass features**. Variables (\`$primary\`, \`$font-stack\`) store reusable values. Nesting (\`nav { ul { li { a { ... } } } }\`) reflects HTML structure - but this is 4 levels deep, which creates a CSS selector like \`nav ul li a\` (specificity 0,0,0,4). **Avoid deep nesting** - it creates overly specific selectors and large CSS files. The \`@mixin responsive($breakpoint)\` is a parameterized mixin - includes different media query based on argument. \`@include responsive("tablet")\` injects the mixin content. The \`%\` placeholder (\`%card-base\`) with \`@extend\` shares styles without duplicating them in the compiled CSS - \`.card-featured { @extend %card-base }\` groups both selectors together. \`darken($primary, 20%)\` is a built-in function that darkens the color. **Modern CSS alternatives:** \`--primary\` custom properties replace \`$primary\`. CSS \`@media\` queries are standard. CSS native nesting (now supported) replaces Sass nesting. **Preprocessors are still useful for mixins with complex logic** and for projects with existing Sass codebases, but the gap with vanilla CSS is shrinking.**`
  },
  'modern-css-features': {
    explanation: `**Modern CSS** has evolved significantly with powerful new features that reduce the need for preprocessors and JavaScript. These features are widely supported in modern browsers and make CSS more capable than ever.

**Key modern features:** **CSS Custom Properties** (\`--var-name\`) - dynamic variables that can be changed at runtime via JavaScript. **\`:is()\` and \`:where()\`** - reduce selector repetition and manage specificity (\`:where()\` has zero specificity). **CSS Grid** - native grid layout system. **Flexbox** - one-dimensional layout. **Container Queries** - respond to container size, not viewport. **\`clamp()\`, \`min()\`, \`max()\`** - mathematical functions for fluid sizing. \`color-mix()\` - mix colors in CSS. **\`aspect-ratio\`** - maintain element proportions. **\`scroll-snap\`** - snap scrolling behavior. **\`@layer\`** - cascade layers for controlling style precedence. **\`:has()\`** - parent selector (select a parent if it has a specific child). **\`accent-color\`** - style form controls. **\`subgrid\`** - inherit grid tracks from parent. **Animations** - \`@keyframes\`, \`animation-timeline\` (scroll-driven animations). **Best practice:** check browser support (caniuse.com) before using newer features. Use progressive enhancement - provide a fallback for older browsers. CSS custom properties and Grid are safe to use now. Container queries and \`:has()\` have good support in modern browsers (2024+). Modern CSS reduces the need for JavaScript for UI interactions - try the CSS solution first before reaching for JS.`,
    codeExplanation: `This code shows **modern CSS features**. \`:root\` defines **CSS custom properties** for colors and font - these can be changed dynamically with JavaScript (\`document.documentElement.style.setProperty('--primary', 'blue')\`). The \`.card\` uses \`container-type: inline-size\` for **container queries** - \`@container (min-width: 400px)\` queries the container's width, not the viewport. This makes the component truly reusable in different contexts. \`:has(.featured-badge)\` is the **parent selector** - it selects \`.card\` elements that contain a \`.featured-badge\` child. \`accent-color: var(--primary)\` styles the checkbox with the theme color. \`scroll-snap-type: x mandatory\` on the container and \`scroll-snap-align: start\` on children enable **snap scrolling** - the container snaps to each card when scrolling horizontally. \`aspect-ratio: 16/9\` maintains a 16:9 proportion for the image, preventing layout shifts. \`clamp(0.875rem, 2vw, 1.25rem)\` fluidly scales font size. **\`:has()\` is revolutionary** - it finally enables parent-selection in CSS (previously only possible with JavaScript). **Container queries are the biggest advance since Grid/Flexbox** - they make truly reusable, context-independent components possible.**`
  },
  'javascript-basics': {
    explanation: `**JavaScript (JS)** is the programming language that makes web pages interactive. It can change HTML content, respond to user actions like clicks and keyboard input, communicate with servers, and manipulate the browser. JavaScript runs in the user's browser (client-side) and also on servers (Node.js).

**Key concepts:** Variables store data (\`let\`, \`const\`, \`var\`). Data types include numbers, strings (text), booleans (true/false), arrays (lists), and objects (key-value pairs). Functions are reusable blocks of code. Control flow includes \`if/else\` conditions and loops (\`for\`, \`while\`). **JavaScript is dynamically typed** - you don't declare types, and a variable can change from string to number. The DOM (Document Object Model) is JavaScript's interface to HTML - \`document.querySelector()\` finds elements, \`.textContent\` and \`.style\` modify them, and \`.addEventListener()\` responds to events. **Modern JavaScript (ES6+)** introduced \`const\`/\`let\`, arrow functions, template literals, destructuring, modules, and promises. Always use \`const\` by default, \`let\` when you need to reassign, and never use \`var\`.`,
    codeExplanation: `This code demonstrates **JavaScript basics**. Variables: \`const\` for values that won't change (the button), \`let\` for values that will change (the count). \`document.getElementById()\` finds an element by its ID. \`addEventListener('click', callback)\` runs the callback function when the element is clicked. The \`() => { ... }\` (arrow function) is the callback. Inside the callback, \`count++\` increments the counter, and \`counterDisplay.textContent = \\\`Count: \${count}\\\`\` updates the displayed text using a template literal (backticks with \${} interpolation). The \`if (count >= 10)\` condition disables the button by setting \`disabled = true\`. **Template literals with \${} are much cleaner than string concatenation with +.**`
  },
  'functions-scope': {
    explanation: `**Functions and scope** are fundamental JavaScript concepts. A function is a reusable block of code that performs a specific task. **Scope** determines where variables are accessible in your code. JavaScript has **function scope** (var) and **block scope** (let, const). Variables declared with \`var\` are function-scoped; \`let\` and \`const\` are blocked-scoped (accessible only within the nearest set of curly braces).

**Function types:** **Function declarations** are hoisted (can be called before definition). **Function expressions** are not hoisted. **Arrow functions** have shorter syntax and don't have their own \`this\`. **Scope chain:** inner functions can access variables from outer functions, but not vice versa. **Closures** occur when a function "remembers" its lexical scope even when executed outside that scope. **\`this\` binding** depends on how the function is called: in a method, \`this\` refers to the object; in a regular function, it's \`undefined\` (strict mode) or \`window\`; in an arrow function, it's lexically inherited. **Best practice:** Use \`const\` by default. Avoid \`var\`. Use arrow functions for callbacks. Use default parameters. Keep functions small and focused on one task. Functions should do one thing and do it well. A function that takes more than 3 parameters should probably receive an object instead. Name functions clearly - if you need to comment what a function does, rename it.`,
    codeExplanation: `This code demonstrates **functions and scope**. \`function greet\` is a function declaration - it's hoisted, so you can call it before the definition appears in code. \`const square\` is a function expression - not hoisted. \`const createCounter\` demonstrates **closure** - it returns an object with methods that "remember" the \`count\` variable even after \`createCounter()\` has returned. \`counter.increment()\` can access and modify \`count\` because of the closure. **Block scope example:** \`let x = 1\` is declared outside, \`let x = 2\` inside the if block is a **different** variable (separate scope). With \`var\`, the inner declaration would overwrite the outer one. **\`this\` binding:** In the regular function inside \`const user\`, \`this\` refers to the user object (because it's called as a method: \`user.sayHi()\`). In the arrow function, \`this\` is lexically inherited from the surrounding scope. **Arrow functions don't have their own \`this\`** - they inherit it from the parent scope. This makes them ideal for callbacks and event handlers where you want to preserve the outer \`this\`.**`
  },
  'objects-arrays': {
    explanation: `**Objects and arrays** are the two most important data structures in JavaScript. **Arrays** are ordered lists of values - \`const arr = [1, 2, 3]\`. **Objects** are collections of key-value pairs - \`const obj = { name: 'Alice', age: 30 }\`. Arrays use numeric indexes (0-based); objects use named keys.

**Array methods:** \`map()\` transforms each element. \`filter()\` keeps matching elements. \`reduce()\` accumulates values. \`find()\` returns the first match. \`some()\` / \`every()\` test conditions. \`forEach()\` loops without returning. **Object operations:** \`Object.keys()\`, \`Object.values()\`, \`Object.entries()\` for iteration. **Spread operator** copies arrays (\`[...arr]\`) and objects (\`{...obj, newProp: val}\`). **Destructuring** extracts values: \`const { name, age } = obj\`, \`const [first, second] = arr\`. **Mutability:** \`map/filter/reduce\` return new arrays (immutable). \`push/pop/splice\` modify in place (mutable). Prefer immutable operations to avoid bugs. **Nested data:** objects can contain arrays, arrays can contain objects. Access nested data with optional chaining: \`user?.address?.city\`. **Best practice:** use \`const\` for arrays/objects (reference is constant, but contents can change). Use spread or \`structuredClone()\` for copying. Prefer \`map/filter/reduce\` over \`for\` loops for data transformations. Nullish coalescing (\`??\`) for default values.`,
    codeExplanation: `This code demonstrates **objects and arrays in action**. The \`users\` array contains user objects - nested data structure. \`.map()\` transforms each user into a modified copy (with \`isActive: true\` added) - the original array is not modified. \`.filter()\` keeps only users older than 25. \`.reduce()\` groups users by age into an object. Spread operator (\`{...user, isActive: true}\`) creates a shallow copy with an added property. Destructuring (\`{ name, age, ...rest }\`) extracts specific properties and collects the rest. Optional chaining (\`user?.address?.city ?? 'No city'\`) safely accesses deeply nested properties without throwing if intermediate values are null/undefined. The \`??\` provides a fallback. **\`structuredClone()\`** creates a deep copy - unlike spread (which only copies top-level properties), it recursively copies all nested objects. **Map, filter, and reduce are chainable** - \`users.filter(f).map(g)\` first filters, then maps the results. This is cleaner than nested for loops.**`
  },
  'async-javascript': {
    explanation: `**Asynchronous JavaScript** handles operations that take time - API calls, file reads, timers, database queries. Instead of blocking execution while waiting, JavaScript continues running other code and handles the result when ready. This is possible because of the **event loop**.

**Callbacks:** the traditional pattern - pass a function to be called when the operation completes. Problems: callback hell (deeply nested callbacks) and error handling difficulties. **Promises:** an object representing eventual completion/failure. States: pending, fulfilled, rejected. \`fetch()\` returns a Promise. Handle with \`.then()\` (success), \`.catch()\` (error), \`.finally()\` (always runs). \`Promise.all()\` waits for all promises to resolve (fails fast if any rejects). \`Promise.allSettled()\` waits for all to complete regardless of success/failure. \`Promise.race()\` resolves/rejects with the first settled promise. **Async/await:** syntactic sugar over Promises (ES2017). An \`async\` function returns a Promise. \`await\` pauses execution until the Promise resolves. Error handling with try/catch. **The event loop:** JavaScript runs on a single thread. Long synchronous operations block the event loop. Use \`setTimeout()\`, \`requestAnimationFrame()\`, or \`setImmediate()\` to defer work and keep the UI responsive. **Best practice:** always handle Promise rejections (unhandled rejections crash Node.js). Use async/await over raw Promise chains (easier to read and debug). Use \`Promise.all()\` for independent parallel operations. Never block the event loop with synchronous CPU-intensive operations (use Web Workers in browsers or worker threads in Node.js).`,
    codeExplanation: `This code compares **Promises and async/await**. The \`fetchUser\` function uses a Promise chain: \`fetch()\` makes the API call, \`.then(res => res.json())\` parses the response, \`.catch(err => ...)\` handles errors. The async/await version (\`async function loadUserData\`) is cleaner: \`await fetch()\` pauses until the response arrives, \`await res.json()\` waits for parsing. try/catch wraps both. **Async/await is preferred** - stack traces are clearer and the code reads like synchronous code. The \`Promise.all\` example runs three fetches **in parallel** - much faster than awaiting each sequentially. \`Promise.allSettled\` returns results for all promises, even if some fail - useful when you need partial results. \`Promise.race\` resolves with the first completed promise - useful for timeouts (\`Promise.race([fetch(url), timeout(5000)])\`). **The event loop** processes tasks in phases: pending callbacks -> timers -> I/O -> idle -> poll -> check (setImmediate) -> close. Understanding this helps avoid blocking the main thread. **Never use \`await\` in a loop for independent async operations** - use \`Promise.all\` instead for parallel execution.**`
  },
  'es6-features': {
    explanation: `**ES6 (ECMAScript 2015)** was the biggest update to JavaScript, introducing features that fundamentally changed how JavaScript is written. Modern JavaScript development relies heavily on these features.

**Key features:** \`let\` and \`const\` replace \`var\` - block-scoped variables. **Arrow functions** (\`() => {}\`) - shorter syntax, lexical \`this\`. **Template literals** (\`\`string \${expr}\`\`) - interpolation and multi-line strings. **Destructuring** - extract values from arrays/objects. **Spread/rest** (\`...\`) - spread arrays/objects, collect remaining parameters. **Default parameters** - \`function(a = 1)\`. **Enhanced object literals** - shorthand methods and computed property names. **Classes** - syntactic sugar over prototypes. **Modules** - \`import/export\`. **Promises** - built-in async handling. **Symbols** - unique identifiers. **Map, Set, WeakMap, WeakSet** - new collection types. **Iterators and generators** - custom iteration with \`Symbol.iterator\` and \`function*\`. **\`for...of\`** loop - iterate over iterables. **\`Array.from()\`** and **\`Array.of()\`** - array creation methods. **\`.find()\`**, **\`.findIndex()\`**, **\`.includes()\`** - new array methods. **ES7+ additions:** async/await (ES2017), \`Object.entries/values\`, string padding. ES2020: optional chaining (\`?.\`) and nullish coalescing (\`??\`). **Best practice:** use const by default, let only when reassigning. Use arrow functions for short callbacks (but not as methods). Use template literals for all string construction. Use destructuring for cleaner parameter handling in functions. Use modules instead of script tags with global variables.`,
    codeExplanation: `This code demonstrates **ES6+ features**. \`let\` and \`const\` provide block scoping - the \`let i\` in the if block is separate from outer \`let i\`. **Template literals** use backticks with \`\${}\` interpolation - much cleaner than concatenation. **Destructuring** extracts properties into variables and collects remaining with \`...rest\`. **Spread** copies an array/object and can merge or update. **Arrow functions** (\`=>\`) have implicit return for single expressions (no \`return\` keyword needed). **Default parameters** (\`rate = 1\`) handle missing arguments. **Optional chaining** (\`user?.address?.city\`) safely accesses nested properties - returns \`undefined\` if any intermediate value is null/undefined instead of throwing. **Nullish coalescing** (\`??\`) returns the right side only when left is \`null\` or \`undefined\` (NOT for other falsy values like \`0\` or \`""\`). This differs from \`||\` which treats all falsy values the same. **These features are the foundation of modern JavaScript** - you'll use them in every file you write. The compiled output shows how Babel/TypeScript transpiles ES6+ to older syntax for browser compatibility.**`
  },
  'error-handling-debugging': {
    explanation: `**Error handling and debugging** are essential skills for JavaScript developers. Errors are inevitable, and knowing how to handle them gracefully and debug them efficiently separates junior from senior developers.

**Error types:** \`SyntaxError\` (invalid code), \`ReferenceError\` (accessing undefined variable), \`TypeError\` (wrong type operation), \`RangeError\` (value out of range), \`URIError\` (invalid URI). **Try/catch/finally:** \`try { risky() }\` wraps potentially failing code. \`catch(err)\` handles the error. \`finally\` always runs (cleanup). **Throwing errors:** \`throw new Error("message")\`. Create custom errors by extending Error. **Async error handling:** \`.catch()\` for Promises, try/catch for async/await. Unhandled Promise rejections crash Node.js. **Debugging tools:** \`console.log()\`, \`console.error()\`, \`console.table()\`, \`console.time()\`. Browser DevTools: breakpoints, watch expressions, call stack, scope variables. **Debugger statement:** \`debugger;\` pauses execution in DevTools. **Best practice:** handle errors at the appropriate level (don't catch every error in every function - let them propagate to a handler). Use \`finally\` for cleanup (close connections, remove loaders). Never swallow errors silently (empty catch blocks). Log sufficient context. Use source maps for debugging compiled code. Lint your code (ESLint) to catch common errors before runtime. TypeScript catches type-related errors at compile time. Write tests to catch regressions. **Error messages should be meaningful** - tell the developer what went wrong and what they should do to fix it.`,
    codeExplanation: `This code shows **error handling patterns**. \`function divide(a, b)\` throws a \`ValidationError\` (custom error) if b is 0. \`ValidationError extends Error\` creates a custom error type with \`this.name = "ValidationError"\`. The try/catch block catches different error types: \`if (error instanceof ValidationError)\` handles validation failures with a specific message; otherwise, it logs a generic error. The \`finally\` block always runs - here it just logs "Done". The async function \`fetchData\` uses try/catch with await - if \`fetch()\` fails or \`res.json()\` throws, the catch block handles it. **Always check \`response.ok\`** - fetch doesn't reject on HTTP errors (404, 500). You need to manually check \`if (!res.ok)\` and throw. The debugging example shows \`console.table()\` for structured data, \`console.time()/timeEnd()\` for performance measurement, and the \`debugger\` statement. **\`finally\` is guaranteed to run** even if there's a \`return\` or \`throw\` in \`try\` or \`catch\`. This makes it ideal for cleanup operations.**`
  },
  'js-design-patterns': {
    explanation: `**Design patterns** are reusable solutions to common programming problems. In JavaScript, patterns are often less formal than in class-based languages because JavaScript's flexibility (first-class functions, dynamic typing, prototypal inheritance) provides alternative approaches. Still, understanding common patterns helps you write better-organized code.

**Module Pattern:** Encapsulates private data and exposes a public API using closures. Before ES6 modules, this was the standard way to organize code. **Singleton:** Ensures a class has only one instance. In JavaScript, modules are naturally singletons. **Factory Pattern:** Creates objects without specifying the exact class. Useful when object creation involves complex logic. **Observer Pattern:** One object (subject) notifies many observers of state changes. Event emitters in Node.js use this pattern. **Pub/Sub (Publish/Subscribe):** Similar to Observer but decoupled via a message broker. **Mixin Pattern:** Combines behaviors from multiple objects. **Decorator Pattern:** Adds behavior to objects dynamically. **Proxy Pattern:** Controls access to another object. JavaScript's \`Proxy\` built-in implements this. **Revealing Module Pattern:** A variation of Module pattern where all methods and properties are defined privately and only selectively exposed. **Best practice:** Use patterns when they solve a real problem, not just because they're patterns. Over-engineering with patterns is a common mistake. JavaScript's built-in features (modules, classes, Proxies) often make formal patterns unnecessary. The most important pattern in modern JS is **Composition over Inheritance** - build complex objects by combining simple pieces. Keep it simple first; add patterns when complexity demands structure.`,
    codeExplanation: `This code shows **common JavaScript design patterns**. The **Module Pattern** uses an IIFE (Immediately Invoked Function Expression) to create a closure - \`count\` is private, and only the returned methods can access it. The shopping cart API exposes addItem, removeItem, and getItems while hiding the internal \`items\` array. The **Observer Pattern** implements a simple event system - \`subscribe\` registers listeners, \`unsubscribe\` removes them, \`notify\` calls all listeners with the data. \`forEach(callback => callback(data))\` iterates over all subscribed callbacks. Each listener runs independently. The **Singleton Pattern** uses \`instance\` to ensure only one instance exists - \`if (instance) return instance; instance = this;\`. The **Factory Pattern** creates different types of notification senders based on the \`type\` parameter - returns an email sender, SMS sender, or push notification sender. **The Observer/Pub-Sub pattern is the foundation of event-driven architecture** - it's used in DOM events, Node.js EventEmitter, and frontend state management (Redux, Zustand). The Singleton is useful for shared resources (database connections, configuration) but can make testing difficult.**`
  },
  'advanced-types': {
    explanation: `**Advanced TypeScript types** enable you to model complex data shapes and enforce business rules at compile time. These features make TypeScript incredibly powerful for large-scale applications where type safety is critical.

**Discriminated unions:** Types with a common property (discriminant) whose value determines the specific shape of the object. TypeScript narrows the type when you check the discriminant. \`type Result<T> = { status: 'success'; data: T } | { status: 'error'; message: string }\`. **Mapped types:** Transform existing types by iterating over their keys. \`type Readonly<T> = { readonly [K in keyof T]: T[K] }\`. **Conditional types:** Types that depend on a condition. \`T extends U ? X : Y\`. **Template literal types:** Create types from string patterns. \`type EventName = \`on\${Capitalize<string>}\`\`. **Infer keyword:** Extract types from within conditional types. \`type ReturnType<T> = T extends (...args: any[]) => infer R ? R : never\`. **Satisfies operator:** Validates a type without changing inference. **Branded types:** Create nominal typing with a unique brand property. \`type UserId = string & { __brand: 'UserId' }\`. **Utility types:** \`Awaited<T>\`, \`ReturnType<T>\`, \`Parameters<T>\`, \`NonNullable<T>\`, \`Record<K,V>\`. **Best practice:** Use discriminated unions for API responses and state machines. Use template literal types for strongly-typed event handlers. Use \`satisfies\` when you want type checking without widening. Don't over-complicate types - if a type is too complex to understand, it's probably too complex to maintain. Document advanced types with comments. Prefer simplicity over cleverness.`,
    codeExplanation: `This code shows **advanced TypeScript types**. The \`Result<T>\` discriminated union has a \`status\` discriminant - inside the \`if (result.status === 'success')\` block, TypeScript knows \`result.data\` exists and is of type \`T\`. In the \`else\` (error) branch, \`result.message\` exists. This pattern makes **impossible states impossible** - you can't have a result that's both success and error. The \`DeepReadonly<T>\` mapped type uses **recursive conditional types** - if a property is an object (not a function), recursively apply DeepReadonly; otherwise, make it readonly. The \`ExtractPromise<T>\` type uses \`infer\` to extract the resolved type from a Promise - \`ExtractPromise<Promise<number>>\` evaluates to \`number\`. The \`Brand\` type creates a **branded type** - \`UserId\` is a \`string & { __brand: 'UserId' }\`. You can't accidentally assign a plain string where a UserId is expected. The \`EventName\` template literal type creates a type from string pattern - \`onClick\`, \`onChange\`, etc. **Discriminated unions are the most practical advanced type** - they model API responses, form states, and workflow steps with full type safety. TypeScript ensures you handle every case.**`
  },
  'typescript-react': {
    explanation: `**TypeScript with React** provides type safety for components, props, state, and events. This eliminates entire categories of bugs (wrong prop types, missing required props, incorrect event handlers) and provides excellent autocomplete. TypeScript with React is now the standard for professional React development.

**Typing props:** Define an interface for props and type the component with it. \`interface ButtonProps { label: string; onClick: () => void; variant?: 'primary' | 'secondary' }\`. \`const Button: React.FC<ButtonProps> = ({ label, onClick, variant = 'primary' }) => ...\`. Or use a regular function: \`function Button({ label, onClick }: ButtonProps)\`. **Typing state:** TypeScript infers state types from the initial value. For complex state, use discriminated unions. \`const [user, setUser] = useState<User | null>(null)\`. **Typing events:** \`onChange: (e: React.ChangeEvent<HTMLInputElement>) => void\`, \`onClick: (e: React.MouseEvent<HTMLButtonElement>) => void\`. **Typing refs:** \`const inputRef = useRef<HTMLInputElement>(null)\`. **Typing children:** \`children: React.ReactNode\` (accepts any renderable content). **Generic components:** Components that work with multiple types. \`function List<T>({ items, render }: ListProps<T>)\`. **Typing hooks:** Custom hooks return typed values. \`function useLocalStorage<T>(key: string, initial: T): [T, (value: T) => void]\`. **Best practice:** define props interface in the component file (or colocated). Use \`interface\` for public props, \`type\` for complex unions. Use \`React.FC\` or regular functions - both are fine. Prefer explicit return types for public components. Use \`as const\` for literal types. Use \`satisfies\` to validate objects without widening types. Use utility types like \`React.ComponentProps<typeof Button>\` to extract props from existing components.`,
    codeExplanation: `This code shows **TypeScript with React**. \`interface User\` defines the user data structure - used for both state and props. \`interface UserProfileProps\` defines component props with required (\`user\`), optional (\`showEmail?\`), and callback (\`onUpdate\`) properties. \`const UserProfile: React.FC<UserProfileProps>\` types the component - TypeScript validates that all required props are passed. \`const [user, setUser] = useState<User | null>(null)\` types state - \`user\` can be a \`User\` object or \`null\`. \`onChange: (e: React.ChangeEvent<HTMLInputElement>) => void\` types the change event - \`e.target.value\` is typed as string. \`const inputRef = useRef<HTMLInputElement>(null)\` types the ref - \`inputRef.current\` is typed as \`HTMLInputElement | null\`. The generic component \`List<T>\` works with any item type - \`items: T[]\` and \`render: (item: T) => React.ReactNode\`. The custom hook \`useLocalStorage<T>\` is generic - it returns \`[T, (value: T) => void]\`. \`children: React.ReactNode\` accepts any renderable React content (string, JSX, fragments, null). **TypeScript catches prop errors at compile time** - passing a missing required prop or wrong type shows a red underline in the editor before you even run the code.**`
  },
  'typescript-decorators': {
    explanation: `**TypeScript decorators** are special functions that can be attached to classes, methods, properties, accessors, and parameters to modify their behavior. They're a stage 2 TC39 proposal (experimental) and are commonly used in Angular and NestJS. Enable with \`experimentalDecorators: true\` in tsconfig.

**Types of decorators:** **Class decorators** receive the constructor and can modify or replace it. **Method decorators** receive the target, method name, and property descriptor - useful for logging, memoization, or modifying method behavior. **Property decorators** receive the target and property name. **Accessor decorators** (getter/setter). **Parameter decorators** receive target, method name, and parameter index. **Decorator factories:** Functions that return a decorator function, allowing configuration. \`@log('Auth')\`. **Execution order:** decorators are applied top-to-bottom (for declaration order) but executed bottom-to-top (for evaluation). **Use cases:** dependency injection (Angular), routing (NestJS), validation, logging, memoization, authentication guards, serialization. **Best practice:** decorators are powerful but make code implicit. Use them consistently and document their behavior. Prefer higher-order functions or wrapper patterns when decorators aren't needed. Decorators can't decorate functions (only class members). Use them when a framework requires them (Angular, NestJS, TypeORM). For React/Vue projects, decorators are rarely needed. The TC39 proposal is still evolving - the experimental implementation may change. Consider alternatives like wrapper functions or HOCs for simpler cases.`,
    codeExplanation: `This code shows **TypeScript decorators in action**. \`@sealed\` is a class decorator that calls \`Object.freeze()\` on the constructor and prototype - prevents adding new properties. \`@log\` is a decorator factory - it takes a prefix argument and returns a method decorator. The method decorator wraps the original method with logging: it logs "Calling prefix.methodName" before execution and "prefix.methodName completed" after. It creates a new function, calls the original with the same arguments, and returns the result. The property descriptor (\`descriptor.value\`) gives access to the original method. \`@readonly\` is a property decorator that uses \`Object.defineProperty\` to make the property writable: false. \`@validate\` is a parameter decorator that stores metadata about which parameters should be validated - the \`validateParams\` array maps parameter indices to validation status. **Decorator execution order:** property decorators run first (bottom-up), then method decorators, then parameter decorators, then class decorators. Within the same type, execution is bottom-up (the decorator closest to the class runs first). **Decorators are primarily used by frameworks** - in plain React/Vue/Express apps, you typically don't need them.**`
  },
  'typescript-configuration': {
    explanation: `**TypeScript configuration** is managed through \`tsconfig.json\`. This file controls compiler options, which files to include/exclude, module resolution, output settings, and strictness levels. A well-configured tsconfig is essential for getting the most out of TypeScript.

**Key options:** \`target\`: which ECMAScript version to compile to (ES2020, ES2022). \`module\`: module system (CommonJS, ESNext, Node16). \`strict: true\`: enables all strict type-checking options (recommended). Individual strict options: \`strictNullChecks\` (prevents null/undefined assignment), \`noImplicitAny\` (errors on implicit any), \`strictFunctionTypes\` (proper function type variance), \`strictBindCallApply\`. \`outDir\`: compiled JavaScript output folder. \`rootDir\`: source root. \`include\`: glob patterns for files to compile. \`exclude\`: files to skip. \`paths\`: module alias mapping (\`@/\` -> \`src/*\`). \`esModuleInterop\`: better interoperability between CommonJS and ES modules. \`resolveJsonModule\`: import JSON files. \`declaration\`: generate \`.d.ts\` declaration files. \`sourceMap\`: generate source maps for debugging. \`composite\`: for project references (monorepos). **tsconfig inheritance:** \`extends\` base configuration. **Best practice:** always enable \`strict: true\`. Set \`target\` to at least ES2020. Use \`Node16\` or \`NodeNext\` module resolution for Node.js projects. Use \`ESNext\` for frontend and let bundler (Vite, webpack) handle module resolution. Configure \`paths\` for clean imports. Enable \`sourceMap\` for debugging. Use \`composite\` and project references for monorepos. Keep separate tsconfigs for app and tests (\`tsconfig.json\` and \`tsconfig.test.json\`). Don't ignore TypeScript errors - if a type error exists, fix it or explicitly cast rather than using \`@ts-ignore\`.`,
    codeExplanation: `This \`tsconfig.json\` shows **production-ready TypeScript configuration**. \`compilerOptions\`: \`target: ES2022\` targets modern JavaScript. \`module: Node16\` uses Node.js's native module resolution. \`strict: true\` enables all strict checks. \`esModuleInterop: true\` allows \`import express from 'express'\` (default imports from CommonJS modules). \`resolveJsonModule: true\` allows importing \`.json\` files. \`declaration: true\` generates \`.d.ts\` files for library consumers. \`sourceMap: true\` enables source maps for debugging. \`outDir: ./dist\` puts compiled JS in dist/. \`rootDir: ./src\` specifies the source root. \`paths\` defines module aliases - \`@/*\` maps to \`./src/*\` so you can do \`import { User } from '@/models'\` instead of relative paths. \`include\` specifies which files to compile. \`exclude\` skips node_modules and test files. **Separate test config:** \`tsconfig.test.json\` extends the base config but includes test files and uses a different module type. **\`strict: true\` is non-negotiable** - it catches null reference errors, implicit any, and other common bugs. The \`paths\` configuration also needs a corresponding \`resolve.alias\` in your bundler (Vite, webpack) to work at runtime.**`
  },
  'react-fundamentals': {
    explanation: `**React** is a JavaScript library for building user interfaces. It's based on **components** - reusable, self-contained pieces of UI that manage their own state. React is **declarative**: you describe what the UI should look like for a given state, and React efficiently updates the DOM when state changes.

**Core concepts:** **JSX** - JavaScript syntax extension that looks like HTML. JSX expressions use \`{}\` braces. **Components** are functions that return JSX. **Props** are read-only data passed from parent to child. **State** (\`useState\`) is data that changes over time - React re-renders the component when state updates. **The Virtual DOM** - React creates a lightweight copy of the DOM, calculates the difference (diffing) between old and new virtual DOM, and applies only the minimal changes to the real DOM. **Unidirectional data flow:** data flows down from parent to child via props, and events flow up via callbacks. **Conditional rendering:** \`{condition && <Component />}\` or \`{condition ? <A /> : <B />}\`. **Lists and keys:** use \`.map()\` to render arrays, each item needs a unique \`key\` prop for efficient updates. **Best practice:** keep components small and focused (single responsibility). Use meaningful names. Extract reusable logic into custom hooks. Prefer composition over inheritance. Keep state as local as possible - only lift it up when multiple components need it. Use \`React.memo\` for performance optimization when needed. Start with a functional approach - classes are legacy. Always handle loading, error, and empty states. Use TypeScript for prop types.`,
    codeExplanation: `This is a **React fundamentals example**. \`useState\` manages the todo list and input value. \`handleSubmit\` adds a new todo with a unique ID (\`Date.now()\`) and clears the input. \`handleToggle\` uses \`.map()\` to create a new array with the toggled todo - this is **immutable state update** (don't modify state directly). The JSX renders: a form with controlled input, the todo count, and the list. \`.map()\` renders each todo with a checkbox and text. The \`key={todo.id}\` prop is essential for React to track list items efficiently. The checkbox uses \`checked={todo.completed}\` (controlled) and toggles completion state. The delete button removes the todo with \`.filter()\`. **Conditional rendering:** the "No todos yet" message only shows when \`todos.length === 0\`. The count text changes based on completed count (pluralization). **State updates are asynchronous** - React batches them for performance. Don't rely on the previous state value without using the functional form: \`setTodos(prev => [...prev, newTodo])\`. **Every item in a mapped list needs a unique, stable key** - avoid array index as key for dynamic lists.**`
  },
  'state-hooks': {
    explanation: `**React Hooks** let you use state and other React features in functional components. Introduced in React 16.8, hooks replaced class components as the primary paradigm. The most important hooks: \`useState\`, \`useEffect\`, \`useContext\`, \`useRef\`, \`useMemo\`, \`useCallback\`, \`useReducer\`, and \`useTransition\`.

**useState:** \`const [state, setState] = useState(initialValue)\`. The setter can accept a new value or a function (\`setState(prev => prev + 1)\`). **useEffect:** handles side effects (fetching, subscriptions, timers). The dependency array controls when it re-runs: empty \`[]\` = run once (mount), omitted = run after every render, with values = run when values change. The cleanup function prevents memory leaks. **useContext:** access React context without prop drilling. **useRef:** mutable value that persists across renders without causing re-renders. Common uses: accessing DOM elements, storing previous values, interval IDs. **useMemo:** memoizes computed values - only recomputes when dependencies change. **useCallback:** memoizes function references - prevents unnecessary child re-renders when passed as props. **useReducer:** like useState but for complex state logic (multiple sub-values, dependency on previous state). Uses a reducer function (state, action) => newState. **useTransition:** marks state updates as non-urgent, keeping the UI responsive during expensive updates. **Rules of Hooks:** only call hooks at the top level (not inside loops, conditions, or nested functions). Only call hooks from React function components or custom hooks. The order of hooks must be consistent across renders. Lint with eslint-plugin-react-hooks to catch violations.`,
    codeExplanation: `This code demonstrates **five key hooks**. \`useState\` manages form input, users list, and loading state. \`useEffect\` fetches users on mount - the empty \`[]\` dependency ensures it runs once. The cleanup function (\`AbortController\`) cancels the fetch if the component unmounts. \`useRef\` creates a ref that focuses the input when the component mounts (\`inputRef.current?.focus()\`). Ref values persist across renders and don't cause re-renders when changed. \`useMemo(() => filteredUsers, [filter]\` memoizes the filtered list - only recomputes when \`filter\` or \`users\` change. Without this, \`filteredUsers\` would be computed on every render. \`useCallback(() => addUser(input), [input]\` memoizes the function reference - if passed to a child component wrapped in \`React.memo\`, the child won't re-render unnecessarily. \`useReducer\` manages complex state: \`{ users: [], loading: false, error: null }\`. The reducer handles "FETCH_START", "FETCH_SUCCESS", and "FETCH_ERROR" actions. This is cleaner than multiple useState calls for related state. **The dependency array is critical** - missing dependencies cause bugs (stale closures). The ESLint exhaustive-deps rule catches missing dependencies automatically.**`
  },
  'react-component-patterns': {
    explanation: `**React component patterns** are reusable solutions to common UI challenges. They help organize code, improve reusability, and handle complex scenarios. Understanding these patterns is essential for building maintainable React applications.

**Compound Components:** Multiple components that work together to form a cohesive unit. Example: \`<Select>\`, \`<Select.Option>\`, \`<Select.Options>\`. The parent manages state, children communicate through context. **Render Props:** A component that takes a function prop (\`render\`) that returns JSX. The component calls the function with its internal state. \`<DataFetcher url="/api" render={(data) => <div>{data}</div>} />\`. **Higher-Order Components (HOC):** A function that takes a component and returns an enhanced component. \`const EnhancedComponent = withAuth(WrappedComponent)\`. Mostly replaced by hooks. **Custom Hooks:** Extract reusable stateful logic into a function starting with \`use\`. \`function useWindowSize() { ... return { width, height } }\`. **Context + useReducer:** Global state management without external libraries (Redux alternative). **Controlled vs Uncontrolled:** Controlled components manage their own state; uncontrolled components delegate state to the DOM. **Container/Presentational:** Split data-fetching logic (container) from rendering (presentational). Modern hooks make this less necessary. **Asynchronous Component Patterns:** Loading states, error boundaries, Suspense integration. **Best practice:** prefer custom hooks over HOCs (simpler, no wrapper hell). Use compound components for flexible, composable UIs. Use render props sparingly (can lead to deeply nested code). Error boundaries (class components with \`componentDidCatch\`) are still needed for error handling. Keep patterns simple - over-engineering is a common trap. A plain component with well-organized code is often the best pattern.`,
    codeExplanation: `This shows **compound components** using Context. The \`Tabs\` component creates a context with \`activeTab\` and \`setActiveTab\`. \`Tabs.Tab\` is a child component that uses the context: it checks if its \`label\` matches \`activeTab\` and calls \`setActiveTab\` on click. \`Tabs.Panel\` shows its children only when its \`label\` matches the active tab. This allows flexible composition: \`<Tabs><Tabs.Tab label="A" /><Tabs.Panel label="A">Content</Tabs.Panel></Tabs>\`. The custom hook \`useWindowSize\` demonstrates **custom hook pattern** - it encapsulates window resize logic with \`useEffect\` (add/remove event listener) and returns the current dimensions. Any component can use \`const { width, height } = useWindowSize()\` without duplicating the resize logic. The **Error Boundary** catches rendering errors in its children and shows a fallback UI instead of crashing the whole app. **Compound components are flexible** - the parent doesn't control the order or styling of children; the consumer decides. This is the pattern used by libraries like Radix UI. **Custom hooks are the most important pattern** - they're the primary way to share logic between components. If you find yourself duplicating \`useEffect\` logic, extract it into a custom hook.**`
  },
  'state-management': {
    explanation: `**State management** in React is about handling data that changes over time across your application. While local state (\`useState\`) works for individual components, global state management is needed when multiple distant components need to share and update the same data.

**Approaches (from simple to complex):** **Lifting state up** - move state to a common parent and pass down via props. Works for closely-related components. **React Context** - share state across the component tree without prop drilling. Good for themes, auth, locale. \`useContext\` + \`useReducer\` can handle most global state needs. **Zustand** - minimal external library (1KB). Simple API, no boilerplate. \`const useStore = create((set) => ({ count: 0, increment: () => set((state) => ({ count: state.count + 1 })) }))\`. **Jotai** - atomic state management. Similar to Recoil but simpler. **Redux Toolkit** - the most popular full-featured solution. Provides a centralized store, reducers, middleware (thunks, sagas), DevTools. RTK simplifies the older Redux boilerplate with \`createSlice\` and \`configureStore\`. **TanStack Query (React Query)** - server state management. Handles caching, refetching, pagination, optimistic updates for API data. **Zustand vs Redux:** Zustand is simpler with less boilerplate; Redux has more structure, middleware ecosystem, and DevTools. Start with Context + useReducer, move to Zustand when Context becomes cumbersome, use Redux for large teams that need strict patterns. **Best practice:** keep server state separate from UI state (use TanStack Query for API data, local/context state for UI). Don't put everything in global state - most state should be local. If only one component needs a piece of state, keep it there - don't prematurely globalize. Normalize nested data in stores. Use selectors for derived data.`,
    codeExplanation: `This code compares **state management approaches**. **Zustand** creates a store with \`create()\` - it returns a hook. The store defines both state and actions together. Components use the hook to access state: \`const { count, increment, reset } = useCounterStore()\`. Zustand automatically optimizes re-renders - components only re-render when the slices they select change. **Redux Toolkit** with \`createSlice\` defines a slice with name, initial state, and reducers. \`configureStore\` creates the store. Components use \`useSelector\` to read and \`useAppDispatch\` to dispatch actions. Redux requires a Provider wrapper. **TanStack Query** (\`useQuery\`) fetches and caches server data. \`queryKey: ['users']\` identifies the query. \`queryFn\` is the fetch function. It provides \`data\`, \`isLoading\`, \`error\`, \`refetch\` - no manual loading/error state management needed. \`useMutation\` handles create/update/delete operations with automatic cache invalidation (\`invalidatesQueries\`). **The trend is moving away from Redux** - Zustand handles client state more simply, and TanStack Query handles server state better than Redux ever did. For new projects: local state (\`useState\`) + React Query (server) + Zustand or Context (global client state).**`
  },
  'testing-react': {
    explanation: `**Testing React components** ensures they work correctly and prevents regressions. The standard approach combines **unit tests** (testing functions and hooks), **component tests** (testing components with user interactions), and **integration tests** (testing page-level behavior). Vitest (fast, Vite-native) has largely replaced Jest for new projects, with React Testing Library for component testing.

**React Testing Library** focuses on testing from the user's perspective - you test what the user sees and interacts with, not implementation details. **Queries:** \`getByRole\` (preferred - finds by ARIA role), \`getByText\`, \`getByLabelText\` (form inputs), \`getByTestId\` (last resort, uses \`data-testid\`). **Async queries:** \`findBy*\` (returns a Promise, waits for element to appear), \`waitFor\` (waits for assertion to pass). **User events:** \`@testing-library/user-event\` simulates real user interactions (typing, clicking, tabbing). More realistic than \`fireEvent\`. **Mocking:** \`vi.mock('module')\` mocks imports. \`vi.spyOn(obj, 'method')\` spies on methods. MSW (Mock Service Worker) intercepts network requests at the protocol level. **Snapshot testing:** captures component output and compares on subsequent runs - useful but fragile. **Coverage:** aim for high coverage on critical logic, not 100% line coverage. **Best practice:** test behavior, not implementation. Use accessible queries (getByRole, getByLabelText). Test user flows, not isolated renders. Test error states and edge cases. Don't test React internals (no need to test if useState works). Keep tests simple - if a test is hard to write, the component may need to be simplified. Use \`data-testid\` sparingly. Use \`screen\` object methods. Mock at the network level (MSW) rather than module level when possible. Write integration tests for critical user journeys.`,
    codeExplanation: `This code shows **component testing with React Testing Library**. \`render(<Counter />)\` renders the component in a test environment. \`screen.getByRole('button', { name: /count is/i })\` finds the button by its accessible role and text content - this is the recommended approach (tests what users see/interact with). \`await user.click(button)\` simulates a click using user-event - it's more realistic than \`fireEvent.click\` because it triggers hover, focus, and other events that real clicks do. \`expect(screen.getByText(/count is 1/i)).toBeInTheDocument()\` verifies the text changed after the click. **Testing async behavior:** \`screen.findByText\` (returns Promise) waits for text to appear - useful when data is loaded asynchronously. \`waitFor\` waits for an assertion to pass within a timeout. **\`describe\`** and \`it\` organize tests - \`describe('Counter', () => { it('increments count', ...) })\`. **Accessible queries are preferred** because they work regardless of CSS/structure changes and encourage accessible code. If you can't find an element by role or label, it's probably not accessible. **Test one behavior per test case.** Keep tests focused and independent. Each test should set up its own state (don't share mutable state between tests). Use \`beforeEach\` for common setup.**`
  },
  'server-components': {
    explanation: `**React Server Components (RSC)** are a new paradigm introduced in React 18 and popularized by Next.js 13+ App Router. They allow components to run **on the server** during rendering, sending only the resulting HTML (or a serialized representation) to the client. This reduces JavaScript bundle size and enables direct access to server-side resources (databases, file systems).

**Server Components vs Client Components:** Server components run on the server, can access databases directly, and stay on the server (no JS sent to browser). Client components (marked with \`'use client'\`) run in the browser with full interactivity (hooks, event handlers, browser APIs). **Key benefits:** zero client-side JavaScript for server components, direct database access without API endpoints, automatic code splitting, smaller bundles. **What server components CAN'T do:** use state (\`useState\`), effects (\`useEffect\`), event handlers, browser APIs, or custom hooks that use these features. For that, use client components. **Data fetching in RSC:** you can \`await fetch()\` or directly query a database inside the component - no need for \`useEffect\` or React Query on the server. **Composition pattern:** server components can import and render client components. Client components can accept server components as \`children\` (passed as props). **Streaming:** RSC supports streaming - the page can start rendering before all data is loaded. **Best practice:** make as many components server components as possible. Move "use client" to the leaves of the component tree. Use server components for data fetching and static rendering. Use client components only for interactivity. Pass server component results as props/children to client components rather than fetching data separately. Understand the "server component -> client component" boundary - once you cross to client, you can't go back to server.`,
    codeExplanation: `This code shows **Server Components vs Client Components** in Next.js App Router. \`export default async function HomePage()\` is a **Server Component** - it's \`async\` and directly fetches data with \`fetch()\`. No \`useEffect\` or loading state needed - the component \`await\` the data and renders it. The \`PostList\` component is also a server component - it maps over posts and renders HTML. The \`'use client'\` directive on \`InteractiveButton\` makes it a **Client Component** - it can use \`useState\` for tracking clicks and \`onClick\` for handling events. Client components can't be async. **Data flow:** the page component fetches all data and passes it as props to both server and client children. The client component receives \`postId\` and can call the API (\`/api/posts/\${postId}/like\`) when the button is clicked. **The boundary:** you can import server components from server components. You can NOT import server components from client components. You can pass server components as \`children\` to client components. **The key insight:** Next.js automatically bundles only the client components' JavaScript. InteractiveButton's JavaScript is sent to the browser, but PostList's code stays entirely on the server. This dramatically reduces bundle size for pages with mostly static content.**`
  },
  'nextjs-basics': {
    explanation: `**Next.js** is a React framework that provides server-side rendering (SSR), static site generation (SSG), routing, API routes, and more out of the box. It's the most popular React framework for production applications. The two approaches: **Pages Router** (traditional, file-based routing in \`/pages\`) and **App Router** (newer, uses \`/app\` directory with React Server Components, introduced in Next.js 13).

**Key features:** **File-based routing** - files in \`/app\` or \`/pages\` automatically become routes. **Server Components** by default in App Router. **Layouts** - persistent UI that doesn't re-render on navigation (\`layout.tsx\`). **Loading and Error states** - \`loading.tsx\` and \`error.tsx\` files automatically handle loading/error UI. **Data fetching** - \`fetch()\` with automatic caching and revalidation. **Server Actions** - call server functions directly from client components (form handling). **API Routes** - create API endpoints in \`/api\` directory. **Middleware** - run code before requests complete (redirects, rewrites, auth checks). **Image Optimization** - \`next/image\` for automatic image optimization. **Font Optimization** - \`next/font\` for optimized fonts. **Static Generation (SSG)** - HTML generated at build time. **Server-Side Rendering (SSR)** - HTML generated on each request. **ISR (Incremental Static Regeneration)** - update static pages after deployment without rebuilding. **Best practice:** use App Router for new projects. Prefer server components. Use \`loading.tsx\` for streaming. Configure \`next.config.js\` for images, redirects, and headers. Use environment variables (\`NEXT_PUBLIC_\* prefix for client-side\`). Leverage static generation where possible (blogs, docs). Use ISR for pages that need periodic updates. Use SSR for personalized pages. Deploy to Vercel for optimal performance.`,
    codeExplanation: `This is a **Next.js App Router page**. \`app/layout.tsx\` defines the root layout - it wraps all pages. \`metadata\` export sets the page title and description (SEO). \`{children}\` renders the page content. \`app/posts/[id]/page.tsx\` is a dynamic route (note the \`[id]\` folder). \`generateStaticParams\` tells Next.js which paths to pre-render at build time (SSG). The page component is \`async\` - it directly \`await fetch()\` the data. \`notFound()\` shows the 404 page if post is null. \`export const revalidate = 3600\` enables **ISR** - the page is re-generated at most every hour. \`app/loading.tsx\` shows a skeleton loader while the page loads. \`app/error.tsx\` catches errors and shows a retry button (\`reset()\`). **The file structure determines routes** - \`/app/posts/[id]/page.tsx\` creates the route \`/posts/:id\`. **Layouts persist across navigations** - the header in layout.tsx won't re-render when navigating between posts. **Loading, Error, and Not Found boundaries** are automatic per route segment - you don't need to manually manage loading states. Next.js also optimizes images with \`next/image\`, handles font loading with \`next/font\`, and manages metadata through the \`metadata\` export.**`
  },
  'nextjs-data-fetching': {
    explanation: `**Data fetching in Next.js** has evolved significantly. In the App Router, data fetching is built into server components - you can \`await fetch()\` or query a database directly in the component. No \`useEffect\`, no React Query needed on the server. Next.js extends the native \`fetch()\` with caching and revalidation options.

**Caching strategies:** **Static (default):** \`fetch(url)\` - data is fetched at build time and cached indefinitely. **Dynamic:** \`fetch(url, { cache: 'no-store' })\` - data is fetched on every request (SSR). **Revalidating:** \`fetch(url, { next: { revalidate: 3600 } })\` - cached for 1 hour, then re-fetched (ISR). **Deduplication:** Next.js automatically deduplicates fetch requests - if two components fetch the same URL, only one request is made. **Direct database access:** In server components, you can directly import and query your database (no API endpoint needed): \`const user = await db.user.findUnique({ where: { id } })\`. **Parallel data fetching:** Use \`Promise.all()\` to fetch multiple resources in parallel instead of awaiting each sequentially. **Sequential data fetching:** await one fetch before another when the second depends on the first. **Client-side fetching:** For interactive data (real-time updates, user-specific data after page load), use \`useEffect\` or a library like React Query/SWR in client components. **Server Actions:** Call server functions from client components via \`'use server'\` - useful for form submissions and mutations. **Best practice:** prefer server component data fetching (faster, caches better). Use React Query only for client-side data that needs real-time updates. Leverage ISR for content that changes periodically. Use \`generateStaticParams\` for dynamic routes with known paths. Avoid waterfall requests (fetching in sequence when parallel is possible). Handle loading states with \`loading.tsx\` and error states with \`error.tsx\`.`,
    codeExplanation: `This code shows **Next.js data fetching patterns**. Server Components can \`await fetch()\` directly. \`cache: 'force-cache'\` (default) caches the fetch. \`next: { revalidate: 60 }\` enables ISR - re-fetches every 60 seconds. Direct database access with Prisma (\`await db.posts.findMany()\`) works inside server components - no API endpoint needed. **Parallel fetching** with \`Promise.all([fetchPosts(), fetchUsers()])\` starts both fetches simultaneously, reducing total load time. **Sequential fetching** (\`const user = await fetchUser(); const posts = await fetchUserPosts(user.id)\`) when the second request depends on the first. The **Server Action** (\`'use server'\`) is a function that runs on the server but can be called from client components. It receives \`formData\` (for form submissions) and can return data. \`useActionState\` hook calls the server action and tracks its state (\`isPending\`, \`data\`). **Server Actions are the recommended way to handle form submissions and mutations in the App Router** - they work without JavaScript enabled (progressive enhancement), handle CSRF protection automatically, and don't require API endpoint boilerplate. For client-side fetching, use React Query's \`useQuery\` - it handles caching, refetching, and optimistic updates. **Choose the right strategy:** SSG for content, SSR for dynamic data per request, ISR for mostly-static content that needs occasional updates, client-side for real-time user-specific data.**`
  },
  'nextjs-api-routes': {
    explanation: `**Next.js API Routes** allow you to create API endpoints within your Next.js application. In the Pages Router, files in \`/pages/api/\` become API routes. In the App Router, you use Route Handlers in \`/app/api/\` with the \`route.ts\` file convention. API routes run on the server and are not included in the client bundle.

**Route Handlers (App Router):** \`export async function GET(request: NextRequest) { ... }\`. Export named functions for HTTP methods: GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS. **Request object:** \`NextRequest\` extends the standard Request with helpers: \`request.nextUrl.searchParams.get('q')\`, \`request.cookies\`, \`request.headers\`. **Response:** return \`NextResponse.json(data)\` or \`new Response(body, { status, headers })\`. **Dynamic routes:** \`app/api/posts/[id]/route.ts\` handles \`/api/posts/:id\`. **Middleware:** \`middleware.ts\` in the project root runs before every request - use for redirects, rewrites, headers, and auth checks. **CORS:** configure CORS headers in the route handler or middleware. **Edge Runtime:** Route handlers can run on the Edge (faster, globally distributed) instead of Node.js. Use \`export const runtime = 'edge'\`. Edge has limited APIs (no Node.js fs, no database drivers). **Rate limiting, authentication, logging:** can be implemented in route handlers or middleware. **Best practice:** keep API routes simple - they should be thin wrappers over your business logic. Use middleware for cross-cutting concerns (auth, CORS, rate limiting). Validate request bodies with Zod. Return consistent error responses. Use Route Handlers instead of Pages Router API routes for new projects. For complex APIs, consider a separate backend (Express, Fastify, NestJS) instead of putting everything in Next.js API routes. Server Actions often replace simple API routes for mutations.`,
    codeExplanation: `This code shows **Next.js Route Handlers**. \`app/api/posts/route.ts\` handles \`GET /api/posts\` (with optional \`?author=\` filter) and \`POST /api/posts\`. \`export async function GET(request: NextRequest)\` defines the GET handler. \`request.nextUrl.searchParams.get('author')\` reads query parameters. \`NextResponse.json(posts)\` returns JSON. \`app/api/posts/[id]/route.ts\` handles dynamic routes - \`context.params.id\` extracts the route parameter. \`export async function PATCH(request: NextRequest, context: { params: { id: string } })\` handles partial updates. \`request.json()\` parses the request body. **Middleware:** \`middleware.ts\` runs before every request. \`request.nextUrl.pathname.startsWith('/api')\` checks if the request is for an API route. \`NextResponse.next()\` continues to the route handler. \`request.headers.get('authorization')\` reads auth headers. You can \`redirect\` to a login page if unauthenticated. **\`NextResponse.json({ error: 'Unauthorized' }, { status: 401 })\` returns an error response. **Middleware is the right place for auth checks** - it runs before the route handler and can short-circuit unauthorized requests. **Route Handlers are colocated with your app code** - you can import the same database client and utilities used by your server components. For simple CRUD, Route Handlers work great. For complex APIs with many endpoints, consider a dedicated backend service.**`
  },
  'nextjs-middleware-auth': {
    explanation: `**Next.js Middleware** allows you to run code before a request completes. It's defined in \`middleware.ts\` at the project root and runs for every matching route. Middleware is ideal for authentication checks, redirects, URL rewrites, bot detection, A/B testing, and adding security headers.

**How middleware works:** The \`middleware.ts\` file exports a \`middleware\` function that receives \`NextRequest\` and returns \`NextResponse\`. It runs on the Edge Runtime (fast, globally distributed). You can use \`config.matcher\` to specify which paths middleware runs on. **Common auth patterns:** JWT verification in middleware, redirecting unauthenticated users to login, checking role-based access, refreshing expired tokens, setting session cookies. **Auth libraries:** NextAuth.js (Auth.js) - the most popular authentication library for Next.js. Provides built-in providers (Google, GitHub, email), database adapters, and middleware integration. **Clerk:** a full-featured auth solution with pre-built components. **Route protection:** \`if (!token) return NextResponse.redirect(new URL('/login', request.url))\`. **Role-based access:** check user role in middleware and redirect if insufficient permissions. **Session management:** validate JWT tokens, set cookies, handle token refresh. **Performance:** middleware runs on every matched request - keep it lightweight. Heavy operations should be in API routes or server components. **Best practice:** use middleware for fast check-only operations (token validation, redirects). Don't make database calls in middleware (too slow for edge). Use the \`matcher\` config to limit middleware to specific paths. Use NextAuth.js or Clerk for production authentication (they handle security edge cases). Always validate sessions in both middleware (for redirects) and server components/API routes (for actual protection). Configure CORS headers in middleware for API routes.`,
    codeExplanation: `This middleware implements **auth protection**. \`export function middleware(request: NextRequest)\` is the main function. It reads the token from cookies (\`request.cookies.get('token')?.value\`). The \`isAuthenticated\` flag checks if the token exists. \`const isAuthPage = request.nextUrl.pathname.startsWith('/login')\` identifies auth pages. \`const isApiRoute = request.nextUrl.pathname.startsWith('/api')\` identifies API routes. **Redirect unauthenticated users:** if not authenticated and not on an auth page or API route, redirect to /login. **Redirect authenticated users:** if already authenticated and trying to access login page, redirect to dashboard. **API route protection:** if not authenticated and accessing an API route, return 401 JSON. \`config.matcher\` specifies which paths the middleware runs on - \`/((?!_next/static|favicon.ico).*)\` excludes static assets. **NextAuth.js setup:** \`[...nextauth]/route.ts\` handles OAuth callbacks. \`authOptions\` configures providers and callbacks. \`getServerSession(authOptions)\` in server components gets the current session. The middleware (\`withAuth\`) redirects unauthenticated users. **Always validate on the server** - middleware auth is convenience for redirects, but actual protection must be in server components/API routes. \`getServerSession\` should be used in page components and API routes to verify the user's identity, not just rely on middleware checks.**`
  },
  'nextjs-performance': {
    explanation: `**Next.js performance** optimization leverages the framework's built-in features along with web best practices. Next.js provides several performance optimizations automatically, but understanding them helps you make the right choices.

**Automatic optimizations:** **Code splitting** - Next.js automatically splits your code by route (only load JS for the current page). **Image optimization** - \`next/image\` automatically serves WebP/AVIF, resizes images, implements lazy loading, and sets proper dimensions to prevent layout shifts. **Font optimization** - \`next/font\` self-hosts fonts (no external requests) and eliminates layout shifts from font loading. **Script optimization** - \`next/script\` with \`strategy='afterInteractive'\` loads scripts without blocking. **Static Generation** - pre-render pages at build time for instant loading. **ISR** - update static content without rebuilding. **Streaming** - server components can stream content as it's ready. **Manual optimizations:** **React.lazy** for component-level code splitting within a page. **Dynamic imports** (\`next/dynamic\`) for loading heavy components only when needed. **Bundle analyzer** (\`@next/bundle-analyzer\`) to find large dependencies. **Proper caching headers** for static assets. **CDN** for static content. **Database query optimization** - use indexes, select only needed fields, paginate results. **Client-side caching** with React Query for API data. **Preconnect and prefetch** critical resources. **Core Web Vitals:** LCP (Largest Contentful Paint - loading), FID (First Input Delay - interactivity), CLS (Cumulative Layout Shift - visual stability). Next.js helps optimize all three. **Best practice:** use the built-in optimizations before adding custom ones. Measure performance (Lighthouse, Web Vitals) and fix the biggest issues first. Optimize images (serve proper sizes, lazy load below-fold images). Use ISR for content pages. Minimize client-side JavaScript. Use React.memo and useMemo for expensive renders (measured). Optimize fonts. Use bundle analyzer to identify large dependencies. Implement proper caching.`,
    codeExplanation: `This code shows **Next.js performance patterns**. \`export const revalidate = 3600\` enables ISR - the page is re-generated at most once per hour, combining static speed with fresh content. \`next/image\` optimizes images automatically: \`width\` and \`height\` prevent layout shifts, \`priority\` loads above-fold images immediately (no lazy loading), \`sizes="(max-width: 768px) 100vw, 50vw"\` tells the browser which image size to download at different viewports. \`next/font\` with \`Inter\` self-hosts the font - no Google Fonts request, no layout shift from font loading. \`next/dynamic\` with \`ssr: false\` dynamically imports the heavy chart component - it only loads when needed and isn't server-rendered (because it needs browser APIs). \`DynamicPosts\` uses \`next/link\` with \`prefetch={true}\` (default) - Next.js prefetches linked pages in the background for instant navigation. **Streaming with Suspense:** the page immediately shows a loading skeleton (\`<PostSkeleton />\`) while the post content streams in. This improves perceived performance - users see content sooner. **Key performance metrics:** The ISR page (/) loads instantly (static). The dynamic import prevents the chart library from blocking the initial page load. Images are optimized and sized properly to prevent layout shifts. Fonts are self-hosted for zero external requests. Prefetching makes navigation feel instant. **Always measure before optimizing** - use Lighthouse, Web Vitals report, and the browser DevTools Performance tab.**`
  },
  'deploying-nextjs': {
    explanation: `**Deploying Next.js** applications involves building the application and hosting it on a server. Vercel (by the creators of Next.js) is the recommended platform with the best integration, but Next.js can be deployed anywhere that supports Node.js.

**Vercel deployment (recommended):** Connect your Git repository, Vercel automatically detects Next.js, builds, and deploys. Features: automatic preview deployments for every PR, serverless functions for API routes, ISR support, Edge Functions, analytics, and automatic HTTPS. **Self-hosted options:** Node.js server (\`next start\`), Docker container, PM2 process manager, Nginx reverse proxy. **Build process:** \`next build\` generates static files in \`.next\` and server-side bundles. \`next start\` runs the production server. **Environment variables:** \`.env.local\` for local development, \`.env.production\` for production, configured in Vercel dashboard for hosted deployments. **Static export:** \`next export\` (or \`output: 'export'\` in next.config) generates a fully static site (no server needed). Lose: API routes, ISR, middleware, server components that use server-only features. **Docker deployment:** multi-stage Dockerfile with \`node:18-alpine\` for the build stage and \`next start\` for the runtime. **CI/CD:** GitHub Actions to test, lint, build, and deploy. **Domain and SSL:** configure custom domain and automatic HTTPS. **Monitoring:** Vercel Analytics, Sentry for error tracking, custom logging. **Best practice:** deploy to Vercel for ease and performance (serverless edge, ISR, preview deployments). Use Docker for self-hosted options. Set up CI/CD early. Use preview deployments for testing. Configure proper caching headers. Set up monitoring and error tracking. Use environment variables for configuration. For static sites (blogs, docs), consider static export + Vercel/GitHub Pages/Netlify for zero-cost hosting. For e-commerce or SaaS, use Vercel or self-hosted with proper scaling strategy.`,
    codeExplanation: `This shows **Next.js deployment configurations**. **Vercel deployment** is the simplest - push to GitHub, Vercel auto-deploys. Preview deployments are created for every PR branch. Environment variables are configured in the Vercel dashboard (separate for production, preview, development). **Static export** (\`output: 'export'\`) generates a \`/out\` folder with pure HTML/CSS/JS - deploy to any static host (GitHub Pages, S3, Netlify). Limited to static features. **Docker deployment:** \`Dockerfile\` uses multi-stage build with \`node:18-alpine\`. Stage 1 installs dependencies and builds. Stage 2 copies the build output and runs \`next start\`. The \`.dockerignore\` excludes node_modules and .next from the Docker context. \`docker build -t my-next-app .\` builds the image. \`docker run -p 3000:3000 my-next-app\` runs it. **PM2 with Nginx:** PM2 runs the Next.js process (\`pm2 start npm -- start\`). Nginx reverse proxies requests to localhost:3000, serves static files directly, and handles SSL termination. **CI/CD with GitHub Actions:** \`main\` branch push triggers: checkout -> install dependencies -> lint -> test -> build -> deploy to Vercel. **Choose the right deployment:** Vercel for simplicity (discover the full power of Next.js), Docker for containerized environments, static export for simple content sites, PM2 + Nginx for traditional server setups. For most projects, Vercel provides the best developer experience and performance.**`
  },
  'nodejs-fundamentals': {
    explanation: `**Node.js** is a JavaScript runtime built on Chrome's V8 engine that allows server-side JavaScript execution. It uses an **event-driven, non-blocking I/O model** that makes it efficient for building scalable network applications. Created by Ryan Dahl in 2009.

**Key features:** **CommonJS** (\`require\`, \`module.exports\`) and **ES modules** (\`import\`, \`export\`) are both supported. **Event loop** handles concurrency on a single thread without creating a new thread per request. **Libuv** provides the event loop, thread pool for async I/O, and cross-platform async support. **Key built-in modules:** \`fs\` (file system), \`path\` (file paths), \`http\`/\`https\` (HTTP servers/clients), \`os\` (OS info), \`events\` (EventEmitter), \`stream\` (streaming data), \`child_process\` (spawn processes), \`cluster\` (multi-core scaling). **npm** is the package manager with the largest ecosystem. **package.json** manages dependencies, scripts, and metadata. **NODE_ENV** controls behavior (development vs production). **Error handling:** uncaught exceptions and unhandled Promise rejections crash the process - always handle them. **Best practice:** prefer promises/async-await over callbacks. Use \`fs/promises\` API for file operations. Set up global error handlers (\`process.on('uncaughtException')\`, \`process.on('unhandledRejection')\`). Use environment variables for configuration. Never block the event loop with synchronous CPU-heavy operations (use worker threads or child processes). Use \`--watch\` flag (Node 18+) for development auto-restart. Implement graceful shutdown for production (SIGTERM handler). Use TypeScript for better code quality. Monitor memory usage - Node.js has a default memory limit of ~1.4GB (can be increased with \`--max-old-space-size\`).`,
    codeExplanation: `This shows **Node.js fundamentals**. \`http.createServer()\` creates an HTTP server that handles requests. \`fs.promises.readFile\` reads a file asynchronously using promises. The \`EventEmitter\` pattern is core to Node.js - many built-in modules (stream, http) are EventEmitters. \`process.on('uncaughtException')\` catches unexpected errors that weren't caught by try/catch. \`process.on('unhandledRejection')\` catches Promise rejections without a .catch() handler. **Without these global handlers, the process crashes** on unhandled errors. **Graceful shutdown:** on SIGTERM (sent by process managers), stop accepting new requests, close existing connections, then exit. This prevents dropped connections during restarts. **The event loop:** Node processes one callback at a time. Expensive synchronous operations block the event loop and freeze all other operations. Offload heavy computation to \`Worker Threads\` or \`child_process.fork()\`. **For production:** use a process manager (PM2) or container orchestration (Kubernetes) to automatically restart crashed processes. Always implement health check endpoints for load balancers. Use clustering to utilize all CPU cores (\`cluster\` module or PM2 cluster mode).`
  },
  'file-system-streams': {
    explanation: `**File system and streams** in Node.js handle reading/writing files and processing data in chunks. The \`fs\` module provides both callback-based and promise-based APIs. **Streams** allow processing data piece by piece instead of loading everything into memory at once - essential for large files.

**File system:** \`fs.readFile\` / \`fs.writeFile\` (whole file, simple), \`fs.createReadStream\` / \`fs.createWriteStream\` (large files, streaming). **Path module:** \`path.join\` (cross-platform paths), \`path.resolve\` (absolute paths), \`path.basename\`, \`path.extname\`. **Directory operations:** \`fs.mkdir\`, \`fs.readdir\`, \`fs.stat\`. **File watching:** \`fs.watch\` (monitor file changes). **Stream types:** **Readable** (source - file, HTTP request), **Writable** (destination - file, HTTP response), **Transform** (modify data in transit - compression, encryption), **Duplex** (both readable and writable). **Stream events:** \`data\` (chunk arrives), \`end\` (no more data), \`error\`, \`finish\` (writing complete). **Pipe:** \`readable.pipe(writable)\` connects streams automatically - handles backpressure (pauses source when destination is slow). **Best practice:** use streams for files larger than ~100MB. Use \`pipe()\` instead of manual event handling. Handle stream errors (unhandled stream errors crash the process). Use \`pipeline()\` from \`stream/promises\` (Node 15+) - it automatically cleans up and handles errors properly. For configuration files and small data, use \`fs.readFile\` (simpler). Use \`fs/promises\` API (promises version) instead of callbacks. Use \`path.join\` for cross-platform paths (Windows uses \\\\, POSIX uses /). Use \`path.resolve\` to convert relative paths to absolute.`,
    codeExplanation: `This code shows **file system and stream operations**. \`fs.promises.readFile\` reads a small JSON file entirely into memory (fine for config files). \`fs.createReadStream\` creates a readable stream for a large file - it emits \`data\` events with chunks. \`fs.createWriteStream\` creates a writable stream. \`readStream.pipe(writeStream)\` connects them: data flows from the read stream directly to the write stream, with automatic backpressure handling (if the write stream is slow, the read stream pauses). The \`pipeline()\` function (from \`stream/promises\`) is the recommended way - it handles errors, cleanup, and backpressure automatically. \`through2\` (or \`Transform\` stream) modifies data in transit - the \`transform\` function receives each chunk, processes it, and pushes the result. \`path.join(__dirname, 'data', 'file.txt')\` creates cross-platform paths. \`path.basename\` extracts the filename, \`path.extname\` gets the extension. **Streams are memory-efficient** - instead of loading a 1GB file into memory, streams process it in small chunks (default 64KB). This allows handling files larger than available RAM. **Always handle stream errors** - an unhandled \`error\` event on a stream crashes the process. \`pipeline()\` handles this automatically. Use Readable.from() to create streams from arrays/iterables. Use \`fs/promises\` for simple async file operations.**`
  },
  'nodejs-express': {
    explanation: `**Express.js with Node.js** is the standard combination for building web APIs. Express is a minimal, unopinionated web framework that provides routing, middleware, and request handling. While raw Node.js \`http\` module can build servers, Express dramatically reduces boilerplate.

**Setting up:** \`const app = express()\` creates the application. \`app.use(express.json())\` adds JSON body parsing middleware. **Routing:** \`app.get('/api/users', handler)\`, \`app.post('/api/users', handler)\`. Route parameters: \`app.get('/api/users/:id', (req, res) => { req.params.id })\`. **Middleware:** functions with \`(req, res, next)\` signature. Execute in order. Can modify req/res, end requests, or call next(). **Error handling:** special middleware with 4 params \`(err, req, res, next)\` catches errors. **Common middleware:** \`cors()\`, \`helmet()\` (security headers), \`morgan\` (logging), \`compression\` (gzip), \`express-rate-limit\`. **Project structure:** \`/routes\` (route definitions), \`/controllers\` (request handling logic), \`/middleware\` (custom middleware), \`/services\` (business logic), \`/models\` (database models). **Error handling pattern:** controllers wrap async handlers with try/catch, pass errors to \`next(error)\`, error handler middleware formats the response. **Best practice:** use \`express.Router()\` to modularize routes. Use catch-all error handler. Validate request bodies with Zod/Joi. Use environment variables for configuration. Implement rate limiting, CORS, and security headers. Use TypeScript. Keep controllers thin - business logic goes in services. Use HTTP status codes consistently. Version your API. Use \`helmet\` for security headers. Use \`compression\` for gzip. Structure the app for testability - dependency injection for services.`,
    codeExplanation: `This code shows **Express.js with async error handling**. \`express()\` creates the app. \`app.use(express.json())\` parses JSON bodies. \`app.use(cors())\` enables CORS. The \`errorHandler\` has 4 parameters - Express recognizes it as error-handling middleware. The \`catchAsync\` wrapper function wraps async route handlers - it catches Promise rejections and passes them to \`next(error)\`. Without this, Express doesn't catch async errors (they result in unhandled Promise rejections). The user routes are modular with \`express.Router()\`. \`router.get('/', getAllUsers)\` handles GET /api/users. The controller (\`getAllUsers\`) uses async/await with try/catch - catches specific errors (like \`Prisma.NotFoundError\`) and returns appropriate status codes. The error handler returns consistent JSON: \`{ error: { message, status, ...details } }\`. In development, include the stack trace; in production, omit it. **The \`catchAsync\` pattern is essential** - Express 4 doesn't catch async errors automatically. Express 5 (experimental) does. For now, wrap all async route handlers. **Project organization:** separate route definitions, controllers, services, and middleware. Keep controllers thin (just request/response handling). Business logic goes in services. Database access goes in models/repositories. This separation makes testing easier and keeps each file focused on one responsibility.**`
  },
  'nodejs-error-handling': {
    explanation: `**Error handling in Node.js/Express** is critical for building reliable applications. Unhandled errors crash the process and cause downtime. A comprehensive error handling strategy covers synchronous errors, async errors, uncaught exceptions, unhandled Promise rejections, and operational errors (expected, like validation) vs programmer errors (bugs).

**Synchronous errors:** try/catch catches them. **Async errors in Express:** Must be caught and passed to \`next(error)\`. Express 4 doesn't catch Promise rejections automatically - use a wrapper like \`catchAsync\` or Express 5 (which does). **Custom error classes:** Extend Error with status code, error code, and details. \`class AppError extends Error { constructor(message, statusCode) { super(message); this.statusCode = statusCode } }\`. **Operational errors:** predictable errors (invalid input, not found, rate limit exceeded). Handle gracefully by returning appropriate error responses. **Programmer errors:** bugs in code (ReferenceError, TypeError). These should crash the process (or at least log prominently) - they indicate bugs that need fixing. **Global handlers:** \`process.on('uncaughtException')\` - last resort for unexpected sync errors. \`process.on('unhandledRejection')\` - last resort for unhandled Promise rejections. Log the error, then exit (process may be in an inconsistent state). Use a process manager (PM2) to restart. **Error response format:** consistent JSON structure: \`{ success: false, error: { message, code, details } }\`. In development include stack trace; in production omit it. **Logging:** use a structured logger (pino, winston) instead of console.log. Log enough context (request ID, user ID, error stack). **Best practice:** define custom error classes for different error types. Use a centralized error handler middleware. Log all errors. Return appropriate HTTP status codes. Never expose stack traces in production. Use tools like Sentry for error monitoring. Implement health check endpoints. Always handle errors at the appropriate level - don't catch every error in every function; let them propagate to the error handler. Use try/catch in controllers, not in every service function.`,
    codeExplanation: `This code shows **comprehensive error handling**. \`AppError\` is a custom error class with \`statusCode\`, \`code\`, and \`isOperational\` properties. \`NotFoundError\`, \`ValidationError\`, \`UnauthorizedError\` extend AppError with specific defaults. The \`errorHandler\` middleware checks if the error is operational (expected) or programmer error. For operational errors, it returns the appropriate status code and message. For programmer errors, it logs and returns 500 Internal Server Error. In development, include the stack; in production, omit it. The \`catchAsync\` wrapper catches async errors. The controller uses \`catchAsync\`: if user is not found, \`throw new NotFoundError('User not found')\`. The error handler catches it and returns 404. **Global handlers:** \`process.on('unhandledRejection')\` and \`process.on('uncaughtException')\` log the error, then \`process.exit(1)\` - the process manager (PM2, Docker) restarts the process. **This pattern gives you clean, consistent error responses** while ensuring programmer errors don't go unnoticed. **Operational vs Programmer errors:** operational errors are expected (validation, not found, auth) - handle them gracefully. Programmer errors are bugs (typos, undefined variables) - log them prominently and fix them. The isOperational flag helps distinguish between them. **Use a logger like pino or winston** instead of console.error - log to files or external services for production debugging.**`
  },
  'nodejs-performance': {
    explanation: `**Node.js performance optimization** focuses on keeping the event loop responsive, using asynchronous I/O, and leveraging multiple CPU cores. Node.js is single-threaded for JavaScript execution, but its asynchronous nature makes it highly efficient for I/O-bound applications.

**Key techniques:** **Clustering** - use the \`cluster\` module to spawn worker processes on each CPU core. Each worker handles requests independently. PM2's cluster mode does this automatically. **Worker threads** - for CPU-intensive operations (image processing, data transformation, complex calculations) that would block the event loop. Use \`worker_threads\` module. **Avoid blocking the event loop:** don't use synchronous versions of fs methods (\`fs.readFileSync\`), avoid heavy synchronous computations, break up large loops with \`setImmediate()\` or \`queueMicrotask()\`. **Database optimization:** use connection pooling, add indexes, limit returned fields, paginate results, use Redis cache for hot data. **Caching:** Redis or in-memory cache for frequently accessed data. Use \`node-cache\` or Redis. **Compression:** use \`compression\` middleware (gzip/brotli). **HTTP/2:** faster than HTTP/1.1 with multiplexing. **Load testing:** use autocannon or wrk to measure performance. **Memory management:** monitor memory usage, avoid memory leaks (common causes: event listeners not removed, closures holding references, large caches without TTL). Use \`--inspect\` flag and Chrome DevTools for profiling. **Best practice:** always use asynchronous APIs. Cluster in production (one process per CPU core). Use connection pooling for databases. Implement caching at every layer. Use CDN for static assets. Enable gzip compression. Monitor with APM tools (New Relic, Datadog). Profile before optimizing - measure, identify bottlenecks, then fix. An optimized but hard-to-read codebase is never worth it. The biggest gains come from architectural changes (caching, better algorithms, async I/O), not micro-optimizations.`,
    codeExplanation: `This code shows **Node.js performance patterns**. **Clustering** with the \`cluster\` module: the primary process forks workers (one per CPU core). Workers share port 3000. If a worker crashes, the primary forks a new one. PM2's cluster mode (\`pm2 start app.js -i max\`) does this automatically. **Worker threads** for CPU-intensive tasks: the main thread sends a task (\`worker.postMessage(data)\`), the worker thread processes it without blocking the event loop, and sends the result back (\`parentPort.postMessage(result)\`). **Memory leak prevention:** \`heapdump\` captures heap snapshots for analysis. Compare snapshots to find growing objects. **Common memory leak causes:** global variables, event listeners not removed (\`emitter.removeListener()\`), closures holding large objects, setInterval without clearInterval, large caches without size limits. The \`performance.now()\` API measures execution time. **\`--inspect\` flag** enables Chrome DevTools debugging - go to \`chrome://inspect\` to connect. The **Performance** tab in DevTools shows the flame graph - identify long-running functions. **Memory** tab shows heap usage over time - look for patterns where GC doesn't free memory. **Always monitor in production** - use \`process.memoryUsage()\` for basic monitoring, APM tools for detailed analysis. Set up alerts for high memory usage. Use \`process.on('warning')\` to log deprecation and memory warnings.**`
  },
  'nodejs-security': {
    explanation: `**Node.js security** involves protecting your application from common vulnerabilities. Node.js applications face the same web security threats as any backend, plus some Node-specific concerns. A defense-in-depth approach with multiple security layers is essential.

**Key threats:** **Injection attacks** (SQL injection, NoSQL injection, command injection) - always validate and sanitize user input, use parameterized queries, never concatenate user input into commands. **Cross-Site Scripting (XSS)** - escape user input in HTML responses, set proper Content-Type headers. **CSRF** - use anti-CSRF tokens for state-changing requests (Express.js has \`csurf\` middleware). **Authentication vulnerabilities** - weak password policies, insecure session management, JWT secrets exposed. **Sensitive data exposure** - never log passwords or tokens, use HTTPS, encrypt sensitive data at rest. **Security misconfiguration** - default credentials, unnecessary features enabled, verbose error messages exposing internals. **Dependency vulnerabilities** - use \`npm audit\`, keep dependencies updated, use Snyk or Dependabot. **Denial of Service (DoS)** - rate limiting, request size limits, timeouts. **Node-specific:** prototype pollution, path traversal, unsafe use of \`eval()\` or \`new Function()\`, command injection via \`child_process.exec\`, unsafe deserialization. **Best practice:** use Helmet.js for security headers. Use \`express-rate-limit\` for rate limiting. Use \`express.json({ limit: '10kb' })\` to limit request body size. Validate all input with Zod/Joi. Use parameterized queries (Prisma, Knex) - never concatenate SQL. Implement proper authentication (bcrypt for passwords, JWT with short expiry, refresh tokens). Use HTTPS exclusively. Set secure, httpOnly, sameSite cookies. Implement CORS properly. Sanitize file uploads. Use \`npm audit\` regularly. Add a security.txt file. Keep dependencies updated. Use environment variables for secrets. Implement proper logging and monitoring.`,
    codeExplanation: `This code shows **Node.js security best practices**. \`helmet()\` sets security headers (X-Content-Type-Options, X-Frame-Options, CSP, etc.). \`express.json({ limit: '10kb' })\` limits request body size to prevent large payload attacks. \`express-rate-limit\` limits requests per IP - 100 requests per 15 minutes. \`cors({ origin: process.env.ALLOWED_ORIGIN })\` restricts CORS to a specific origin. **Input validation** with Zod: \`z.object({ email: z.string().email(), password: z.string().min(8) })\` validates the request body before processing. The \`sanitizeInput\` function strips HTML tags to prevent XSS. **Parameterized queries:** Prisma uses parameterized queries by default - \`prisma.user.findUnique({ where: { email } })\` is safe from SQL injection. Never use \`raw\` queries with string concatenation. **Authentication:** bcrypt hashes passwords with salt rounds, JWT is verified with \`jwt.verify()\`. Cookies have \`httpOnly: true\` (not accessible via JavaScript), \`secure: true\` (HTTPS only), \`sameSite: 'strict'\` (CSRF protection). **Dependency security:** \`npm audit\` checks for known vulnerabilities. \`snyk\` provides continuous monitoring. **The principle of least privilege applies** - only allow what's necessary. Validate everything. Never trust user input. Layers of security mean that if one defense fails, others still protect.**`
  },
  'expressjs-basics': {
    explanation: `**Express.js** is a minimal and flexible Node.js web application framework that provides a robust set of features for web and mobile applications. It's the de facto standard for building HTTP servers in Node.js, with a large ecosystem of middleware and extensions.

**Core features:** **Routing** - define endpoints with HTTP methods and URL patterns. \`app.get('/users', handler)\`, \`app.post('/users', handler)\`. **Middleware** - functions executed in order during request processing. Modify req/res, end requests, or pass to next middleware. **Request handling** - \`req.params\` (route params), \`req.query\` (query string), \`req.body\` (request body, requires \`express.json()\`), \`req.headers\`, \`req.cookies\`. **Response methods:** \`res.json()\` (JSON), \`res.send()\` (any type), \`res.status()\` (status code), \`res.redirect()\`, \`res.render()\` (templates). **Application settings:** \`app.set('trust proxy', 1)\` for reverse proxies, \`app.set('view engine', 'ejs')\` for templates. **Static files:** \`app.use(express.static('public'))\` serves files from the public directory. **Error handling:** middleware with 4 parameters catches errors. **Express Router:** modularize routes with \`express.Router()\`. **Best practice:** structure your app with separate files for routes, controllers, middleware, and models. Use environment variables for configuration. Use TypeScript. Implement proper error handling. Use \`helmet\`, \`cors\`, \`compression\`, \`morgan\` middleware. Keep route handlers thin - business logic in separate modules. Validate input with Zod/Joi. Use \`async/await\` with proper error handling. Version your API. Test your endpoints with Supertest.`,
    codeExplanation: `This code shows **Express.js fundamentals**. \`express()\` creates the application. \`app.use(express.json())\` adds JSON body parsing middleware. \`app.use(express.urlencoded({ extended: true }))\` parses form data. \`app.use(express.static('public'))\` serves static files. Route handlers: \`app.get('/api/users')\` handles GET requests, \`app.post('/api/users')\` handles POSTs. \`req.params.id\` extracts route parameters. \`req.query.page\` reads query parameters. \`res.status(201).json({ ... })\` sets the status code and returns JSON. The \`errorHandler\` middleware has 4 parameters - it catches all errors passed via \`next(err)\`. \`app.use('/api/users', userRoutes)\` mounts the router at /api/users. \`express.Router()\` creates modular route groups. \`router.route('/:id')\` chains multiple HTTP methods for the same path. **Express is unopinionated** - it doesn't enforce structure. This flexibility means you need discipline to organize your code well. **Common middleware order:** helmet -> cors -> compression -> body parsers -> logger -> static files -> routes -> error handler. Middleware runs in the order it's added. The error handler should be last so it can catch errors from all preceding middleware and routes.**`
  },
  'expressjs-middleware': {
    explanation: `**Express middleware** are functions that execute during the request-response cycle. They have access to the request object (\`req\`), response object (\`res\`), and the \`next\` function. Middleware can: execute code, modify req/res, end the request-response cycle, or call the next middleware. Middleware is Express's core design pattern - almost everything in Express is middleware.

**Types of middleware:** **Application-level:** \`app.use(middleware)\` runs for all routes. **Router-level:** \`router.use(middleware)\` runs for routes on that router. **Error-handling:** 4 parameters \`(err, req, res, next)\`. **Built-in:** \`express.json()\`, \`express.static()\`, \`express.urlencoded()\`. **Third-party:** \`cors\`, \`helmet\`, \`morgan\`, \`compression\`, \`express-rate-limit\`. **Custom middleware:** write your own. **Execution order:** middleware runs in the order it's added to the app. The \`next()\` function passes control to the next middleware. If a middleware doesn't call \`next()\`, the request hangs (unless it ends the request with \`res.send()\` etc.). **Common patterns:** authentication middleware (verify token, attach user to req), logging middleware, request validation middleware, rate limiting middleware, error handling middleware, request timing middleware. **Best practice:** keep middleware focused on one concern. Use middleware for cross-cutting concerns (auth, logging, validation). Don't put too much logic in middleware - it should be thin and composable. Use the \`next()\` pattern properly. For async middleware, catch errors and pass to \`next(err)\`. Order middleware carefully - auth middleware should come before route handlers that need authentication. Error-handling middleware should be last. Use \`app.set('trust proxy', 1)\` behind reverse proxies for correct IP detection.`,
    codeExplanation: `This code shows **Express middleware patterns**. \`requestLogger\` logs every request with method, URL, and duration. \`console.time(req.url)\` starts a timer, \`next()\` passes to the next handler, and when the response finishes (\`res.on('finish')\`), it logs the duration. \`authenticate\` middleware extracts the token from the Authorization header, verifies it with \`jwt.verify()\`, and attaches the decoded user to \`req.user\`. If the token is invalid, it calls \`next(err)\` with an error - the error handler will catch it. \`validate(schema)\` is a **middleware factory** - it returns a middleware that validates \`req.body\` against a Zod schema. If validation fails, it returns 400 with error details. \`errorHandler\` catches all errors: if the error is a Zod validation error (\`error instanceof z.ZodError\`), it returns 400 with field-level errors. Otherwise, it returns 500. \`app.use('/api', authenticate, userRoutes)\` applies authentication middleware to all user routes. **Middleware order matters:** the requestLogger runs first (logs incoming request), then the routes, then the error handler (last). **Router-level middleware** (\`router.use(authenticate)\`) applies only to routes on that specific router. **Middleware factories** (\`validate(schema)\`) enable reusable validation with different schemas for different endpoints.**`
  },
  'restful-apis-express': {
    explanation: `**Building RESTful APIs with Express** involves creating endpoints that follow REST conventions: use HTTP methods for CRUD operations, use resource-based URLs, return appropriate status codes, and maintain a consistent response structure. Express's flexibility makes it ideal for building REST APIs.

**REST conventions in Express:** \`GET /api/users\` (list), \`GET /api/users/:id\` (single), \`POST /api/users\` (create), \`PUT /api/users/:id\` (replace), \`PATCH /api/users/:id\` (partial update), \`DELETE /api/users/:id\` (delete). **Response format:** consistent JSON structure: \`{ success: true, data: ... }\` for success, \`{ success: false, error: { message, code, details } }\` for errors. **Status codes:** 200 (OK), 201 (Created), 204 (No Content), 400 (Bad Request), 401 (Unauthorized), 403 (Forbidden), 404 (Not Found), 409 (Conflict), 422 (Unprocessable), 429 (Too Many Requests), 500 (Internal Server Error). **Pagination:** \`?page=1&limit=20\`, response includes \`{ data: [...], pagination: { page, limit, total, hasMore } }\`. **Filtering:** \`?status=active&role=admin\`. **Sorting:** \`?sort=createdAt&order=desc\`. **Field selection:** \`?fields=id,name,email\`. **Best practice:** version your API (\`/api/v1/...\`). Use plural nouns for resources. Use sub-resources for relationships (\`/api/users/:id/orders\`). Use nouns, not verbs in URLs (\`/api/users\` not \`/api/getUsers\`). Use HTTP methods correctly. Return appropriate status codes. Use consistent error format. Validate input. Implement rate limiting. Document with OpenAPI/Swagger. Use HATEOAS for discoverability. Use middleware for cross-cutting concerns. Use \`express.Router()\` for modular routes. Keep controllers thin. Use service layer for business logic.`,
    codeExplanation: `This shows a **RESTful API structure with Express**. The router defines CRUD endpoints following REST conventions. \`GET /api/v1/users\` supports query parameters for pagination (\`page\`, \`limit\`), filtering (\`role\`), sorting (\`sort\`, \`order\`), and field selection (\`fields\`). The controller parses these parameters and constructs a query. The response includes \`data\` (the actual records) and \`pagination\` metadata (page, limit, total). \`POST /api/v1/users\` creates a user - validates input with Zod, passes to the service, returns 201 with the created user and a Location header. \`GET /api/v1/users/:id\` returns a single user or 404. \`PATCH /api/v1/users/:id\` partially updates (only sends changed fields). \`DELETE /api/v1/users/:id\` deletes and returns 204 No Content. **Service layer** (\`userService\`) contains business logic (checking for existing users, hashing passwords). The controller only handles request/response - it calls the service and formats the result. **This separation makes testing easier** - you can test services without HTTP, and test controllers with mocked services. **Consistent error handling:** all errors pass through \`catchAsync\` to the error handler. The error handler returns \`{ success: false, error: { message, status, ... } }\`. This consistency makes API consumption predictable for frontend developers.**`
  },
  'expressjs-error-handling': {
    explanation: `**Express error handling** is essential for building reliable APIs. Express has specific patterns for handling errors in synchronous and asynchronous code. Without proper error handling, errors cause requests to hang or crash the server.

**Synchronous errors:** Express automatically catches errors thrown in synchronous route handlers. \`app.get('/user', (req, res) => { throw new Error('Oops') })\` - Express's default error handler catches this. **Async errors:** Express 4 does NOT catch errors from async functions. You must pass them to \`next()\`: \`async (req, res, next) => { try { ... } catch (err) { next(err) } }\`. Use a wrapper like \`catchAsync\` to avoid repeating try/catch in every handler. **Custom error classes:** Create error classes with status codes and error codes. \`class AppError extends Error { constructor(message, statusCode, code) { super(message); this.statusCode = statusCode; this.code = code } }\`. **Error-handling middleware:** defined with 4 parameters: \`(err, req, res, next)\`. Express recognizes it by the number of parameters. Must be defined AFTER all routes. **Production vs Development errors:** In development, include stack traces for debugging. In production, never expose stack traces. **Common error types:** validation errors (400), authentication errors (401), authorization errors (403), not found errors (404), conflict errors (409), rate limit errors (429), internal errors (500). **Best practice:** define a custom error class hierarchy. Use \`catchAsync\` wrapper for all async route handlers. Implement a centralized error handler. Log errors with sufficient context. Return consistent error responses. Handle known error types (validation, auth, not found) with specific status codes. Use \`app.set('env')\` to determine development vs production. Don't swallow errors - if you catch an error and can't handle it, pass it to \`next(err)\`. Never expose internal error details to clients. Use a monitoring service (Sentry) for production error tracking.`,
    codeExplanation: `This shows **comprehensive Express error handling**. \`AppError\` is a custom base error with \`statusCode\`, \`code\`, and \`isOperational\` flag. Error subclasses (\`NotFoundError\`, \`ValidationError\`, \`AuthError\`) extend it with default values. \`catchAsync\` wraps async route handlers - catches any rejected promise and passes it to \`next()\`. Without this, async errors in Express 4 result in unhandled promise rejections. The \`errorHandler\` middleware: for operational errors (expected), returns the appropriate status code and message. For programmer errors (bugs), logs the error and returns 500. In development, includes the stack trace; in production, omits it. The controller throws \`NotFoundError\` when a user isn't found - the error handler catches it and returns 404. **Error types matter:** \`error.name === 'ZodError'\` handles validation errors with field-level details. \`error.code === 'P2025'\` handles Prisma's "record not found" error. \`error.statusCode || 500\` - if the error has a statusCode (custom errors), use it; otherwise, default to 500. **The 4-parameter signature is how Express identifies error-handling middleware** - it must have exactly 4 parameters. Place it after all route definitions and other middleware. The order matters: routes come before the error handler. If the error handler is before routes, it won't catch route errors.**`
  },
  'expressjs-security': {
    explanation: `**Express security** involves protecting your application against common web vulnerabilities. Express is a flexible framework, so security relies on proper configuration and middleware. A defense-in-depth approach is essential.

**Key security measures:** **Helmet.js** - sets security headers (X-Content-Type-Options, X-Frame-Options, Content-Security-Policy, etc.). 14 middleware functions in one. **CORS** - configure properly (\`cors({ origin: 'https://yourfrontend.com' })\`). Never use \`cors({ origin: '*' })\` in production. **Rate limiting** - \`express-rate-limit\` prevents brute force and DoS attacks. **Input validation** - validate ALL user input with Zod/Joi. Never trust req.body, req.query, or req.params. **SQL/NoSQL injection prevention** - use parameterized queries (Prisma, Sequelize). Never concatenate user input into queries. **XSS prevention** - never render unsanitized user input as HTML. Use \`helmet.contentSecurityPolicy()\` to restrict script sources. **CSRF protection** - use \`csurf\` middleware or \`sameSite: 'strict'\` cookies. **Secure headers** - use \`helmet()\` which sets X-Frame-Options (clickjacking protection), X-Content-Type-Options (MIME sniffing), Strict-Transport-Security (HSTS), and more. **Request size limiting** - \`express.json({ limit: '10kb' })\` prevents large payload attacks. **HTTPS** - always use HTTPS in production (terminate at reverse proxy or use \`https\` module). **Dependencies** - \`npm audit\`, keep deps updated, use Snyk/Dependabot. **Secrets management** - use environment variables, never hardcode secrets. Use a secrets manager (Vault, AWS Secrets Manager) for production. **Logging** - sanitize logs (never log passwords or tokens). **Best practice:** apply security middleware in the correct order (helmet first). Validate everything. Use parameterized queries. Implement proper authentication (bcrypt, JWT). Set secure cookie flags. Limit request rate and size. Keep dependencies updated. Use HTTPS. Don't expose stack traces in production. Use a web application firewall (WAF) for additional protection. Regularly audit security with tools (OWASP ZAP, Snyk).`,
    codeExplanation: `This code shows **Express security configuration**. \`helmet()\` applies security headers. \`helmet.contentSecurityPolicy({ directives: { ... } })\` restricts which scripts can run (prevents XSS even if an attacker injects a script tag). \`cors({ origin: 'https://example.com', credentials: true })\` restricts CORS to a specific origin with credentials. \`express-rate-limit({ windowMs: 15 * 60 * 1000, max: 100 })\` allows 100 requests per 15 minutes per IP. \`express.json({ limit: '10kb' })\` rejects request bodies larger than 10KB. **Cookie security:** \`httpOnly: true\` prevents XSS from reading cookies, \`secure: true\` sends cookies only over HTTPS, \`sameSite: 'strict'\` prevents CSRF, \`signed: true\` prevents tampering. **Input validation:** \`z.object({ name: z.string().min(1).max(100) })\` validates the request body. **Parameterized queries with Prisma** prevent SQL injection. **CSRF protection:** \`doubleCsrf({ getSecret: ... })\` generates and validates CSRF tokens. The frontend sends the token in a header, and the server validates it. **The order of middleware matters:** apply security middleware before routes - helmet first, then CORS, rate limiting, body parsers, CSRF protection, routes, error handler. **Security is layered** - headers, CORS, rate limiting, validation, parameterized queries, CSRF, and HTTPS work together. If one layer has a vulnerability, others still protect. Never rely on a single security measure.**`
  },
  'testing-express': {
    explanation: `**Testing Express applications** ensures your API endpoints work correctly and prevents regressions. A comprehensive testing strategy includes unit tests (individual functions), integration tests (API endpoints with database), and sometimes E2E tests (full system). Supertest is the standard library for HTTP testing in Express.

**Unit tests:** Test services, utilities, and middleware in isolation. Mock database calls. Fast and reliable. **Integration tests:** Test API endpoints end-to-end with a test database. Setup/teardown database before each test. Verify HTTP status codes, response bodies, and database state. **Supertest:** \`const response = await request(app).get('/api/users').set('Authorization', token).expect(200)\`. It starts the Express app internally and makes HTTP requests. **Test database:** use a separate test database or in-memory SQLite. Migrate before tests, clean up after. **Mocking:** mock external services (payment gateways, email services). Mock authentication middleware to simulate logged-in users. **Test structure (AAA):** Arrange (set up data), Act (make the request), Assert (verify response). **Coverage areas:** successful requests, validation errors, auth errors, not found errors, edge cases (empty list, large payloads, special characters). **Best practice:** use \`beforeAll\`/\`beforeEach\` for setup, \`afterAll\`/\`afterEach\` for cleanup. Use factories or fixtures for test data. Test one behavior per test case. Use descriptive test names. Test error cases as thoroughly as success cases. Run tests with \`--detectOpenHandles\` to find unclosed connections. Use \`jest.setTimeout\` for operations that take longer. Mock external services to avoid flaky tests. Keep tests isolated (don't share mutable state between tests). Use \`nock\` or \`msw\` for HTTP mocking. Use \`mongodb-memory-server\` (MongoDB) or \`testcontainers\` (PostgreSQL) for database testing.`,
    codeExplanation: `This code shows **Express API testing with Jest and Supertest**. \`beforeAll\` creates the test database and seeds data. \`beforeEach\` resets the state. \`afterAll\` disconnects from the test database. **Supertest** syntax: \`request(app).get('/api/v1/users').expect(200)\` sends a GET request and expects status 200. \`const response = await ...\` gets the full response object - \`response.body.data\` checks the response body. **Auth token:** \`request(app).post('/api/v1/auth/login').send({ email, password })\` logs in and gets the token, then sets it as an Authorization header for subsequent requests. **Testing CRUD:** \`POST\` create -> check 201 and response body. \`GET /:id\` read -> check 200. \`PATCH\` update -> check 200 and changed data. \`DELETE\` -> check 204. **Testing errors:** send invalid data -> expect 400. access without token -> expect 401. access without permission -> expect 403. request non-existent resource -> expect 404. The \`toMatchObject\` assertion checks that the response contains certain fields without requiring exact match. **Database cleanup:** delete test data after each test (\`afterEach\`) to ensure test isolation. **Always test both success and error scenarios** - most bugs are in error handling paths. Test edge cases: empty arrays, missing fields, very long strings, special characters, concurrent requests. Use \`.timeout(10000)\` for tests that involve database operations or external calls.**`
  },
  'rest-api-design': {
    explanation: `**REST API design** principles guide how to structure web APIs that are intuitive, consistent, and easy to use. A well-designed REST API uses HTTP methods correctly, uses resource-based URLs, returns appropriate status codes, and maintains consistent conventions. Good API design makes the API easy to learn and consume.

**URL conventions:** Use plural nouns for resources (\`/api/users\`). Use nouns, not verbs (\`/users\` not \`/getUsers\`). Use sub-resources for relationships (\`/users/:id/orders\`). Use lowercase and hyphens (\`/order-items\`). Version your API (\`/api/v1/\`). **HTTP methods:** \`GET\` (read), \`POST\` (create), \`PUT\` (full replace), \`PATCH\` (partial update), \`DELETE\` (delete). \`GET\` and \`DELETE\` should be idempotent (same result regardless of how many times called). \`POST\` creates new resources (not idempotent). \`PUT\` replaces (idempotent). \`PATCH\` partially updates. **Status codes:** 200 OK, 201 Created, 204 No Content, 301 Moved Permanently, 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 409 Conflict, 422 Unprocessable Entity, 429 Too Many Requests, 500 Internal Server Error. **Consistent response format:** \`{ success: true, data: ..., pagination: {...} }\` for success. \`{ success: false, error: { message, code, details } }\` for errors. **Filtering, sorting, pagination:** \`?status=active&sort=-createdAt&page=1&limit=20\`. **HATEOAS:** include links to related resources in responses. **Best practice:** design for the consumer. Be consistent (naming, error format, pagination). Use proper HTTP methods and status codes. Version from day one. Document with OpenAPI. Use rate limiting. Implement proper authentication. Keep responses minimal (don't return unnecessary data). Use sparse fieldsets (\`?fields=id,name\`) for large resources. Support ETag for caching. Use Content-Type negotiation. Handle errors gracefully with descriptive messages. Avoid breaking changes - add new fields without removing old ones. Use deprecation headers for outdated endpoints.`,
    codeExplanation: `This code shows **REST API design patterns**. Consistent response format: \`ApiResponse<T>\` type wraps all responses with \`success\`, \`data\`, \`pagination\`, and \`links\` (HATEOAS). The \`formatResponse\` helper creates this structure. **Pagination:** Query uses \`skip\` and \`take\` (Prisma). Response includes \`page\`, \`limit\`, \`total\`, and \`hasMore\`. **Filtering:** Query parses URL query parameters and builds a \`where\` clause. \`sort\` with \`-\` prefix indicates descending order. **HATEOAS:** The \`links\` object includes \`self\`, \`next\`, \`prev\`, and \`first\` page URLs. Clients can navigate the API by following these links instead of constructing URLs themselves. **Error responses:** consistent \`{ success: false, error: { message, code, details } }\`. Different error types have different codes and details (field-level validation errors). **Status codes:** 201 for creation (with Location header), 204 for deletion, 404 for not found, 409 for conflicts (duplicate email). **API design rules to follow:** use plurals (\`/api/v1/users\` not \`/api/v1/user\`). Nest resources for relationships (\`/users/:id/orders\`). Use query parameters for filtering/sorting/pagination. Return appropriate status codes. Version from the start. Documentation is essential - use Swagger/OpenAPI to generate interactive API docs.**`
  },
  'api-versioning': {
    explanation: `**API versioning** allows you to evolve your API without breaking existing clients. When you need to change response format, add new parameters, or modify behavior, versioning lets old clients continue working while new clients use the updated version. There are several approaches to API versioning.

**URL versioning (most common):** \`/api/v1/users\`, \`/api/v2/users\`. Simple, explicit, easy to implement. Each version can have different code. **Header versioning:** \`Accept: application/vnd.myapi.v1+json\`. Cleaner URLs but harder to test and discover. **Query parameter versioning:** \`/api/users?version=1\`. Simple but clutters query string. **Best practice:** URL versioning is recommended for most APIs - it's the most visible and easiest to route. Version the entire API, not individual endpoints. **Versioning strategy:** maintain old versions for a reasonable time (6 months to 2 years). Communicate deprecation clearly (Deprecation header, Sunset header). Provide migration guides. **Implementation:** in Express, use a separate router for each version. \`app.use('/api/v1', v1Router)\`, \`app.use('/api/v2', v2Router)\`. Share common code between versions. Use adapters or transformers to convert between versions. **When to version:** changing response structure, removing fields, changing behavior, changing validation rules. **When NOT to version:** adding new fields (don't break clients - just add), adding new endpoints (existing clients don't use them), fixing bugs. **Best practice:** avoid versioning if possible by being backward compatible. Add new fields to responses without removing old ones. Make breaking changes only when necessary. Use feature flags for gradual rollouts. Use a robust deprecation policy. Test all active versions. Consider GraphQL as an alternative - clients request exactly what they need, so additions don't break existing clients.`,
    codeExplanation: `This code shows **URL-based API versioning** in Express. \`v1Router\` and \`v2Router\` are separate routers mounted at \`/api/v1\` and \`/api/v2\`. Each can have completely different implementations. V2 changes the response format from \`{ id, name }\` to \`{ id, fullName }\` (demonstrating a breaking change). **Header-based versioning:** a custom header \`Accept-Version\` determines which version to use. The \`versionMiddleware\` reads the header and sets \`req.apiVersion\`. Route handlers then check \`req.apiVersion\` to return different responses. **Compatibility approach:** add fields rather than changing them. In the example, V1 returns \`{ name, email }\`. V2 keeps those fields and adds \`{ fullName: name, displayEmail: email }\` (new field names). Old clients still work because the old fields are still present. **Deprecation:** use the \`Deprecation: true\` header and \`Sunset: Sat, 01 Nov 2025 23:59:59 GMT\` header to tell clients when an API version will be removed. **Avoid versioning when possible** - prefer additive changes. Rename fields by adding the new name alongside the old one, then remove the old one after a transition period. The OpenAPI specification can document multiple versions. Each version gets its own API documentation URL. Test all active versions continuously. Monitor version usage to know when to retire old versions.**`
  },
  'pagination-filtering': {
    explanation: `**Pagination and filtering** are essential for API endpoints that return lists of resources. Without pagination, a single request could return thousands of records, overwhelming the server, the network, and the client. Pagination limits the number of results per response; filtering narrows down which results are returned.

**Pagination approaches:** **Offset-based** (\`?page=2&limit=20\`): simple, uses \`OFFSET\` and \`LIMIT\` in SQL. Problems: inconsistent when data changes between page requests (item may appear on multiple pages), inefficient for large offsets (database still scans all skipped rows). **Cursor-based** (\`?cursor=abc123&limit=20\`): uses a unique, sequential field (usually \`id\` or \`createdAt\`) as a pointer. Returns results after the cursor. Consistent even if data changes. More efficient for large datasets. Better for real-time data (feeds, messages). **Keyset pagination** (\`?after=2024-01-01T00:00:00Z&limit=20\`): uses a timestamp or other key. Similar to cursor-based. **Page-based** (\`?page=2&per_page=20\`): the simplest, most common. Include \`page\`, \`limit\`, \`total\`, \`hasMore\` in the response. **Filtering:** \`?status=active&role=admin\` (exact match), \`?search=john\` (text search), \`?createdAfter=2024-01-01\` (date range). Use consistent query parameter names. Support multiple values with comma: \`?status=active,pending\`. **Sorting:** \`?sort=name,-createdAt\` (\`-\` prefix = descending). **Best practice:** use cursor-based pagination for large, real-time datasets. Use offset-based pagination for simple admin interfaces. Always include pagination metadata in the response. Set reasonable default limits (20-50). Enforce maximum limits (100-1000). Document pagination parameters. Support filtering on indexed columns for performance. Use compound indexes for common filter combinations. Validate pagination parameters. Return consistent error for invalid parameters. Include \`hasMore\` boolean so clients know when to stop paginating. Return total count only when necessary (it can be expensive for large tables).`,
    codeExplanation: `This code shows **offset-based pagination with filtering**. The endpoint accepts \`page\`, \`limit\`, \`status\`, \`search\`, \`sortBy\`, and \`sortOrder\` query parameters. \`page\` defaults to 1, \`limit\` defaults to 20 (max 100). The \`where\` clause is built dynamically: \`status\` filter (exact match), \`search\` filter (case-insensitive contains on name OR email). The \`orderBy\` is built from \`sortBy\` and \`sortOrder\` parameters, with a whitelist to prevent injection (\`allowedSortFields\`). \`skip\` calculates the offset: \`(page - 1) * limit\`. The response includes the data array and pagination metadata. **Cursor-based pagination:** uses the \`cursor\` parameter to fetch the next page. \`cursor\` is the \`id\` of the last item from the previous page. \`take: limit + 1\` fetches one extra to determine if there's a next page (\`hasMore: results.length > limit\`). The \`nextCursor\` is the \`id\` of the last item (or the 2nd-to-last if we fetched the extra). **Cursor-based is more consistent** - new items inserted before the current position don't shift the page boundaries. It's also faster for large offsets because the database uses the index to find the cursor position instead of scanning skipped rows. **Security:** validate pagination params, don't allow arbitrary sort fields (SQL injection risk with raw queries). Use Prisma's built-in pagination for SQL injection protection.**`
  },
  'rate-limiting': {
    explanation: `**Rate limiting** controls how many requests a client can make to your API within a specific time window. It's essential for preventing abuse, protecting against DoS attacks, ensuring fair usage, and maintaining API stability. Rate limiting is typically applied per IP address, per user, or per API key.

**Types of rate limiting:** **Global** (all requests across all routes) - basic protection. **Per-endpoint** (specific limits on expensive routes like search or export). **Per-user** (based on authentication). **Per-IP** (for unauthenticated requests). **Concurrent request limiting** (limit simultaneous connections). **Algorithms:** **Fixed window** (X requests per Y minutes, resets at window boundary) - simple but can burst at boundary. **Sliding window** (X requests in the last Y minutes) - more accurate, uses rolling time window. **Token bucket** (tokens added at a rate, each request consumes a token) - smooth, allows bursts. **Leaky bucket** (requests processed at a constant rate) - smooth, no bursting. **Implementation:** In-memory for single-process apps, Redis for distributed apps. \`express-rate-limit\` (in-memory), \`rate-limit-redis\` (Redis-backed). **Response headers:** \`X-RateLimit-Limit\` (max requests), \`X-RateLimit-Remaining\` (remaining in window), \`X-RateLimit-Reset\` (window reset time). **When limit exceeded:** return 429 Too Many Requests with \`Retry-After\` header. **Best practice:** apply rate limiting to all routes, with stricter limits on auth endpoints (login, register - prevent brute force). Use Redis for distributed rate limiting across multiple servers. Return clear error messages. Set limits based on normal usage patterns (100 req/min for general APIs, 5 req/min for login). Use different limits for authenticated vs unauthenticated users. Log rate limit violations for abuse detection. Implement exponential backoff for retries. Consider using API keys for tracking. Use rate limiting as part of a defense-in-depth strategy (combined with WAF, DDoS protection). Allow certain IPs/IP ranges (internal services) to bypass limits. Implement cost-based rate limiting (limit by computational cost, not just request count) for expensive operations.`,
    codeExplanation: `This code shows **rate limiting in Express**. \`generalLimiter\` applies to all routes: 100 requests per 15 minutes, returns standard headers (\`RateLimit-Limit\`, \`RateLimit-Remaining\`, \`RateLimit-Reset\`). \`authLimiter\` is stricter: 5 requests per 15 minutes on auth routes. \`apiLimiter\` is a moderate limit: 60 requests per minute. **Per-IP vs Per-User:** the middleware checks if \`req.user\` exists (authenticated) and uses \`req.user.id\` as the rate limit key; otherwise falls back to \`req.ip\`. This means authenticated users get a higher limit that doesn't change when their IP changes. **Redis-backed rate limiting:** uses \`rate-limit-redis\` with Redis client and \`sliding window\` type. This works across multiple server instances. The Redis key includes the prefix and the identifier (user ID or IP). **Custom middleware:** the \`rateLimitByRole\` middleware applies different limits based on user role - admin gets 1000 req/min, regular user gets 100. **Error response for 429:** \`{ error: { message: 'Too many requests', retryAfter: Math.ceil(windowMs / 1000) } }\` with \`Retry-After\` header set to the number of seconds to wait. **Always use Redis-based rate limiting in production** - in-memory rate limiting doesn't work with multiple server instances (each instance has its own counter, so a client could make N * instances requests before hitting the limit). **Rate limiting is essential for API security** - without it, a single client can exhaust your server resources or brute-force authentication endpoints.**`
  },
  'api-security': {
    explanation: `**API security** encompasses all measures to protect your API from attacks and unauthorized access. APIs are a primary attack surface because they expose application logic and data directly. A secure API requires multiple layers of defense.

**Authentication:** verify who the user is. Use JWT with short expiry (15 minutes) and refresh tokens. Use OAuth 2.0 / OpenID Connect for third-party access. Implement multi-factor authentication for sensitive operations. **Authorization:** control what authenticated users can do. Use role-based access control (RBAC) or attribute-based access control (ABAC). Check permissions at every endpoint. **Input validation:** validate ALL input - request body, query parameters, URL params, headers. Use a schema validation library (Zod, Joi). Sanitize input to prevent XSS. **Injection prevention:** use parameterized queries for databases. Don't eval() user input. Don't concatenate user input into commands. **Rate limiting:** prevent abuse and brute force attacks. **CORS:** restrict which origins can access your API. Never use \`Access-Control-Allow-Origin: *\` with credentials. **HTTPS:** always use TLS/SSL. Redirect HTTP to HTTPS. Use HSTS header. **Security headers:** Helmet.js sets essential headers. Content-Security-Policy restricts script execution. **CSRF protection:** for cookie-based auth, use anti-CSRF tokens or SameSite cookies. **Sensitive data exposure:** never expose passwords, tokens, or internal IDs in responses. Use \`.omit()\` from Prisma to exclude fields. Encrypt sensitive data at rest. **Logging and monitoring:** log security events (failed logins, access denied, rate limit exceeded). Use a SIEM or monitoring service. **Best practice:** adopt a security-by-design approach. Use the principle of least privilege. Validate everything. Keep dependencies updated. Run security scans (SAST, DAST). Have an incident response plan. Use API keys for programmatic access. Implement request signing for sensitive operations. Use Web Application Firewall (WAF). Conduct regular security audits. Follow OWASP API Security Top 10. Use API gateways for centralized security policies.`,
    codeExplanation: `This shows **API security middleware**. \`authenticate\` verifies JWT from Authorization header - attaches user to \`req.user\`. \`authorize('admin')\` checks if user's role is included in allowed roles. \`validate(createUserSchema)\` validates \`req.body\` against a Zod schema - returns 400 with field-level errors if invalid. \`sanitizeInput\` strips HTML tags from string fields to prevent stored XSS. \`auditLog\` middleware logs security events - who accessed what, with timestamp and result. **Helmet security headers** (applied globally) include: \`X-Content-Type-Options: nosniff\` (prevents MIME sniffing), \`X-Frame-Options: DENY\` (prevents clickjacking), \`Strict-Transport-Security\` (enforces HTTPS). **CORS configuration:** \`origin: ['https://app.example.com']\` restricts which origins can call the API. \`credentials: true\` allows cookies/auth headers. \`methods: ['GET', 'POST']\` restricts HTTP methods. **Input validation:** the Zod schema validates that email is a valid email, password is at least 8 characters, and name is a string. Invalid requests are rejected before they reach the handler. **Sensitive data:** Prisma's \`.omit({ passwordHash: true })\` excludes the password hash from the response. Even if a developer accidentally returns the full user object, the password hash is automatically excluded. **API security is not optional** - a single vulnerability can expose all user data. Implement all layers and test them regularly. Use automated security scanning tools.**`
  },
  'graphql-vs-rest': {
    explanation: `**GraphQL vs REST** is a common architectural decision. Both are API design approaches, but they differ fundamentally in how data is requested and delivered. REST uses multiple endpoints with fixed response structures; GraphQL uses a single endpoint where clients specify exactly what data they need.

**REST:** Multiple endpoints (\`/api/users\`, \`/api/users/:id/posts\`). Fixed response shapes - often over-fetching (getting fields you don't need) or under-fetching (needing multiple requests). HTTP caching is natural (\`GET\` requests are cacheable). Mature ecosystem, simpler mental model. **GraphQL:** Single endpoint (\`/graphql\`). Client specifies the exact fields needed in the query. Eliminates over/under-fetching. Strongly typed schema (self-documenting). Built-in introspection. Real-time with subscriptions. **When REST is better:** simple CRUD APIs, caching is important, file uploads, you want to leverage HTTP features (status codes, headers). **When GraphQL is better:** complex data requirements with nested relationships, multiple clients (web, mobile) need different data shapes, rapid frontend development, real-time features. **Trade-offs:** GraphQL queries can be expensive (no built-in pagination, complex queries can overload the server). Caching is harder (no natural HTTP caching). File uploads are more complex. Learning curve is steeper. **Best practice:** start with REST for simple APIs. Use GraphQL when you have complex data requirements and multiple clients. You can use both - REST for simple CRUD, GraphQL for complex queries. Use proper pagination in GraphQL (connections pattern). Implement query complexity analysis to prevent abuse. Use DataLoader to solve N+1 problem. Use persisted queries for production optimization. Consider GraphQL middleware (GraphQL Yoga, Apollo Server) for implementation. REST is not dead - it's still the right choice for many APIs. Choose based on your specific needs, not trends.`,
    codeExplanation: `This code compares **REST vs GraphQL** for fetching a user with their posts and followers. **REST** requires 3 requests: fetch user, fetch posts, fetch followers. This is under-fetching (the client needs multiple round trips). Alternatively, the API might return all data in a single response (but over-fetching if you only need some fields). **GraphQL** fetches everything in ONE request with EXACTLY the fields needed. The query requests \`name\`, \`email\`, \`posts.title\`, and \`followers.name\`. No extra data is returned. **REST response:** \`/api/users/1\` returns all user fields. Additional requests needed for related data. **GraphQL response:** exactly the requested fields. No over-fetching (no \`address\`, \`phone\` from user). No under-fetching (posts and followers included in the same response). **GraphQL is more efficient for complex data** - one round trip instead of three. The tradeoff is that the server needs to resolve multiple related data sources in a single request. **DataLoader** solves the N+1 problem (if 10 posts have 10 different authors, DataLoader batches and caches the author queries). **Apollo Client** provides caching, optimistic updates, and normalized cache on the frontend. REST is simpler to cache at the HTTP level (CDN caching of GET requests). GraphQL queries are POST requests (not cached by default). Choose based on your specific needs.**`
  },
  'graphql-basics': {
    explanation: `**GraphQL** is a query language and runtime for APIs developed by Meta (Facebook) in 2012 and open-sourced in 2015. It allows clients to request exactly the data they need, nothing more and nothing less. GraphQL APIs are defined by a **schema** that specifies types, queries, mutations, and subscriptions.

**Core concepts:** **Schema** defines the types and operations available. **Types** (\`type User { id: ID! name: String! posts: [Post!]! }\`) define the shape of data. **Queries** (\`type Query { user(id: ID!): User }\`) are for fetching data (equivalent to REST GET). **Mutations** (\`type Mutation { createUser(input: UserInput!): User }\`) modify data (equivalent to REST POST/PUT/DELETE). **Subscriptions** (\`type Subscription { newPost: Post }\`) enable real-time updates via WebSockets. **Resolvers** are functions that provide data for each field in the schema. **Schema Definition Language (SDL):** the syntax for defining schemas. **Non-nullable fields** (\`!\`): field must always have a value. **Lists** (\`[Post]\`): field returns an array. **Input types** (\`input UserInput\`): for mutation arguments. **Introspection:** GraphQL APIs are self-documenting - you can query the schema itself. **Best practice:** design the schema around business domains, not database tables. Use meaningful names. Always paginate list fields. Think about what queries and mutations consumers need. Use input types for mutation arguments. Version through evolution (add fields, don't remove them). Use federation or schema stitching for microservices. Implement query complexity limits to prevent abuse. Use persisted queries for production. Use \`@deprecated\` annotation for fields to be removed. Use UUIDs for IDs, not auto-incrementing integers (they reveal data cardinality). Document your schema with descriptions.`,
    codeExplanation: `This is a **GraphQL schema and resolvers**. The schema defines: \`User\` type (id, name, email, posts), \`Post\` type (id, title, content, author, createdAt), \`Query\` (\`user\`, \`users\`, \`post\`), \`Mutation\` (\`createUser\`, \`createPost\`). **Resolvers:** \`Query.user\` calls \`db.user.findUnique({ where: { id } })\` to fetch a user by ID. \`User.posts\` is a field resolver - it resolves the \`posts\` field on a User type by querying the database. **The resolver receives:** \`parent\` (the parent object, e.g., user), \`args\` (query arguments), \`context\` (shared context like db client, current user), \`info\` (query AST). **Mutations:** \`createUser\` receives \`input\` (UserInput), creates the user in the database, and returns it. **Error handling:** GraphQL errors are returned in the \`errors\` array of the response, alongside partial \`data\`. This means a query can partially succeed - some fields may have errors while others resolve successfully. **Context:** the GraphQL context is created per-request and typically contains the database client, authenticated user, and data loaders. **GraphQL is strongly typed** - the schema is the contract between client and server. Tools like GraphQL Code Generator can generate TypeScript types from the schema. Apollo Studio provides a GraphQL playground for exploring and testing queries.**`
  },
  'graphql-schemas-types': {
    explanation: `**GraphQL schemas and types** define the structure of your API. The schema is the contract between client and server - it specifies what data is available, what operations can be performed, and the relationships between types. A well-designed schema makes your API intuitive and evolvable.

**Type system:** **Scalar types** (Int, Float, String, Boolean, ID) - leaf values. **Object types** (\`type User { ... }\`) - have fields with their own types. **Enums** (\`enum Role { ADMIN USER }\`) - restricted set of values. **Interfaces** (\`interface Node { id: ID! }\`) - abstract types that other types implement. **Union types** (\`union SearchResult = User | Post\`) - one of several types. **Input types** (\`input CreateUserInput { ... }\`) - for mutation arguments. **Lists** (\`[Post!]!\`) - arrays, can be non-null at list or element level. **Non-null** (\`!\`) - field/argument always has a value. **Design principles:** Model the business domain, not the database schema. Use nouns for types, verbs for fields/mutations. Prefer explicit types over generic types. Use enums for fields with fixed values. Use interfaces for common fields (Node, Timestamp). Design mutations as actions (verbs), not CRUD (createUser, not saveUser). **Relationships:** one-to-many (\`User.posts\`), many-to-many (\`User.following\`). Use arguments to paginate list fields (\`posts(first: 10, after: String)\`). **Best practice:** always paginate list fields. Use cursor-based pagination (Relay connection spec). Use descriptive field names. Add descriptions to types and fields for documentation. Avoid deep nesting (more than 3-4 levels). Avoid circular references in input types. Use \`@deprecated\` for fields being phased out. Keep mutations focused (one mutation = one action). Return the modified object from mutations. Use a consistent naming convention (camelCase for fields, PascalCase for types). Version through additive changes (don't remove fields, add new ones). Use federation for microservices.`,
    codeExplanation: `This is a **GraphQL schema with advanced type features**. \`interface Node\` defines a common \`id\` field that \`User\` and \`Post\` implement. \`enum Role\` restricts user roles to ADMIN, MODERATOR, or USER. \`union SearchResult = User | Post\` allows search to return either type - the client uses \`__typename\` or inline fragments to handle different types. **Relay Connection spec for pagination:** \`PostConnection\` wraps a paginated list with \`edges\` (each edge has \`node\` and \`cursor\`) and \`pageInfo\` (hasNextPage, hasPreviousPage, startCursor, endCursor). \`posts(first: 10, after: String)\` implements cursor-based pagination. **Input types:** \`CreateUserInput\`, \`UpdateUserInput\`, and \`PostFilterInput\` encapsulate mutation arguments. **Resolvers:** \`User.posts\` field resolver handles pagination - uses \`first\`, \`after\` to slice results, constructs edges with cursors. \`SearchResult\` resolver uses \`__resolveType\` to determine which type a search result is (differentiates User from Post). **The Relay connection pattern is the standard for pagination in GraphQL** - it handles cursor-based pagination consistently across all list fields. \`pageInfo\` tells the client if there are more pages. Each edge has a cursor for requesting the next page. **Well-designed schemas are intuitive to use** - clients can explore the schema with introspection and understand exactly what fields are available.**`
  },
  'graphql-nodejs': {
    explanation: `**GraphQL with Node.js** is typically implemented using Apollo Server (full-featured) or GraphQL Yoga (lightweight, cross-platform). Both provide a GraphQL server that parses queries, executes resolvers, and returns responses. Apollo Server integrates with Express, Fastify, Lambda, and more.

**Apollo Server setup:** \`const server = new ApolloServer({ typeDefs, resolvers })\`. \`typeDefs\` is the schema (SDL string or document). \`resolvers\` are functions that resolve each field. \`startStandaloneServer(server)\` creates a standalone HTTP server. **Integration with Express:** \`const server = new ApolloServer({ typeDefs, resolvers })\`, then \`await server.start()\`, then \`app.use('/graphql', expressMiddleware(server))\`. **Context:** created per-request, typically contains database client, authenticated user, and data loaders. \`context: async ({ req }) => ({ db, user: await getUser(req) })\`. **DataLoader:** solves the N+1 problem by batching and caching database queries. \`const userLoader = new DataLoader(ids => db.user.findMany({ where: { id: { in: ids } } }))\`. **Error handling:** Apollo Server catches resolver errors and formats them. Custom errors: \`new ApolloError('message', 'ERROR_CODE', { details })\`. **Performance:** use \`@apollo/subgraph\` for federation. Use persisted queries to avoid sending full queries over the network. Use query planning and cost analysis. **Best practice:** use code-first approach (GraphQL Code Generator, TypeGraphQL, NestJS) with TypeScript for type safety. Use DataLoader for all database access to batch queries. Implement query depth limiting and complexity analysis. Use persisted queries in production. Use Apollo Studio for schema registry and performance monitoring. Use federation for microservices. Keep resolvers simple - they should delegate to service/business layer. Implement proper authentication and authorization in resolvers. Use context for per-request state. Handle errors gracefully with proper error codes.`,
    codeExplanation: `This shows **Apollo Server with Express and DataLoader**. \`ApolloServer\` is created with typeDefs (schema) and resolvers. \`expressMiddleware(server, { context })\` integrates with Express - the context function runs per-request, extracts the auth token, verifies it, and provides \`db\` (Prisma client) and \`user\` to all resolvers. **DataLoader:** \`new DataLoader(ids => db.user.findMany(...))\` batches multiple user queries into a single database call. The DataLoader collects all requested IDs from a single "tick" of the event loop and makes one batched query. **Resolver pattern:** \`Query.user\` resolver: uses \`context.db.user.findUnique\` to fetch user. \`User.posts\` field resolver: uses DataLoader (\`context.loaders.postsByUser.load(parent.id)\`) to load posts - multiple User.posts resolvers are batched into one database query. \`createUser\` mutation: validates input with Zod, creates user, returns it. **Error handling:** Apollo Server formats errors automatically. \`GraphQLError\` with extensions provides structured error info. **The N+1 problem:** without DataLoader, if a query requests 10 users and each user's posts, you'd make 1 + 10 = 11 database queries. With DataLoader, you make 1 user query + 1 posts query (batched) = 2 queries. **Production setup:** use Apollo Studio for schema registry, implement persisted queries, add query complexity limits, use response caching. Use GraphQL Code Generator for TypeScript types from the schema. Use \`@graphql-tools/load-files\` to split schema and resolvers into multiple files.**`
  },
  'graphql-subscriptions': {
    explanation: `**GraphQL Subscriptions** enable real-time communication between server and client. Unlike queries (request-response) and mutations (server responds with data), subscriptions maintain a persistent connection (typically WebSocket) and push data from server to client when events occur. Common use cases: live chat, notifications, real-time feeds, collaborative editing, live sports scores.

**How subscriptions work:** Client sends a subscription query (similar to a query but uses \`subscription\` keyword). Server establishes a WebSocket connection. When the subscribed event occurs, the server publishes data, and the client receives it in real-time. **Implementation:** Subscriptions use a **Pub/Sub** (publish/subscribe) system. In-memory PubSub works for single server. For production with multiple instances, use an external PubSub (Redis, MQTT, Kafka). **Apollo Server setup:** \`const server = new ApolloServer({ typeDefs, resolvers, subscriptions: { ... } })\`. Use \`SubscriptionServer\` or the newer \`@apollo/server/plugin/subscriptionCallback\`. **Event flow:** Mutation publishes an event -> PubSub notifies subscribers -> GraphQL subscription resolver pushes data to connected clients. **Filtering:** subscription resolvers can filter events based on arguments. \`newPost(topic: String)\` - only receive posts matching the topic. **Authentication:** authenticate the WebSocket connection during the connection handshake (not per-event). **Best practice:** use subscriptions only for real-time events that need immediate delivery. For polling-friendly data, use queries. For live queries, consider using a live query library (Hasura, Supabase). Use Redis PubSub for production deployments (so all server instances know about events). Clean up subscriptions when clients disconnect. Handle reconnection gracefully (client re-subscribes). Use subscription filters wisely to avoid sending too many events to clients. Implement backpressure handling - if a client can't keep up, decide whether to drop events or buffer them. Consider using Server-Sent Events (SSE) for simpler one-way real-time data (easier than WebSockets, works over HTTP/2). Libraries like Apollo Client handle subscription reconnection automatically. Use \`graphql-ws\` for WebSocket transport (replaces the deprecated \`subscriptions-transport-ws\`).`,
    codeExplanation: `This code shows **GraphQL subscriptions with Redis PubSub**. \`RedisPubSub\` uses Redis to publish/subscribe events - this works across multiple server instances (when one instance publishes an event, all instances receive it). The schema defines \`Subscription\` type with \`newPost\` and \`newNotification\` subscriptions. \`newPost(topic: String)\` can filter by topic. **Publishing:** the \`createPost\` mutation calls \`pubsub.publish('NEW_POST', { newPost: post })\` after creating the post in the database. This publishes the event. **Client subscription:** the \`newPost\` subscription resolver uses \`pubsub.asyncIterator('NEW_POST')\` to listen for events. The \`withFilter\` function filters events - only passes through posts matching the requested \`topic\` argument. **Apollo Server setup:** \`expressMiddleware\` is used with a WebSocket server for subscriptions. The \`SubscriptionServer\` creates a WebSocket endpoint at \`/graphql\`. **Client-side (Apollo Client):** uses \`GraphQLWsLink\` to create a WebSocket connection. \`subscribeToMore\` subscribes to new posts and merges them into the existing cached query. **Subscriptions trigger UI updates** - \`subscribeToMore\` receives the new post and calls \`updateQuery\` to merge it into the existing list (prepending it). The UI re-renders automatically. **For production:** use \`@graphql-yoga\` (built-in subscription support with SSE and WebSocket), or \`@as-integrations/next\` for Next.js. Use Redis for PubSub in multi-instance deployments. Handle client reconnection automatically. Implement event deduplication for critical events. Monitor subscription connection counts. Consider whether you truly need subscriptions - REST polling with \`setInterval\` is simpler and sufficient for many use cases.**`
  },
  'graphql-performance': {
    explanation: `**GraphQL performance optimization** addresses the unique challenges of GraphQL APIs: the N+1 problem, expensive queries, over-fetching from databases, and caching difficulties. Because clients control what data they request, the server must handle unpredictable query patterns efficiently.

**N+1 problem:** When fetching a list of N items and their related data, without optimization, you make 1 query for the list + N queries for the related data. **Solution: DataLoader** batches individual requests into a single batch query. All field resolvers that load the same type are batched together. **Query complexity analysis:** Prevent expensive queries by limiting query depth, calculating query cost, and rejecting overly complex queries. Use \`graphql-query-complexity\` or Apollo's built-in plugin. **Persisted queries:** Store queries on the server; clients send only the query hash. Reduces request size, prevents arbitrary queries, enables whitelisting. **Response caching:** GraphQL responses are POST requests (not cached by default). Use Apollo's \`@apollo/cache-control\` for automatic cache headers, or use a CDN cache with GET requests for persisted queries. **Dataloader caching:** DataLoader caches results within a single request - if a user is requested multiple times, only one query is made. **Schema design for performance:** design types to minimize database queries. Use proper pagination. Limit the number of resolvable fields per type. **Resolver optimization:** compute multiple fields in one resolver (parent resolver pattern). Optimize database queries (select only needed columns, use include/join). **Monitoring:** use Apollo Studio to see query performance, slow resolvers, and error rates. **Best practice:** always use DataLoader for relational data. Implement query depth and complexity limits. Use persisted queries in production. Design schemas with performance in mind (avoid deeply nested types if not needed). Profile your GraphQL API regularly. Use response caching for frequently accessed data. Consider using view materialization or denormalization for frequently accessed data patterns. For read-heavy APIs, consider using a read-optimized database or cache layer. Implement field-level metrics to identify slow resolvers. Use batching at the database level (Prisma's include/select joins multiple tables in one query).`,
    codeExplanation: `This code shows **GraphQL performance optimizations**. **DataLoader:** \`createPostLoader\` creates a DataLoader that batches post queries. \`userLoader.load(parent.id)\` is called in the field resolver - DataLoader collects all IDs from the current event loop tick and makes a single database query. Without DataLoader, querying 10 users with their posts would make 1 users query + 10 posts queries = 11 queries. With DataLoader: 1 users query + 1 posts query = 2 queries. **Query complexity analysis:** \`createComplexityPlugin\` calculates the cost of each query based on field multipliers. Simple fields cost 1, list fields cost 10 per item. Queries exceeding \`maxComplexity\` (1000) are rejected with an error. This prevents abusive queries from overloading the server. **Persisted queries:** the \`store\` maps query hashes to full queries. The \`@apollo/server-plugin-operation-registry\` requires queries to be registered - clients send only the hash, reducing request size and preventing arbitrary queries. **Dataloader caching** is per-request - if the same user is requested multiple times within a single GraphQL query, DataLoader returns the cached result. This cache is cleared after each request. **Response caching:** \`@cacheControl(maxAge: 60)\` directive on schema fields tells Apollo to cache the response for 60 seconds. This works with CDN caching when using GET requests. **Performance checklist:** use DataLoader for all relational fields. Implement query depth limits (max 7-10 levels). Use persisted queries. Monitor slow queries. Enable response caching. Optimize database queries (select only needed columns, use joins). Use pagination on all list fields. Profile with Apollo Studio. Batch database operations. Use a read replica for read-heavy workloads.**`
  },
  'auth-basics': {
    explanation: `**Authentication** is the process of verifying a user's identity. It answers "who are you?" while **authorization** answers "what can you do?". Authentication is the foundation of web application security. The main approaches are session-based auth (server-side sessions with cookies) and token-based auth (JWT).

**Session-based auth:** User logs in -> server creates a session, stores it (in memory, database, or Redis), and sends a session cookie to the client. Client sends the cookie with every request. Server looks up the session to identify the user. **Pros:** Server controls sessions (can revoke instantly), simpler for traditional web apps. **Cons:** Stateful (server must track sessions), harder to scale horizontally (need shared session store). **JWT (JSON Web Token):** User logs in -> server creates a signed token with user info (claims). Client stores the token and sends it in the \`Authorization\` header. Server verifies the signature. **Pros:** Stateless (no session lookup), scales horizontally easily, can be used across different services. **Cons:** Can't revoke tokens server-side (must wait for expiry), token storage on client requires security consideration. **Authentication flows:** **Login/Password** (traditional), **OAuth 2.0** (login with Google/GitHub), **Magic Link** (email-based, passwordless), **MFA/2FA** (extra verification factor). **Password security:** never store plain text passwords. Use bcrypt to hash with salt rounds (10-12). **JWT best practices:** use short expiry (15 minutes), use refresh tokens (7-30 days), store access tokens in memory (not localStorage), store refresh tokens in httpOnly secure cookies. **Best practice:** use established libraries (Passport.js, NextAuth.js, Lucia) instead of implementing from scratch. Always use HTTPS. Implement rate limiting on login endpoints. Use secure, httpOnly cookies. Implement account lockout after failed attempts. Log auth events. Use CSRF protection for cookie-based auth. Consider WebAuthn/Passkeys for passwordless auth.`,
    codeExplanation: `This code shows **authentication fundamentals**. \`POST /auth/register\`: receives email and password. Validates with Zod. Hashes password with bcrypt (\`bcrypt.hashSync(password, 12)\` - 12 salt rounds). Creates user in database. Generates tokens and returns them. \`POST /auth/login\`: finds user by email, verifies password with \`bcrypt.compareSync(password, user.passwordHash)\`. Generates tokens. \`generateAccessToken\`: creates a JWT with user ID and role, expires in 15 minutes. \`generateRefreshToken\`: longer-lived (7 days), stored in database for revocation. \`authenticate\` middleware: extracts token from Authorization header (\`req.get('Authorization')?.replace('Bearer ', '')\`). Verifies JWT (\`jwt.verify(token, ACCESS_TOKEN_SECRET)\`). Attaches decoded user to \`req.user\`. **Token refresh:** endpoint accepts refresh token, verifies it, checks if it exists in database (allows revocation), generates new access token. **Cookie option:** set tokens as \`httpOnly\` cookies (not accessible via JS), \`secure\` (HTTPS only), \`sameSite: 'strict'\` (CSRF protection). **Security considerations:** passwords are never stored in plain text. JWT secrets are in environment variables (never hardcoded). Access tokens are short-lived (15 min). Refresh tokens are stored in database and can be revoked. Rate limiting on auth endpoints prevents brute force. Account lockout after 5 failed attempts. HTTPS in production is mandatory. CORS is properly configured. Session cookie is signed to prevent tampering.**`
  },
  'jwt-authentication': {
    explanation: `**JWT (JSON Web Token) authentication** is a stateless authentication mechanism. The server creates a signed token containing user claims (like user ID and role). The client stores this token and sends it with every request. The server verifies the signature without needing to look up session state. JWTs are self-contained - all user information is in the token itself.

**JWT structure:** \`header.payload.signature\`. **Header** specifies the algorithm (HS256, RS256). **Payload** contains claims (registered claims like \`sub\`, \`iat\`, \`exp\`, and custom claims like \`role\`). **Signature** is created by signing the header+payload with a secret (HMAC) or private key (RSA/ECDSA). **Access Token vs Refresh Token:** **Access token** is short-lived (15 min), sent with every request in the Authorization header. **Refresh token** is long-lived (7-30 days), used only to get new access tokens. Stored securely, can be revoked. **Token storage:** Access tokens: in memory (variable in JS) is most secure but requires re-login on page refresh. A common compromise: store in memory and use refresh token in httpOnly cookie to get new access token on page load. **Never store JWT in localStorage** - it's accessible to any JavaScript on the same origin (XSS vulnerability). **Signature algorithms:** **HS256** (HMAC with SHA-256) - symmetric, same secret signs and verifies. **RS256** (RSA with SHA-256) - asymmetric, private key signs, public key verifies. Use RS256 for microservices (only the auth service has the private key). **JWT best practices:** use short expiry. Use refresh token rotation (old refresh token is invalidated when a new one is issued). Keep token payload small (don't include sensitive data). Use the \`jti\` (JWT ID) claim to identify specific tokens for blacklisting. Validate the \`aud\` (audience) and \`iss\` (issuer) claims. Use httpsOnly cookies for refresh tokens. Implement token revocation (blacklist or version-based). Use established libraries (jsonwebtoken, jose) - don't implement JWT validation yourself. Use algorithm whitelisting to prevent algorithm confusion attacks.`,
    codeExplanation: `This code shows **JWT implementation**. \`generateAccessToken(user)\`: creates a JWT with \`sub\` (user ID), \`role\`, \`iat\` (issued at), \`exp\` (expiry - 15 min). Signs with \`ACCESS_TOKEN_SECRET\` using HS256. \`generateRefreshToken(user)\`: longer expiry (7 days), stores a hash in the database for revocation. \`verifyAccessToken(token)\`: verifies signature, checks expiry, returns decoded payload. Throws if invalid. **Token refresh:** receives refresh token, verifies it, checks database for revocation, generates new access+refresh tokens, invalidates old refresh token (rotation). **Authentication middleware:** checks Authorization header, extracts Bearer token, verifies it, attaches user to \`req.user\`. **Login endpoint:** validates email/password, calls \`generateTokens\` which creates both tokens and stores the refresh token hash. Returns both tokens. **Refresh endpoint:** validates the refresh token, checks it hasn't been revoked (\`prisma.refreshToken.findUnique\`), generates new tokens, marks old token as used (\`refreshToken.used = true\`). \`revokeAllUserTokens\`: marks all user's refresh tokens as revoked - useful for password change or account compromise. **Security:** access tokens are short-lived (15 minutes). Refresh tokens are stored in database and can be revoked. Token rotation means a stolen refresh token can only be used once. Secrets are in environment variables. The JWT library validates signature, expiry, and algorithm automatically. Algorithm whitelisting prevents algorithm confusion attacks. Keep the payload small (only essential claims). Never store sensitive data in the token.**`
  },
  'oauth-social-login': {
    explanation: `**OAuth 2.0 social login** allows users to sign in using their existing accounts from providers like Google, GitHub, Facebook, or Apple. It uses the Authorization Code flow, where the application never sees the user's password. The provider authenticates the user and gives the application an access token and user identity information.

**Authorization Code flow:** 1. User clicks "Login with Google". 2. App redirects to Google's authorization URL with client ID, redirect URI, and scopes. 3. User authenticates on Google and consents to sharing data. 4. Google redirects back to the app with a temporary authorization code. 5. App exchanges the code for an access token (and optionally an ID token) by calling Google's token endpoint with the client secret. 6. App uses the access token to fetch user profile from Google's API. 7. App finds or creates a user in its database and creates a session/JWT. **OpenID Connect (OIDC):** extends OAuth 2.0 with an ID token (JWT) that contains verified user identity. This is what most social login implementations actually use. **Passport.js:** the most popular Node.js authentication library. Provides strategies for hundreds of providers. Each strategy implements the specific OAuth/OIDC flow. **State parameter:** a random value sent in the initial redirect and verified in the callback - prevents CSRF attacks. **Scopes:** specify what data you're requesting (\`profile\`, \`email\`). Request only what you need. **Best practice:** use established libraries (Passport.js, NextAuth.js). Don't implement OAuth yourself. Always use PKCE for mobile/native apps. Validate the \`state\` parameter. Use HTTPS. Store client secrets securely (environment variables). Request minimal scopes. Link social accounts to existing user accounts if the email matches. Handle the case where a social login email already exists. Allow users to unlink social accounts. Implement account linking carefully to prevent account takeover. Use OAuth for both authentication and authorization (accessing provider APIs). Use OIDC's ID token for user identity (contains verified claims). Always validate the ID token's signature, issuer, and audience.`,
    codeExplanation: `This code shows **Google OAuth with Passport.js**. \`GoogleStrategy\` configuration: \`clientID\` and \`clientSecret\` from environment variables. \`callbackURL\` is where Google redirects after auth. \`scope\` specifies requested data (profile, email). The **verify callback** receives \`accessToken\`, \`refreshToken\`, \`profile\`, and \`done\`. It extracts user info from the profile (\`profile.emails[0].value\`, \`profile.displayName\`, \`profile.photos[0].value\`). Finds existing user by provider + providerId (\`prisma.account.findUnique\`). If not found but email exists (different provider), links accounts. If not found at all, creates a new user and account. Calls \`done(null, user)\` to pass user to Passport. **Routes:** \`GET /auth/google\` starts the flow (Passport redirects to Google). \`GET /auth/google/callback\` handles the callback - Passport exchanges the code for tokens and calls the verify callback. \`failureRedirect\` goes to /login on error. **JWT generation:** after successful auth, creates a JWT for the user and redirects to the frontend with the token. **NextAuth.js equivalent:** \`providers: [\n  GitHub({\n    clientId: process.env.GITHUB_ID,\n    clientSecret: process.env.GITHUB_SECRET\n  })\n]\` - much simpler API. **Account linking:** if the user's social email matches an existing account, link the social account instead of creating a duplicate. This is done by checking \`prisma.user.findUnique({ where: { email } })\` before creating a new user. **Security:** the \`state\` parameter is automatically handled by Passport (CSRF protection). The client secret is never exposed to the browser. All communication is over HTTPS. The ID token (from OIDC) should be verified if you need strongly verified identity claims.**`
  },
  'role-based-access': {
    explanation: `**Role-Based Access Control (RBAC)** is an authorization model where permissions are assigned to roles, and roles are assigned to users. Instead of managing permissions for each user individually, you manage roles and assign users to roles. This scales much better as the number of users grows.

**Core concepts:** **Roles** are categories of users (\`admin\`, \`moderator\`, \`user\`). **Permissions** are specific actions (\`read:users\`, \`write:posts\`, \`delete:posts\`). **Role-permission mapping:** which permissions each role has. **User-role mapping:** which role each user has. **Authorization check:** check if the user's role has the required permission before allowing an action. **Implementation approaches:** **Enums** (simple roles like 'admin' | 'user') - limited, hard to extend. **Database model** (permissions table, roles table, user_roles table) - flexible, scalable. **Middleware-based** (check role/permission in middleware before route handler). **Method-level** (in service functions). **Permission hierarchy:** Admin includes all lower permissions. Moderator has moderation permissions but not admin permissions. User has only basic permissions. **Attribute-Based Access Control (ABAC):** more granular than RBAC - uses user attributes, resource attributes, and environmental conditions. Example: "Managers can edit reports they created during business hours." **Best practice:** define roles and permissions clearly. Use the principle of least privilege (give users only the permissions they need). Prefer permission checks over role checks (check "can user delete this post?" rather than "is user admin?"). Centralize authorization logic (don't scatter checks throughout the code). Use a consistent check pattern. Log authorization failures. Review roles and permissions regularly. For simple apps, role-based middleware is sufficient. For complex apps, use a permission-based system with a database. Use CASL or AccessControl libraries for advanced authorization. Implement both middleware (for early rejection) and service-level (for business rule enforcement) checks. Never rely solely on frontend authorization - always enforce on the server.`,
    codeExplanation: `This code shows **RBAC implementation**. The database schema has \`Permission\` (individual actions), \`Role\` (group of permissions), and \`User\` (with assigned role). **Permission definitions:** \`Permissions\` enum defines all possible actions. \`RolePermissions\` mapping defines which permissions each role has. **Authorization middleware:** \`authorize('read:users')\` checks if the authenticated user's role includes the required permission. Returns 403 if not. \`checkPermission(user, requiredPermission)\` looks up the user's role permissions and checks if the required permission is included. **Route protection:** \`router.get('/users', authenticate, authorize('read:users'), getUsers)\` - three middleware layers: authenticate (verify JWT), authorize (check permission), handler (execute). **Resource-based authorization:** \`authorizeResource('post')\` checks if the user can modify a specific resource (e.g., only the post author or an admin can edit). Uses a resource owner check: \`resource.userId === user.id || hasPermission(user, 'manage:posts')\`. **Permission inheritance:** Admin role includes all permissions (\`Object.values(Permissions)\`). Moderator includes moderation permissions. User includes basic permissions. **Best practices:** use \`authorize('permission')\` middleware on routes. For resource-specific checks, implement \`authorizeResource\` that loads the resource and checks ownership. Centralize permission definitions. Use constants/enums for permission names (avoid magic strings). Log authorization failures for security monitoring. Cache role-permission mappings for performance. Implement a \`superadmin\` role that bypasses all checks for system maintenance. Use CASL library for complex permission rules (conditions, fields, and actions). Test authorization logic thoroughly - this is where security vulnerabilities hide.**`
  },
  'auth-security': {
    explanation: `**Authentication security** encompasses best practices for protecting user accounts and authentication systems from common attacks. Authentication is the most targeted part of any application because compromising it gives attackers access to user data and actions.

**Key threats and mitigations:** **Brute force attacks** - attackers try many passwords. Mitigate with rate limiting (slow down repeated attempts), account lockout (temporarily disable account after N failures), and CAPTCHA. **Credential stuffing** - attackers use passwords leaked from other sites. Mitigate with MFA, breached password detection (check against known breached passwords via HaveIBeenPwned API), and encourage password managers. **Phishing** - fake login pages. Mitigate with MFA (especially hardware keys), security awareness training, and domain monitoring. **Session hijacking** - stealing session tokens. Mitigate with httpOnly, secure, sameSite cookies; short session expiry; fingerprinting (check IP/user-agent changes). **CSRF (Cross-Site Request Forgery)** - attackers make authenticated requests from other sites. Mitigate with anti-CSRF tokens (or SameSite cookies, custom headers). **XSS (Cross-Site Scripting)** - attackers inject scripts to steal tokens. Mitigate with CSP headers, input sanitization, httpOnly cookies (prevents JS access). **Password policies:** minimum 8 characters, encourage passphrases (not complex rules), check against common password lists, use password strength meters. **MFA/2FA:** the most effective single security measure. Methods: TOTP (Google Authenticator), SMS (less secure - SIM swapping), hardware keys (WebAuthn/FIDO2 - most secure). **Account recovery:** secure password reset (email link with short expiry, security questions are weak), account recovery codes. **Best practice:** implement MFA for all users (at least optional). Use rate limiting on all auth endpoints. Use bcrypt for password hashing (cost factor 12). Set short session/JWT expiry. Implement refresh token rotation. Log all auth events. Monitor for suspicious activity (new device, new location, unusual time). Use a Web Application Firewall (WAF). Keep auth libraries updated. Follow OWASP Authentication Cheat Sheet. Use security.txt file. Have an incident response plan for auth breaches.`,
    codeExplanation: `This code shows **auth security measures**. **Rate limiting on login:** \`loginLimiter\` allows 5 attempts per 15 minutes per IP. Exceeding the limit returns 429. **Account lockout:** \`failedAttempts\` counter in database - after 5 failed attempts, the account is locked for 15 minutes (\`lockedUntil\`). Successful login resets the counter. **Breached password check:** uses HaveIBeenPwned API (k-anonymity model - sends first 5 chars of SHA-1 hash, checks against returned suffixes). **Password policy:** Zod validates minimum length (8), requires uppercase, lowercase, number, and special character. **MFA setup:** \`POST /auth/mfa/setup\` generates a TOTP secret and QR code URI. User scans with authenticator app. \`POST /auth/mfa/verify\` verifies the TOTP code, enables MFA. \`POST /auth/mfa/disable\` requires current password verification. **Login with MFA:** if user has MFA enabled, login returns a temporary token (instead of full JWT) and requires \`POST /auth/mfa/verify\` with the TOTP code to get the actual JWT. **Security headers:** \`helmet()\` adds CSP, HSTS, X-Frame-Options, and other security headers. \`session.cookie.httpOnly = true\` prevents XSS from reading the cookie. \`secure: true\` sends cookies only over HTTPS. \`sameSite: 'strict'\` prevents CSRF. **MFA is the single most impactful security measure** - it protects against credential stuffing, phishing, and most password-based attacks. Hardware security keys (WebAuthn) are more secure than TOTP. SMS-based MFA is better than nothing but vulnerable to SIM swapping. Always offer MFA to users. Consider making MFA mandatory for admin accounts.**`
  },
  'mongodb-basics': {
    explanation: `**MongoDB** is a NoSQL document database that stores data as JSON-like documents (BSON format). Unlike SQL databases with rigid schemas, MongoDB has a flexible schema where each document can have different fields. It's designed for scalability, high performance, and ease of development for modern applications.

**Key concepts:** **Databases** contain collections. **Collections** contain documents (equivalent to SQL tables). **Documents** are JSON-like objects with key-value pairs (equivalent to SQL rows). **\`_id\`** is the unique identifier (auto-generated ObjectId or you can provide your own). **Embedding vs Referencing:** with embedding, related data is nested inside the document (like an array of addresses). With referencing, you store an ID and use joins (\`$lookup\`) to fetch related data. **MongoDB is schema-flexible** but you should still design your schema (use Mongoose schemas for validation). **CRUD operations:** \`db.collection.find(filter)\` (read), \`insertOne\`/\`insertMany\` (create), \`updateOne\`/\`updateMany\`, \`deleteOne\`/\`deleteMany\`. **Aggregation pipeline:** powerful data processing pipeline with stages like \`$match\`, \`$group\`, \`$sort\`, \`$project\`, \`$lookup\`. **Indexes:** improve query performance, same concept as SQL. **Replica sets:** provide high availability with automatic failover. **Sharding:** horizontal scaling by distributing data across multiple servers. **Best practice:** design documents based on how your application accesses data (access patterns drive schema design - not normalization rules like SQL). Prefer embedding for tightly-coupled, frequently-accessed-together data. Prefer referencing for loosely-coupled, independent data. Use meaningful field names. Use proper data types (Date for dates, Number for numbers). Create indexes for your query patterns. Use the aggregation pipeline for complex transformations. Use Mongoose or the native MongoDB driver. Enable validation. Monitor slow queries. Use 3-node replica sets for production. Use WiredTiger storage engine (default). Use transactions for multi-document atomicity (MongoDB 4.0+).`,
    codeExplanation: `This code shows **MongoDB CRUD operations** with the native Node.js driver. \`MongoClient.connect\` connects to the MongoDB server. \`db.collection('users')\` accesses the users collection. \`insertOne\` creates a document - MongoDB auto-generates \`_id\`. \`find({ ... }).toArray()\` queries documents with a filter. \`updateOne({ _id }, { $set: { name } })\` updates specific fields. \`deleteOne({ _id })\` deletes a document. **Aggregation pipeline:** \`$match\` filters documents (like SQL WHERE). \`$group\` groups by a field and computes aggregates (like SQL GROUP BY). \`$sort\` sorts results. \`$project\` selects which fields to return. \`$lookup\` performs a left outer join with another collection (like SQL JOIN). **Mongoose ODM** provides schema validation and a higher-level API. \`mongoose.Schema\` defines the schema with types, required fields, defaults, and timestamps (auto createdAt/updatedAt). \`mongoose.model('User', userSchema)\` creates the model. \`User.find({ age: { $gt: 25 } })\` queries with Mongoose. **Indexes:** \`db.collection('users').createIndex({ email: 1 }, { unique: true })\` creates a unique index on email for fast lookups. \`createIndex({ status: 1, createdAt: -1 })\` creates a compound index for common query patterns. **MongoDB is great for** rapid prototyping, content management, catalogs, real-time analytics, and applications with evolving schemas. Use the aggregation pipeline for reports and data analysis. Use \`explain()\` to check if queries use indexes. Use MongoDB Compass for visual data exploration. Mongoose provides schema validation, middleware (pre/post hooks), virtual fields, and population (automatic ref replacement).**`
  },
  'mongodb-schema-design': {
    explanation: `**MongoDB schema design** is fundamentally different from SQL schema design. In SQL, you normalize data into tables based on relationships. In MongoDB, you design documents based on how your application accesses data. The three key considerations: **embedding** (nesting related data inside a document) vs **referencing** (storing an ID to another document), and the **access patterns** of your application.

**Embedding:** Store related data directly inside the document. **Good for:** tightly-coupled data accessed together (user profile and addresses), one-to-one and one-to-few relationships, data that doesn't grow unbounded. **Pros:** single query fetches all related data, no joins needed, atomic updates. **Cons:** document size limit (16MB), can't access embedded data independently, data duplication. **Referencing:** Store an ID that references another document. **Good for:** loosely-coupled data, many-to-many relationships, data that grows unbounded (posts by a user). **Pros:** no data duplication, independent access, no size limit. **Cons:** requires multiple queries or \`$lookup\` (slower). **One-to-one:** embed (address in user document). **One-to-few:** embed (array of phone numbers). **One-to-many:** reference (user has many posts - store userId in post). **Many-to-many:** reference with arrays (students and courses). **Access pattern-driven design:** Ask: "What queries does my app make?" Design documents to answer those queries efficiently. **Denormalization:** duplicating data across documents for read performance. Example: store user name in order documents so you don't need to join. **Best practice:** favor embedding for most relationships. Switch to referencing when embedding would cause excessive duplication, unbounded arrays, or document size limits. Use \`$lookup\` sparingly (prefer embedding or application-level joins). Pre-join data at write time rather than join at read time for read-heavy workloads. Use two-way referencing (both sides store the reference) for efficient queries in both directions. Use bucketing for time-series data (group measurements into hour/day documents). Model data for the most common access patterns. Use the Schema Design patterns from MongoDB University. Test your schema with realistic data volumes. Document your schema decisions - they're not always intuitive.`,
    codeExplanation: `This code compares **embedding vs referencing in MongoDB**. **Embedding:** The user document contains an embedded \`address\` object (one-to-one) and an array of \`phoneNumbers\` (one-to-few). All data is fetched in one query. Update the address atomically with the user. **Referencing:** The \`Post\` collection stores \`userId\` referencing the user. To get a user's posts, query posts by userId. To get a user with their posts, need either two queries or \`$lookup\`. **Two-way referencing:** User has \`postIds\` array, Post has \`authorId\`. This allows efficient queries in both directions (find posts by user, find user by post). However, keeping both references in sync requires updates on both sides. **The aggregation \`$lookup\`** performs a left outer join - fetches user info for each post. This is MongoDB's equivalent of SQL JOIN. **Access pattern example:** if your app frequently displays a user with their 5 most recent posts, two queries (user lookup + recent posts query with index on userId+createdAt) can be faster than a single \`$lookup\` (which scans the posts collection). **Design decision framework:** embed if: data is always accessed together AND data doesn't grow unbounded (max ~100 items, < 16MB total). Reference if: data is often accessed independently OR data grows unbounded OR the relationship is many-to-many. **Denormalization example:** store \`userName\` and \`userEmail\` directly in the order document. This duplicates data (updating the user's name requires updating all their orders) but makes order queries fast (no join needed). This tradeoff is worth it for read-heavy workloads where user names rarely change.**`
  },
  'mongodb-indexing': {
    explanation: `**MongoDB indexes** are data structures that improve query performance by reducing the number of documents that need to be scanned. Without an index, MongoDB performs a collection scan (scans every document). With the right index, MongoDB can find documents much faster. Indexes are critical for production MongoDB performance.

**Index types:** **Single field** - index on one field (\`{ email: 1 }\`). **Compound** - index on multiple fields (\`{ status: 1, createdAt: -1 }\`). The order of fields matters: equality matches should come first, then sort, then range. **Multikey** - automatically created for array fields. **Text** - for full-text search on string content. **Geospatial** - for location-based queries. **Hashed** - for hash-based sharding. **TTL (Time-To-Live)** - automatically remove documents after a specified time. **Unique** - prevent duplicate values. **Partial** - index only documents matching a filter (smaller index). **Index properties:** \`1\` = ascending, \`-1\` = descending. For sorting, match the sort direction. **Index considerations:** indexes speed up reads but slow down writes (indexes must be updated). Each index consumes disk space. Indexes are stored in RAM for best performance (working set should fit in RAM). **Query optimizer:** MongoDB's query planner examines multiple query plans and chooses the fastest one. Use \`.explain('executionStats')\` to see which index is used. **Best practice:** create indexes for your most common query patterns. Use compound indexes that match your query filter, sort, and projection. Use the ESR (Equality, Sort, Range) rule for compound index field order. Avoid over-indexing (each index adds write overhead). Monitor slow queries with \`db.currentOp()\` and the profiler. Use \`hint()\` to force a specific index (temporarily, for testing). Remove unused indexes (use \`$indexStats\` to find them). Use partial indexes for queries that filter on a specific field value. Use unique indexes for fields that must be unique (email, username). Create indexes during off-peak hours. Build indexes in the background to avoid blocking writes. Test indexes with realistic data volumes.`,
    codeExplanation: `This code shows **MongoDB index creation and usage**. \`createIndex({ email: 1 }, { unique: true })\` creates a unique ascending index on email - prevents duplicate emails and speeds up email lookups. \`createIndex({ status: 1, createdAt: -1 })\` creates a compound index: first status (equality match), then createdAt (sort). This handles queries that find active users sorted by creation date. **ESR rule:** E (Equality) fields first: \`status\`. S (Sort) fields second: \`createdAt\`. R (Range) fields last if applicable. **Text index:** \`createIndex({ name: 'text', bio: 'text' })\` enables full-text search across name and bio fields. Uses \`$text\` and \`$search\` operators. \`explain('executionStats')\` shows query execution details: \`IXSCAN\` (index scan) is used, \`totalDocsExamined: 3\` (only 3 documents scanned), \`executionTimeMillis: 0\` (fast). Without the index, it would show \`COLLSCAN\` (collection scan) and scan all documents. **TTL index:** \`createIndex({ createdAt: 1 }, { expireAfterSeconds: 86400 })\` automatically deletes documents after 24 hours (86400 seconds) from their \`createdAt\` field. Great for session stores, temporary data, and logs. **Partial index:** \`createIndex({ status: 1, createdAt: -1 }, { partialFilterExpression: { status: 'active' } })\` only indexes active status documents - smaller index, faster for active-only queries. **Multikey index:** automatically created when indexing an array field - each array element gets an index entry. **Index management:** \`dropIndex('index_name')\` removes an index. \`$indexStats\` shows index usage statistics - useful for finding unused indexes. **Monitor slow queries with** \`db.setProfilingLevel(1, { slowms: 100 })\` to log queries taking longer than 100ms. Check \`system.profile\` collection for slow queries. Use MongoDB Atlas's Performance Advisor for automatic index recommendations.**`
  },
  'mongodb-nodejs': {
    explanation: `**MongoDB with Node.js** is typically implemented using the native MongoDB Node.js driver (low-level, full control) or Mongoose (ODM - Object Document Mapper, higher-level, schema validation). Mongoose is more popular for most applications because it provides schema validation, type casting, middleware (pre/post hooks), virtual fields, and population (automatic reference replacement).

**Mongoose features:** **Schema** defines the structure, validation, defaults, and options. **Model** is the interface for database operations. **Validation** (built-in: required, enum, minlength, match; custom validation functions). **Middleware** (pre/post hooks for save, validate, remove, update, aggregate). **Virtuals:** computed properties not stored in MongoDB (like fullName from firstName + lastName). **Population:** automatically replace \`ref\` IDs with the referenced document (\`.populate('author')\`). **Plugins:** reusable schema logic (mongoose-paginate, mongoose-autopopulate). **Transactions:** multi-document transactions with \`session\`. **Connection management:** \`mongoose.connect()\` handles connection pooling, auto-reconnection, and buffering (operations wait for connection). **Best practice:** define clear schemas with proper validation. Use Mongoose for most projects (unless you need maximum performance or raw MongoDB features). Use the native driver for aggregation-heavy or performance-critical operations. Use connection string from environment variables. Enable strict mode (default) to prevent saving fields not in schema. Use \`.lean()\` for read-only queries (returns plain JS objects instead of Mongoose documents - much faster). Handle connection errors. Use middleware for pre-save password hashing. Use virtuals for computed fields. Use population for references (but be careful of N+1). Do expensive operations in aggregation pipeline (server-side) instead of in application code. Use indexes that match your Mongoose query patterns. Use TypeScript with Mongoose for type safety. Monitor connection pool usage.`,
    codeExplanation: `This code shows **Mongoose with Node.js**. \`mongoose.connect(uri)\` connects to MongoDB - connection string includes database name, auth, and options. The Schema defines \`name\` (String, required, trimmed), \`email\` (String, required, unique, lowercase, validated), \`passwordHash\` (String, required), \`role\` (String, enum, default: 'user'), \`posts\` (array of ObjectId refs to 'Post'). \`timestamps: true\` automatically adds \`createdAt\` and \`updatedAt\`. **Pre-save hook:** \`userSchema.pre('save', async function()\` hashes the password before saving - only if the password field was modified (\`this.isModified('password')\`). **Virtual:** \`userSchema.virtual('postCount').get(function() { return this.posts.length })\` - computed field not stored in DB. **Instance method:** \`userSchema.methods.comparePassword\` compares password hash. **Populate:** \`.populate('posts')\` replaces post ObjectIds with actual post documents. \`.populate('posts', 'title -_id')\` populates only specific fields, excluding \`_id\`. **Lean:** \`.lean()\` returns plain JS objects instead of Mongoose documents - 5-10x faster for read-only queries. **Transaction:** \`const session = await mongoose.startSession()\`, \`session.startTransaction()\`, \`User.create([{ ... }], { session })\`, \`session.commitTransaction()\`. Transactions require a replica set. **Error handling:** Mongoose validation errors have \`errors\` object with field-level messages. \`error.code === 11000\` indicates a duplicate key error (unique constraint violation). **Mongoose provides a structured, schema-driven way to work with MongoDB** - it's the standard choice for most Node.js applications. Use it unless you have specific needs that require the native driver.**`
  },
  'mongodb-replication': {
    explanation: `**MongoDB replication** uses replica sets to provide high availability and data redundancy. A replica set is a group of MongoDB servers that maintain the same data set. One node is the **primary** (receives all writes), and the others are **secondaries** (replicate data from primary). If the primary fails, an election automatically promotes a secondary to primary.

**Replica set architecture:** Minimum 3 nodes (or 2 nodes + 1 arbiter). **Primary:** handles all write operations. **Secondaries:** replicate the primary's oplog (operation log) and apply changes. Can serve read operations (with configuration). **Arbiter:** votes in elections but doesn't store data (lightweight). **Election:** when the primary becomes unavailable, secondaries hold an election to choose a new primary. Uses a consensus protocol (majority required). **Read preferences:** \`primary\` (default - all reads from primary, strong consistency), \`primaryPreferred\` (primary if available, secondary fallback), \`secondary\` (reads from secondaries, eventually consistent), \`nearest\` (lowest latency node). **Write concern:** \`w: majority\` (acknowledge when written to majority of nodes), \`w: 1\` (acknowledge when written to primary only). Higher write concern = stronger durability but slower writes. **Read concern:** \`local\` (might return uncommitted data), \`majority\` (only committed data), \`linearizable\` (strongest, highest latency). **Oplog:** a capped collection that records all operations. Secondaries tail the oplog and apply changes asynchronously. Oplog size should be sufficient for your maintenance window (default: 5% of free disk space, minimum 1 hour of operations). **Best practice:** use 3-node replica sets (or 5 for higher availability). Place nodes in different availability zones. Use \`w: majority\` for critical data. Use \`readPreference: secondary\` for reporting/analytics queries. Monitor replication lag (if lag grows, secondaries can't keep up). Perform regular backups from secondaries (not primary). Use hidden secondaries for backups and analytics (not eligible for elections, invisible to clients). Use delayed secondaries for point-in-time recovery (lag by 1 hour to recover from accidental operations). Upgrade nodes one at a time (rolling upgrade). Test failover scenarios. Use MongoDB Ops Manager or Atlas for replica set management.`,
    codeExplanation: `This code shows **MongoDB replica set configuration** with the Node.js driver. **Connection string:** \`mongodb://host1:27017,host2:27017,host3:27017/mydb?replicaSet=rs0\` specifies multiple hosts and the replica set name. The driver automatically detects the primary and handles failover. **Read preference:** \`readPreference: 'secondary'\` routes reads to secondaries (reduces primary load). **Write concern:** \`w: 'majority'\` waits for acknowledgment from the majority of replica set members before resolving. \`j: true\` waits for the write to be written to the journal (durability). **Read concern:** \`readConcern: { level: 'majority' }\` only returns data that has been committed by the majority (stronger consistency). **Monitoring replication status:** \`rs.status()\` shows the replica set state (primary, secondary, arbiter), which member is primary, replication lag. \`rs.printReplicationInfo()\` shows oplog status. **rs.conf()** returns the replica set configuration. **Connection monitoring:** the driver emits events for server changes, topology changes, and heartbeats. Monitor these for alerting on replica set state changes. **Failover behavior:** when the primary goes down, the driver detects the loss, triggers an election, waits for a new primary, and then starts routing writes to it. There is a brief period (typically 5-60 seconds) where writes may fail or be retried. \`retryWrites: true\` (default) automatically retries write operations once if they fail due to a primary election. **Hiding a secondary for backups:** \`rs.add({ host: 'host4:27017', hidden: true, priority: 0 })\` - hidden secondaries can't become primary and are invisible to clients. Use for backups, reporting, and analytics. **Delayed secondary:** \`rs.add({ host: 'host5:27017', slaveDelay: 3600, priority: 0, hidden: true })\` - delayed by 1 hour, useful for point-in-time recovery from accidental operations.**`
  },
  'redis-basics': {
    explanation: `**Redis** is an in-memory data structure store used as a database, cache, and message broker. It's known for its exceptional speed (sub-millisecond response times) because all data is stored in RAM. Redis supports various data structures: strings, hashes, lists, sets, sorted sets, bitmaps, hyperloglogs, geospatial indexes, and streams. It's a critical component for building high-performance applications.

**Key features:** **In-memory storage** - all data in RAM, persists to disk via snapshots (RDB) or append-only file (AOF). **Data structures** - strings (caching, counters), hashes (objects), lists (queues), sets (uniqueness), sorted sets (leaderboards, rate limiting), streams (event sourcing), hyperloglogs (cardinality estimation), bitmaps (feature flags). **Atomic operations** - operations like \`INCR\`, \`DECR\`, \`GETSET\` are atomic. **TTL (Time-To-Live)** - auto-expire keys. **Pub/Sub** - publish/subscribe messaging. **Transactions** - \`MULTI\`, \`EXEC\`, \`WATCH\` for optimistic locking. **Lua scripting** - run custom scripts atomically. **Redis Cluster** - horizontal scaling with automatic sharding. **Sentinel** - high availability with automatic failover. **Persistence options:** RDB (point-in-time snapshots), AOF (append-only log of operations), or both. AOF is more durable but slower. For caching (data can be regenerated), RDB or no persistence is fine. **Best practice:** use Redis for caching, session storage, rate limiting, real-time leaderboards, message queues, and pub/sub. Don't use Redis for primary data storage (data loss risk if not persisted properly). Set TTL for cached data. Use connection pooling (ioredis supports it). Use appropriate data structures (not just strings for everything). Monitor memory usage. Use Redis Cluster or Sentinel for production. Use TLS for production connections. Use Redis for hot data (frequently accessed) - not for cold storage. Use appropriate eviction policies (LRU, LFU, TTL) when memory is full. Use SCAN instead of KEYS for iterating over keys (KEYS blocks the event loop).`,
    codeExplanation: `This code shows **Redis operations with ioredis**. \`new Redis()\` connects to localhost:6379. Connection configuration includes host, port, password, TLS options, retry strategy (exponential backoff), and lazyConnect (don't connect until first command). **String operations:** \`set\` with \`EX\` (TTL in seconds), \`get\`, \`incr\` (atomic increment). **Hash operations:** \`hset\` stores an object, \`hgetall\` retrieves all fields, \`hincrby\` atomically increments a hash field. **List operations:** \`lpush\` adds to head, \`rpop\` removes from tail - useful for queues. \`llen\` returns list length. **Set operations:** \`sadd\` adds members, \`smembers\` returns all, \`sismember\` checks membership - useful for tracking unique items. **Sorted set operations:** \`zadd\` adds with score, \`zrevrange\` returns members ordered by score descending, \`zincrby\` increments a member's score - perfect for leaderboards. **TTL:** \`ttl\` returns remaining time-to-live in seconds. **Error handling:** Redis connection errors are emitted as events. Implement exponential backoff in retry strategy. Handle \`maxRetriesPerRequest\` exceeded gracefully. **Persistence config in redis.conf:** \`save 900 1\` snapshot every 15 min if at least 1 key changed. \`appendonly yes\` enables AOF. \`appendfsync everysec\` balances durability and performance. **Use Redis for:** caching API responses (set TTL), storing user sessions (with TTL), rate limiting (INCR + EXPIRE), real-time leaderboards (sorted sets), job queues (lists), pub/sub for real-time events (websocket broadcasting), distributed locks (SET NX EX). Redis excels at operations that need to complete in milliseconds. Use it as a complement to your primary database, not a replacement for it.**`
  },
  'caching-strategies': {
    explanation: `**Caching strategies** determine how you store and retrieve cached data. The right strategy depends on your data access patterns, how frequently data changes, and your tolerance for stale data. Redis is the most common caching solution, but in-memory caches (node-cache) work for single-server setups.

**Cache-Aside (Lazy Loading):** Application checks cache first. On cache miss, loads from database, stores in cache, returns. Cache entries are evicted when stale. **Pros:** only caches what's requested, resilient to cache failures. **Cons:** cache miss penalty (first request is slow), stale data until eviction. **Read-Through:** Cache layer automatically loads from database on miss (application doesn't know about the database). **Write-Through:** Data is written to cache first, then synchronously to database. **Pros:** cache is always up-to-date, no stale reads. **Cons:** slower writes, increased write latency. **Write-Behind:** Data is written to cache, then asynchronously written to database. **Pros:** fast writes, reduces database write load. **Cons:** data loss risk if cache fails before database write. **Cache Aside with Write-Through for updates:** reads use cache-aside, writes update cache and database simultaneously. This is the most common and practical approach. **Eviction policies (when memory is full):** **LRU** (Least Recently Used - evicts oldest accessed item), **LFU** (Least Frequently Used), **TTL** (evicts based on expiration time), **FIFO** (First In, First Out). **Cache invalidation strategies:** **TTL-based** (set expiration time), **Event-driven** (invalidate cache when data changes), **Version-based** (invalidate when version changes). **Best practice:** use cache-aside as the default. Set appropriate TTLs (shorter for frequently-changing data, longer for stable data). Use cache keys that include relevant entity information (user ID, resource type). Implement cache warming for critical data (pre-populate on application start). Monitor cache hit rate (aim for >90%). Use distributed caching (Redis) for multi-server deployments. Handle cache failures gracefully (application should work without cache). Avoid cache avalanche (many keys expiring simultaneously - add random jitter to TTLs). Avoid cache stampede (many requests for the same expired key simultaneously - use mutex locks). Use Redis Cluster for large caches. Use serialization efficiently (MessagePack for binary, JSON for human-readable).`,
    codeExplanation: `This code shows **caching strategies with Redis**. **Cache-Aside (Lazy Loading):** the \`getUser\` function checks cache first. If found (\`get\` returns data), parse and return (cache hit). If not found, query database, store in cache with TTL (60 seconds), return. This is the most common pattern. **Invalidation on update:** when a user is updated, \`updateUser\` updates the database and then deletes the stale cache entry (\`del\`). The next read will miss the cache and fetch fresh data. **Cache key convention:** \`user:{id}\`, \`posts:list\`, \`post:{id}\`. Namespace by entity type. **Avoiding cache stampede:** \`setAsync\` with \`NX\` (set if not exists) creates a mutex lock. If the lock is acquired, do the expensive computation and cache the result. If not acquired, wait briefly (\`await new Promise(r => setTimeout(r, 100))\`) and retry the cache. This prevents multiple concurrent requests from all hitting the database when a cache key expires. **Cache warming:** on application startup, pre-populate cache for the most popular users (\`User.findMany({ take: 100, orderBy: { loginCount: 'desc' } })\`). This prevents the first requests from experiencing cold cache. **TTL with jitter:** \`Math.floor(Math.random() * 60) + 60\` adds 0-60 seconds of random jitter to a 60-second base TTL. This prevents many keys from expiring simultaneously (cache avalanche). **Monitoring:** track \`cacheHits\` and \`cacheMisses\` counters. Calculate hit rate: \`hits / (hits + misses) * 100\`. If below 90%, investigate - TTL might be too short, cache keys might not be used, or eviction is too aggressive. **Use Indexes or materialized views in PostgreSQL for complex queries instead of caching their results.** Cache simple key-value lookups (user by ID, settings). For complex queries, cache the rendered result or use database query optimization instead. The most effective caches are those with a high hit rate and low invalidation frequency.**`
  },
  'redis-pub-sub': {
    explanation: `**Redis Pub/Sub** (Publish/Subscribe) is a messaging pattern where senders (publishers) send messages to channels without knowing who the receivers (subscribers) are. Subscribers express interest in one or more channels and receive messages asynchronously. Redis Pub/Sub is simple, fast, and supports many-to-many communication.

**How it works:** \`PUBLISH channel message\` sends a message to a channel. \`SUBSCRIBE channel [channel ...]\` receives messages from channels. Redis distributes the message to all active subscribers. Messages are fire-and-forget - if there are no subscribers, the message is lost. **Channels:** named message streams. Convention: \`entity.event\` (\`user.created\`, \`order.completed\`). **Pattern subscriptions:** \`PSUBSCRIBE user.*\` subscribes to all channels matching the pattern. **Use cases:** real-time notifications, chat applications, broadcasting events to multiple servers, live updates (sports scores, stock prices). **Limitations:** messages are not persisted (if a subscriber is offline, messages are lost). No message acknowledgment. No message queuing (all subscribers get all messages). For persistent messaging, use Redis Streams or a message queue (RabbitMQ, Kafka). **Redis Pub/Sub in practice:** In Node.js, the ioredis library creates a separate connection for subscribing (subscriber connections can't execute other commands). This is because Redis connections in subscribe mode are blocked from regular commands. **Pattern:** create two Redis connections - one for publishing, one for subscribing. The subscriber connection enters subscribe mode and listens for messages. **Best practice:** use a separate Redis connection for subscribing. Use pattern subscriptions for flexibility. Handle reconnection gracefully (subscribers need to re-subscribe after disconnect). Use Redis Streams instead of Pub/Sub if you need message persistence, acknowledgment, or consumer groups. For server-to-server communication within the same infrastructure, Redis Pub/Sub is excellent. For client-facing real-time features, use WebSocket and broadcast via Redis Pub/Sub to all server instances (which then push to their connected WebSocket clients). Use descriptive channel names. Monitor subscriber counts. Implement timeout/ping mechanisms for stale subscriptions. For production, use Redis Sentinel or Cluster for high availability. Avoid very large messages (Pub/Sub is not optimized for data transfer - use it for notifications about data, not the data itself).`,
    codeExplanation: `This code shows **Redis Pub/Sub implementation** in Node.js. Two connections are created: \`pub\` (for publishing) and \`sub\` (for subscribing). The subscriber connection can only be in subscribe mode - it can't execute regular Redis commands. **Subscribing:** \`sub.subscribe('order.created', 'order.completed')\` subscribes to specific channels. \`sub.on('message', (channel, message) => ...)\` handles incoming messages. For pattern subscriptions: \`sub.psubscribe('order.*')\` subscribes to all order events. \`sub.on('pmessage', (pattern, channel, message) => ...)\` handles pattern-matched messages. **Publishing:** \`pub.publish('order.created', JSON.stringify(orderData))\` publishes a message. All subscribers of that channel receive it. **WebSocket integration:** the \`setupWebSocket\` function creates a WebSocket server. When a Redis message arrives on \`order.created\`, it broadcasts to all connected WebSocket clients. This allows real-time updates to reach browser clients. \`wss.clients.forEach(client => { if (client.readyState === WebSocket.OPEN) client.send(JSON.stringify(notification)) })\`. **Chat application:** Redis Pub/Sub is perfect for chat. When one server instance receives a chat message from a WebSocket client, it publishes to Redis, all other instances receive the notification and broadcast to their clients. This enables real-time multi-server chat. **Limitations awareness:** if a subscriber disconnects and reconnects, it won't receive messages sent during the disconnect period. For critical messages, use Redis Streams (which persist messages) or combine Pub/Sub with a persistent store. **Pattern subscriptions** (\`psubscribe\`) are powerful but be careful with overlapping patterns (message deduplication). **Production setup:** use a dedicated Redis instance for Pub/Sub (separate from caching) to avoid performance interference. Use Redis Sentinel for high availability. Monitor subscriber counts and message rates. Implement health checks for subscription connections. **Redis Pub/Sub is a building block for real-time features** - combine with WebSockets for browser clients, with database listeners for data change notifications, and with service meshes for inter-service communication.**`
  },
  'redis-sessions': {
    explanation: `**Redis session storage** leverages Redis's in-memory speed and TTL capabilities to store web application sessions. In traditional applications, sessions are stored on the server (memory or database). With Redis, sessions are stored in a fast, shared cache that all server instances can access - enabling horizontal scaling without sticky sessions.

**Why Redis for sessions:** Sessions need fast reads (every request loads the session). They're write-heavy (session data updates frequently). They have a natural TTL (sessions expire after inactivity). Redis excels at all three: sub-millisecond reads, fast writes, and automatic key expiration. **Implementation with express-session:** \`npm install express-session connect-redis\`. Connect the Redis store to express-session. Sessions are automatically stored in Redis with the session ID as the key. **Session data structure:** typically a Redis hash or string with JSON. Includes user ID, roles, preferences, cart data, flash messages. **TTL for sessions:** set the session timeout (typically 24 hours of inactivity). Redis automatically removes expired sessions. Use rolling sessions (reset TTL on each request) so active sessions don't expire. **Session security:** store only non-sensitive data in sessions (preferences, user ID). Don't store passwords, credit cards, or tokens in sessions (use httpOnly cookies for tokens). Sign the session cookie to prevent tampering. **Scaling with Redis sessions:** without Redis, each server instance has its own session store - requests must go to the same server (sticky sessions). With Redis, any server can handle any request because the session is in a shared store. This enables horizontal scaling and zero-downtime deployments. **Best practice:** use Redis for production sessions. Set appropriate TTL (24-72 hours). Use rolling TTL (touch on each request). Use signed cookies with a secret. Use httpOnly, secure, sameSite cookies. Keep session data small (store only IDs, not full objects). Implement session revocation for security (blacklist or user version). Monitor session count and memory usage. Use Redis Sentinel/Cluster for high availability. Fall back gracefully if Redis is unavailable (in-memory store as fallback). For JWT-based auth, you don't need server-side sessions (tokens are self-contained) - but Redis is still useful for token blacklisting.`,
    codeExplanation: `This code shows **Redis session storage with express-session**. **RedisStore** connects express-session to Redis. Configuration: \`client\` (ioredis instance), \`prefix: 'sess:'\` (key namespace), \`ttl: 86400\` (24 hours default). Express-session config: \`secret\` (signs the cookie), \`resave: false\` (don't save if unchanged), \`saveUninitialized: false\` (don't create session until stored), \`cookie: { secure: true, httpOnly: true, maxAge: 24 * 60 * 60 * 1000, sameSite: 'strict' }\`. **Using sessions in routes:** \`req.session.userId = user.id\` stores user ID in session. \`req.session.views = (req.session.views || 0) + 1\` tracks page views per session. \`req.session.save()\` explicitly saves (optional - express-session auto-saves on response end). **Destroying sessions:** \`req.session.destroy()\` removes session from Redis and clears the cookie. **JWT blacklist:** even with JWT auth, you may need to revoke tokens before expiry. Store revoked JWT IDs (\`jti\`) in Redis with TTL matching the token's remaining lifespan. \`SET blacklist:{jti} true EX \${remainingSeconds}\`. Check in auth middleware: \`const isBlacklisted = await redis.get(\`blacklist:\${decoded.jti}\`)\`. **Rolling TTL:** \`rolling: true\` option (only available in some express-session stores) resets the TTL on every request, so active sessions don't expire. **Session revocation:** to revoke all sessions for a user, increment a \`user:\${userId}:tokenVersion\` counter stored in Redis. Each session stores the token version. In auth middleware, compare the version and reject if outdated. **Monitoring:** \`INFO keyspace\` shows Redis memory usage. \`SCAN 0 MATCH sess:* COUNT 1000\` iterates over session keys. \`redis-cli -h host -p port --bigkeys\` finds large keys. **Redis sessions enable stateless application servers** - you can scale horizontally without sticky sessions, do rolling deployments, and handle server failures seamlessly. Store only session metadata in Redis (user ID, roles). Fetch full user data from the primary database when needed. This keeps sessions small and fast.**`
  },
  'redis-cluster': {
    explanation: `**Redis Cluster** provides a way to run Redis across multiple nodes, automatically sharding data across them. It offers horizontal scalability, high availability, and automatic failover. Redis Cluster is the production-ready solution for handling large datasets that exceed a single server's memory capacity.

**Architecture:** A Redis Cluster typically has at least 3 master nodes (shards) and 3 replica nodes (one per master). Data is automatically split across masters using hash slots (16384 slots total). Each key is assigned to a slot using the CRC16 hash algorithm. Masters handle read/write for their slots. Replicas replicate masters and provide read scaling and failover. **Sharding:** \`CLUSTER KEYSLOT mykey\` shows which slot a key maps to. Keys are distributed based on the hash slot. For multi-key operations, all keys must be in the same slot (use hash tags: \`{user:123}.profile\`). **Failover:** If a master fails, its replica is automatically promoted. During failover (milliseconds), some keys may be unavailable. **Client interaction:** the Redis client needs cluster support. ioredis has \`Cluster\` class. The client connects to nodes, discovers the cluster topology, and routes commands to the correct node. **Hash tags:** \`{user:123}:profile\` ensures all keys with \`{user:123}\` are in the same shard. Essential for transactions, Lua scripts, and multi-key operations. **Resharding:** add/remove nodes without downtime. Slots are migrated between nodes. Cluster continues to serve requests during migration. **Limitations:** multi-key operations (MGET, transactions, Lua scripts) only work on keys in the same slot. Cross-slot joins aren't possible. Scan operations need to scan all nodes. **Best practice:** use Redis Cluster when your data exceeds a single node's memory (typically > 25GB). For smaller datasets, use Sentinel (simpler, supports all operations). Design keys with hash tags for related data. Use connection pooling with cluster awareness. Monitor cluster health (nodes, slots, failover status). Plan for enough replicas (at least one per master). Use consistent hashing for client-side sharding if full cluster is overkill. Set proper timeouts for cluster operations. Use TLS for cluster connections. Upgrade nodes one at a time (rolling upgrade). Test failover scenarios in staging. Use Redis Enterprise or AWS ElastiCache for managed cluster operations. Use Redis on Flash for cost-effective large datasets (RAM + SSD). Monitor memory fragmentation and eviction rates. Use \`redis-cli --cluster check\` for cluster health. Keep cluster nodes in the same data center (low latency). For multi-data center, use active-passive with replication.`,
    codeImplementation: `This section would show Redis Cluster configuration and client setup in Node.js. The ioredis Cluster class connects to multiple nodes and discovers the full cluster topology automatically. Hash tags like {user:123} ensure related keys are on the same shard. Cluster nodes can be added/removed dynamically. Read replicas can serve read queries with scaleReads option. Default behavior is to route writes to masters and allow reads from replicas. Cluster health monitoring checks node states (connected, disconnected, fail) and slot ranges. Resharding slots enables online capacity changes without downtime.`
  },
  'branching-strategies': {
    explanation: `**Git branching strategies** define how teams use branches to organize development, collaborate, and release code. A good branching strategy makes collaboration smooth, reduces conflicts, and enables continuous delivery. The most common strategies: Git Flow, GitHub Flow, and Trunk-Based Development.

**Git Flow:** Two main branches: \`main\` (production-ready) and \`develop\` (integration branch). Supporting branches: \`feature/*\`, \`release/*\`, \`hotfix/*\`. Features merge to develop. Releases branch from develop, merge to main and develop. Hotfixes branch from main, merge to main and develop. **Pros:** clear structure, good for scheduled releases. **Cons:** complex, overhead for continuous delivery. **GitHub Flow:** Single main branch. Feature branches branch from main, are merged via pull requests after review. Deploy immediately after merge. **Pros:** simple, perfect for continuous deployment. **Cons:** no release branches, harder to manage multiple concurrent releases. **GitLab Flow:** Environment branches (\`production\`, \`staging\`) in addition to main. Feature branches merge to main, then promote through environments. **Trunk-Based Development:** All developers work on short-lived branches (a few hours) and merge to main multiple times per day. Feature flags hide incomplete features. **Pros:** fast integration, less merge conflicts. **Cons:** requires discipline, feature flags management. **Best practice:** start with GitHub Flow for most projects. Use Git Flow only for projects with scheduled releases and multiple concurrent versions. Use trunk-based development for CI/CD with mature teams. Always use pull requests with code review. Keep branches short-lived. Delete branches after merging. Use branch protection rules (require PR review, status checks). Use meaningful branch names (\`feature/add-login\`, \`fix/login-error\`). Use conventional commits for clear history. Squash merge for feature branches (clean history). Rebase locally to keep linear history. Never force push to shared branches (except feature branches with your team). Use pre-commit hooks for linting and formatting. Use CI to verify all branches.`,
    codeExplanation: `This shows **Git branching workflow**. **GitHub Flow:** create branch from main -> commit changes -> push -> open PR -> code review -> merge to main -> deploy. Simple and effective for continuous deployment. **Git Flow:** more structured. develop is the integration branch. Features branch from develop, merge back to develop. When ready for release, create release branch from develop. Release is tested, merged to main (with version tag) and back to develop. Hotfix branches from main, merge to both main and develop. **Branch naming conventions:** feature/ (new features), fix/ (bug fixes), chore/ (maintenance), release/ (release preparation), hotfix/ (urgent production fixes). **PR template:** ensures quality by requiring description, screenshots, testing notes, and checklist. **Branch protection rules:** require pull request review before merging, require status checks to pass (CI), require up-to-date branch, limit force pushes, restrict branch deletion. **Merge strategies:** **Squash merge** (combines all feature branch commits into one - clean history). **Rebase merge** (rebases feature commits onto main - linear history). **Merge commit** (preserves full history - useful for collaboration branches). **Conventional commits format:** \`type(scope): description\`. types: feat, fix, chore, docs, style, refactor, perf, test. Examples: \`feat(auth): add login endpoint\`, \`fix(api): handle null user gracefully\`. This enables automatic changelog generation and semantic versioning. **Use the strategy that matches your release process.** GitHub Flow is the most common and recommended for most teams. It keeps things simple and enables rapid deployment. More complex strategies like Git Flow add overhead that's only justified when you need strict release management.**`
  },
  'git-collaboration': {
    explanation: `**Git collaboration** involves working effectively with other developers on the same codebase. Key aspects include sharing code via remotes, resolving conflicts, using pull requests for code review, and maintaining a clean project history. Good collaboration practices prevent conflicts and keep the team productive.

**Remotes:** \`origin\` is your primary remote (GitHub/GitLab). \`git remote add upstream <url>\` for forked repositories. \`git fetch\` downloads remote changes without merging. \`git pull\` = fetch + merge (use \`git pull --rebase\` for cleaner history). **Pull Requests (PRs):** propose changes, enable code review, trigger CI checks. Best practices: keep PRs small (one logical change), write clear descriptions, respond to review comments, update PR with new commits, squash before merging. **Code Review:** review for correctness, design, performance, security, and testing. Use GitHub's review features (approve, request changes, comment). Be constructive and respectful. **Merge conflicts:** occur when two branches modify the same lines. Resolve by editing conflicted files, removing conflict markers, staging, and committing. Use \`git mergetool\` for visual conflict resolution. Prevent conflicts by communicating, pulling frequently, and keeping branches short-lived. **Rebasing vs Merging:** \`git rebase main\` replays your commits on top of main (linear history). \`git merge main\` creates a merge commit (preserves branch history). Use rebase for local feature branches, merge for shared branches. **Git hooks:** pre-commit (linting, formatting), pre-push (testing), commit-msg (conventional commits). Use husky for easy hook management. **Best practice:** pull frequently (\`git pull --rebase\`). Communicate with your team about conflicting changes. Keep branches short-lived (merge within a day or two). Write meaningful commit messages. Review PRs promptly. Use draft PRs for work-in-progress. Use GitHub/GitLab project boards for tracking. Tag releases with semantic versions. Use git blame responsibly (investigate context, don't assign blame). Use git bisect to find where a bug was introduced. Use interactive rebase to clean up commits before merging. Learn beyond basic commands: reflog, stash, cherry-pick, revert. Use git aliases for common operations. Use a consistent .gitignore across the team. Use .gitattributes for consistent line endings and diff configurations. Use git-lfs for large files.`,
    codeExplanation: `This shows **Git collaboration workflows**. **Fork + PR workflow:** fork the repository on GitHub, clone your fork, add upstream remote (\`git remote add upstream <original-repo-url>\`), fetch upstream, rebase feature branch on upstream/main, push to your fork, create PR. **Rebase workflow:** fetch latest main, rebase feature branch on main (\`git rebase main\`), resolve conflicts if any (\`git add <file> && git rebase --continue\`), force push (\`git push --force-with-lease\`) - safe force push that warns if remote has new commits. **Interactive rebase:** \`git rebase -i HEAD~3\` to squash, reword, reorder, or drop the last 3 commits. \`pick\` (use commit as-is), \`reword\` (change message), \`squash\` (combine with previous), \`fixup\` (combine, discard message), \`drop\` (remove). **Merge conflict resolution:** conflicted files have <<<<<<<, =======, >>>>>>> markers. Edit to keep the correct version, remove markers, stage (\`git add\`), and continue rebase/merge. **Git bisect:** binary search to find which commit introduced a bug. \`git bisect start\`, \`git bisect good <known-good-commit>\`, \`git bisect bad\` (current is bad). Git checks out a middle commit - test it and mark \`git bisect good\` or \`git bisect bad\`. Repeat until the faulty commit is found. **Git reflog:** shows where HEAD has been. \`git reflog\` shows history of HEAD movements. \`git reset --hard HEAD@{2}\` goes back to a previous state. This is your safety net for recovering lost commits. **Stash:** \`git stash push -m "WIP: login form"\` temporarily shelves changes. \`git stash pop\` restores them. Useful when you need to switch branches without committing. **Cherry-pick:** \`git cherry-pick <commit-hash>\` applies a specific commit's changes to the current branch. Useful for selective changes. **Revert:** \`git revert <commit-hash>\` creates a new commit that undoes the specified commit. Safe for public branches (unlike reset which rewrites history). **Good collaboration is about communication and discipline** - small PRs, frequent merges, clear commits, and respectful code reviews build high-performing teams.**`
  },
  'advanced-git': {
    explanation: `**Advanced Git** commands and techniques go beyond basic add/commit/push to give you precise control over your repository history, debugging, and complex workflows. Mastering these commands makes you a Git power user who can handle any situation.

**Rebase interactive:** \`git rebase -i HEAD~5\` lets you squash, reword, reorder, edit, or drop commits. Essential for cleaning up history before merging. **Rerere (Reuse Recorded Resolution):** \`git config --global rerere.enabled true\` - Git remembers how you resolved conflicts and auto-resolves them next time. **Worktrees:** \`git worktree add ../project-feature feature-branch\` - check out multiple branches simultaneously in different directories. No need to stash or commit before switching. **Submodules:** embed one repository inside another. \`git submodule add <repo>\`. Useful for shared libraries but adds complexity. **Bisect run:** \`git bisect run npm test\` - automate bisect with a command that returns 0 (good) or non-zero (bad). **Filter-branch / filter-repo:** rewrite history - change author info, remove files from history, split repositories. \`git filter-branch --tree-filter 'rm -f passwords.txt' HEAD\`. **Advanced merging:** \`git merge --no-ff\` (force merge commit), \`git merge --squash\` (combine all changes without merge commit), \`git merge -s ours\` (merge but discard their changes). **Patch mode:** \`git add -p\` interactively stage parts of files (hunks). \`git checkout -p\` selectively discard changes. **Notes:** \`git notes add -m "Reviewed by Alice"\` attaches metadata to commits without changing the commit SHA. **Replace:** \`git replace --graft <commit> <parent>\` replace a commit's parents (useful for fixing mistakes without rebasing). **Best practice:** use interactive rebase to clean up feature branches before merging. Use rerere for recurring conflict patterns. Use worktrees for simultaneous work on multiple branches. Use bisect to systematically find bugs. Use add -p for precise, clean commits (separate formatting from logic changes). Use reflog as a safety net (it records all HEAD movements for 90 days). Use stash with messages (\`git stash save "WIP: feature X"\`). Use \`diff\` and \`log\` with powerful options: \`--word-diff\`, \`--patience\`, \`--follow\`, \`-G<regex>\`. Use \`blame\` with \`-w\` (ignore whitespace) and \`-C\` (detect moved lines). Use \`shortlog\` for release notes. Use \`describe\` for human-readable commit names. Use \`clean -fd\` to remove untracked files. Use \`gc\` (garbage collect) to optimize repository size.`,
    codeExplanation: `This shows **advanced Git commands**. **Interactive rebase (\`-i\`):** pick (use commit), reword (edit message), edit (modify content), squash (combine with previous), fixup (combine, discard message), exec (run command), break (stop for editing), drop (remove). **Worktree:** \`git worktree add ../hotfix hotfix-branch\` creates a new working directory with the hotfix branch checked out. You can work on both branches simultaneously without switching. **Rerere:** after enabling, Git records conflict resolutions. Next time the same conflict occurs (e.g., after rebase), Git automatically applies the previous resolution. **Bisect automated:** \`git bisect start HEAD v1.0\` (current is bad, v1.0 is good). \`git bisect run npm test\` automatically runs tests on each commit until it finds the first failing commit. **Add -p:** \`git add -p file.js\` shows each change (hunk) and asks: y (stage), n (skip), s (split further), e (edit manually), q (quit). Great for splitting unrelated changes into separate commits. **Filter-branch:** \`git filter-branch --commit-filter 'GIT_AUTHOR_NAME="$NEW_NAME"; GIT_AUTHOR_EMAIL="$NEW_EMAIL"; git commit-tree "$@"'\` rewrites author info for all commits. This rewrites history - only do on branches that haven't been pushed. Use \`git filter-repo\` (suggested replacement, faster and safer). **Notes:** \`git notes add -m "Approved in code review #42"\` adds a note to HEAD. Notes are stored in refs/notes/commits and push separately. **Replace:** \`git replace --graft OLD_COMMIT_HASH NEW_PARENT_HASH\` replaces a commit's parent. Useful after a bad merge was pushed. The replacement is local only - use \`git push origin refs/replace/*\` to share. **Reflog:** \`git reflog\` shows all HEAD movements. \`git reset --hard HEAD@{5}\` goes back to the position 5 moves ago. This is your safety net - most "lost" commits can be recovered via reflog within 90 days. **These advanced commands give you surgical control over your Git history.** Use them with caution, especially commands that rewrite history on shared branches. Always communicate history changes with your team. Use force-with-lease instead of force push for safety. Master the reflog - it's your best friend for recovery.**`
  },
  'gitops-automation': {
    explanation: `**GitOps** is an operational model where Git is the single source of truth for declarative infrastructure and application configuration. Changes are made via pull requests, and an automated process (GitOps operator) synchronizes the actual system state with the desired state in Git. GitOps is commonly used with Kubernetes (Argo CD, Flux).

**Core principles:** **Declarative configuration** - the entire system is described in a Git repository. **Version controlled** - all changes are tracked, auditable, and revertible. **Approved changes** - changes go through PR review before applying. **Automated delivery** - an operator (Argo CD, Flux) continuously reconciles actual state with desired state. **Drift detection** - the operator detects and corrects manual changes (drift). **Benefits:** improved security (PR-based changes, no direct cluster access), audit trail (Git history), easy rollback (revert PR), developer productivity (familiar Git workflow), disaster recovery (recreate entire system from Git). **GitOps vs CI/CD:** CI/CD pipelines build and test code. GitOps operators deploy and manage infrastructure. They complement each other: CI builds artifacts, GitOps deploys them. **Argo CD:** the most popular GitOps tool for Kubernetes. It watches a Git repository and syncs the cluster state to match. Supports multi-cluster, SSO, web UI, and automated sync policies. **Flux:** another popular GitOps tool, lighter weight, integrates tightly with the Kubernetes ecosystem. **Best practice:** separate application config from infrastructure config (different repos or directories). Use Kustomize or Helm for templating. Use pull-based deployment (operator pulls from Git). Implement proper RBAC (who can approve changes). Add automated testing in CI before merging. Use signed commits for integrity. Monitor drift detection alerts. Use progressive delivery (canary, blue/green) with Flagger or Argo Rollouts. Keep secrets secure (Sealed Secrets, External Secrets Operator, Vault). Document the recovery process. Use Git as the source of truth for everything - configuration, documentation, and runbooks. Test GitOps workflows in a staging environment first. Use PR preview environments for testing changes. Implement proper backup for the Git repository itself.`,
    codeExplanation: `This shows **GitOps with Argo CD**. The application YAML defines a "Guestbook" app with source pointing to a Git repository and path. \`syncPolicy\` enables automatic sync (changes in Git automatically apply to the cluster) and self-healing (reverts manual changes). PR-based workflow: make changes in a feature branch, open PR, review and merge to main, Argo CD detects the change and syncs the cluster. **Helm/Kustomize integration:** Argo CD supports Helm charts and Kustomize overlays. Use \`helm.releaseName\` and \`helm.values\` for Helm. Use \`kustomize.path\` for Kustomize. **Secrets management:** Sealed Secrets encrypts secrets so they can be stored in Git. The controller decrypts them in the cluster. External Secrets Operator pulls secrets from external stores (AWS Secrets Manager, Vault). **CI/CD pipeline:** GitHub Actions build and push Docker image, update the Kubernetes manifests in the GitOps repo with the new image tag. Argo CD detects the manifest change and deploys the new image. **Rollback:** to rollback, revert the Git commit and push. Argo CD syncs the cluster back to the previous state. \`PrunePropagationPolicy: foreground\` ensures resources are cleaned up properly. **Sync options:** \`Validate: true\` validates manifests before applying. \`PruneLast: true\` prunes resources last (safe default). \`RespectIgnoreDifferences: true\` allows fields to differ between Git and cluster (e.g., autoscaler updates). **Monitoring:** Argo CD web UI shows sync status, health, and diff between Git and cluster. Set up alerts for OutOfSync and Degraded states. Use notifications for sync events. **GitOps is the standard for Kubernetes deployment** - it provides security, auditability, and reliability. Start with a simple setup (single repo, single cluster) and expand as needed. The key is the declarative approach - if you can describe your infrastructure in Git, you can manage it with GitOps.**`
  },
  'dockerfile-best-practices': {
    explanation: `**Dockerfile best practices** help you create efficient, secure, and maintainable Docker images. A well-optimized Dockerfile produces smaller images, faster builds, and more secure containers. Since Docker images are built in layers, every instruction matters.

**Key practices:** **Use official base images** with specific tags (\`node:18-alpine\` not \`node:latest\`). Alpine-based images are much smaller (5MB vs 150MB for full distro). **Multi-stage builds** - separate build dependencies from runtime. First stage installs build tools and compiles; second stage copies only the compiled artifacts. This dramatically reduces final image size. **Order layers by change frequency** - least changing layers first (system dependencies, then app dependencies, then app code). This maximizes Docker layer caching, speeding up builds. **Combine RUN commands** (\`apt-get update && apt-get install -y pkg1 pkg2 && rm -rf /var/lib/apt/lists/*\`) to reduce layers and clean up in the same layer. **Don't run as root** - create a non-root user (\`USER node\`). **Use .dockerignore** to exclude node_modules, .git, and other unnecessary files from the build context. **Cache package downloads** - copy package.json and install dependencies before copying source code. This caches the dependency layer (npm install only reruns when package.json changes). **Minimize layers** - each RUN, COPY, ADD creates a layer. Combine related commands. **Use COPY over ADD** (COPY is simpler and more predictable). **Specify EXPOSE** only for documentation. **Use HEALTHCHECK** to let Docker/orchestrators know container health. **Use labels** for metadata (maintainer, version, description). **Security:** scan images for vulnerabilities (trivy, snyk). Use distroless or scratch base images when possible. Remove build tools and package managers from final image. **Best practice checklist:** specific base image tag, multi-stage build, non-root user, .dockerignore, proper layer ordering, combined RUN commands, healthcheck, labels, vulnerability scanning, minimal final image size. Aim for final images under 200MB (most Node.js apps can be under 150MB with Alpine).`,
    codeExplanation: `This Dockerfile shows **best practices**. **Stage 1 (build):** \`FROM node:18-alpine AS builder\` - Alpine base (small). Copy package.json and lock files first, install dependencies, then copy source code and build. This layers caching: if only source code changes, the npm install layer is cached. **Stage 2 (production):** \`FROM node:18-alpine\` - fresh base, no build tools. \`RUN addgroup -g 1001 -S nodejs && adduser -S nodejs -u 1001\` creates a non-root user. Copy only the built artifacts and production dependencies (\`COPY --from=builder --chown=nodejs:nodejs ...\`). \`USER nodejs\` switches to non-root. \`HEALTHCHECK --interval=30s --timeout=3s --start-period=5s --retries=3 CMD wget --no-verbose --tries=1 --spider http://localhost:3000/health || exit 1\` checks container health. \`LABEL\` adds metadata. \`CMD ["node", "dist/server.js"]\`. **.dockerignore:** excludes node_modules, .git, .env, Dockerfile, and other unnecessary files from the build context (speeds up COPY transfers). **Image size comparison:** full node image (~900MB), node:slim (~150MB), node:alpine (~110MB with app), distroless node (~100MB), scratch (if you compile to binary, ~20MB). **For Node.js, Alpine is the sweet spot** - good tooling compatibility, small size, familiar package manager (apk). Distroless is even more secure but harder to debug (no shell). **Vulnerability scanning:** \`docker scan myapp:latest\` (uses Snyk), \`trivy image myapp:latest\`. Fix vulnerabilities by updating base images and dependencies. **Multi-stage builds are the single most impactful optimization** - they keep the final image clean of build tools, SDKs, and intermediate artifacts. The difference between a single-stage and multi-stage build for a typical Node.js app is 500MB+ vs 150MB.**`
  },
  'docker-compose': {
    explanation: `**Docker Compose** defines and runs multi-container Docker applications using a YAML file. With one command (\`docker compose up\`), you start all services (web server, database, cache, queue) defined in \`compose.yaml\` (or \`docker-compose.yml\`). Compose is ideal for development environments and simple production deployments.

**Key concepts:** **Services** - each containerized component (web, db, redis). **Networks** - services communicate over internal networks. **Volumes** - persist data (database data) and enable live code reloading (bind mounts). **Environment variables** - configured per service, can use \`.env\` file. **Ports** - expose container ports to the host (\`"3000:3000"\`). **Depends_on** - control startup order (but doesn't wait for readiness). **Healthchecks** - ensure service is ready before dependent services start. **Profiles** - enable/disable services based on profile (\`docker compose --profile monitoring up\`). **Extensions** - use \`x-\` prefixed keys for shared configuration. **Production considerations:** Compose can be used in production for small setups. For larger deployments, use Docker Swarm or Kubernetes. Use \`docker compose -f compose.yml -f compose.prod.yml\` to override development settings for production. **Development vs Production:** In development, use bind mounts for hot-reload, expose debug ports, set NODE_ENV=development. In production, don't use bind mounts (code is in the image), use named volumes for databases, set NODE_ENV=production, use restart: always, use resource limits. **Best practice:** define all services in compose.yaml. Use named volumes for persistent data. Use healthchecks to ensure services are ready. Use \`.env\` file for environment-specific variables (don't commit it). Use \`extends\` or multiple compose files for sharing config. Use \`profiles\` for optional services (monitoring, admin tools). Use \`restart: unless-stopped\` for production. Limit container resources (\`deploy.resources.limits\`). Use \`networks\` to isolate services. Use \`init: true\` for proper signal handling. Test your compose setup with \`docker compose config\` (validates the file). Use \`docker compose logs -f\` to view logs from all services. Use \`docker compose down -v\` to clean up (including volumes). Never commit .env files or passwords in compose files. Use secrets management for production.`,
    codeExplanation: `This \`compose.yaml\` defines a **fullstack application with multiple services**. **app service:** builds from the current directory (\`build: .\`), uses environment variables (from the file), depends on db and redis, maps port 3000, uses a bind mount for hot-reload (.\`\${PWD:-.}:/app\`), sets NODE_ENV. **db service:** uses PostgreSQL image, named volume for persistence (\`pgdata:/var/lib/postgresql/data\`), healthcheck to ensure it's ready (pg_isready), environment variables for credentials, port mapping for external access. **redis service:** uses Redis image, healthcheck (redis-cli ping), named volume for data. **Services know each other by service name** - the app connects to \`db:5432\` and \`redis:6379\` (Docker DNS resolves service names). **Profiles:** \`monitoring\` profile enables Prometheus and Grafana for observability. Use \`docker compose --profile monitoring up -d\` to include monitoring. **Resource limits:** \`deploy.resources.limits.cpus: '1.0'\` limits CPU to 1 core. \`memory: 512M\` limits memory to 512MB. **Networks:** an internal network (\`app-network\`) connects all services. \`driver: bridge\` is default for single-host. **Named volumes:** \`pgdata:\` and \`redis-data:\` are defined at the top level and mounted into containers. These persist across container restarts. **Custom healthcheck for app:** \`test: ["CMD", "wget", "--spider", "http://localhost:3000/health"]\` tells Compose when the app is ready. **Depends_on with healthcheck:** \`app.depends_on.db.condition: service_healthy\` waits for the db's healthcheck to pass before starting the app. **Docker Compose makes local development simple** - one command to start everything, consistent environment across the team, easy cleanup. For production, consider Kubernetes or Docker Swarm for orchestration, scaling, and self-healing.**`
  },
  'docker-networking': {
    explanation: `**Docker networking** enables communication between containers, between containers and the host, and between containers and external networks. Docker provides several network drivers for different use cases. Understanding networking is essential for multi-container applications.

**Network drivers:** **Bridge** (default) - containers on the same bridge network can communicate. Containers get IP addresses on the private bridge network. Good for standalone containers. **Host** - container shares the host's network stack (no network isolation). Faster but less secure. Use for performance-critical applications or when many ports need exposure. **Overlay** - connects containers across multiple Docker hosts (Docker Swarm). Essential for multi-host deployments. **Macvlan** - assign MAC addresses to containers, making them appear as physical devices on the network. Use for legacy applications that need direct network access. **None** - no network access. **DNS resolution:** Docker provides built-in DNS. Containers can reach other containers by service name (on user-defined bridge networks) or container name. This is how Docker Compose services resolve each other. **Port mapping:** \`-p 8080:3000\` maps host port 8080 to container port 3000. Only one container can bind to a host port. **Exposing ports:** \`EXPOSE 3000\` in Dockerfile is documentation only - doesn't publish the port. \`-p\` or \`ports:\` in compose actually publishes. **Network security:** default bridge network doesn't provide DNS-based service discovery. Use custom user-defined bridge networks for isolation and DNS. Consider network policies in Docker Swarm or Kubernetes for restricting traffic between services. **Best practice:** create user-defined bridge networks instead of using the default bridge. Use service names (Docker Compose) or container names for DNS resolution. Don't use host networking unless necessary. Isolate different application tiers (frontend, backend, database) on separate networks when possible. Use network policies to restrict traffic (only allow necessary connections). Use \`internal: true\` to prevent external access. Monitor network traffic for anomalies. For production, use overlay networks with Docker Swarm or Kubernetes CNI plugins. Use Docker's network troubleshooting tools: \`docker network inspect\`, \`docker exec container ping other\`, \`docker exec container curl other:port\`.`,
    codeExplanation: `This shows **Docker networking configuration**. **User-defined bridge network:** \`docker network create --driver bridge --subnet=172.20.0.0/16 --ip-range=172.20.240.0/20 app-network\` creates a custom bridge network with specific subnet. Containers on this network can resolve each other by container name. **Docker Compose networks:** \`networks:\` defines multiple networks. The app service is on both frontend and backend networks. The web service is only on frontend. The db service is only on backend. This isolates the database from the frontend. **Network configuration:** \`ipv4_address\` assigns a static IP (use when you need predictable IPs). \`aliases\` adds network aliases (service is reachable by multiple names). \`dns:\` custom DNS servers. **Connecting containers:** \`docker network connect app-network container-name\` attaches a running container to an additional network. \`docker network disconnect app-network container-name\` removes. **Troubleshooting commands:** \`docker network ls\` lists networks. \`docker network inspect app-network\` shows connected containers and their IPs. \`docker exec app ping db\` tests DNS resolution (if on the same network). \`docker exec app curl db:5432\` tests connectivity. **Network isolation:** containers on different networks can't communicate unless explicitly connected to both. \`internal: true\` on a network prevents external access (containers can't reach the internet). **Embedded DNS:** user-defined bridge networks have built-in DNS resolution. Containers resolve each other by container name or service name. The default bridge (\`bridge\`) does NOT have DNS resolution - you must use \`--link\` (deprecated) or IP addresses. **Always use user-defined bridge networks for multi-container applications** - they provide DNS resolution, better isolation, and the ability to attach/detach containers dynamically. Use network segmentation to follow the principle of least privilege (frontend can't talk directly to database).**`
  },
  'docker-production': {
    explanation: `**Docker in production** involves running containers reliably, securely, and at scale. While Docker Compose works for simple deployments, production environments typically use orchestration platforms (Docker Swarm, Kubernetes, or managed services) to handle scaling, load balancing, self-healing, and rolling updates.

**Production considerations:** **Orchestration** - use Kubernetes or Docker Swarm for multi-host deployment, scaling, and management. **Logging** - containers should log to stdout/stderr (not files). Use Docker's logging drivers (json-file, syslog, fluentd, CloudWatch) to collect logs centrally. **Monitoring** - use cAdvisor, Prometheus, and Grafana for container metrics (CPU, memory, network, disk). Use Docker's healthchecks for application-level monitoring. **Resource limits** - set CPU and memory limits for each container (\`docker run --memory=512m --cpus=1\`). This prevents one container from starving others. **Restart policies** - \`always\`, \`unless-stopped\`, \`on-failure:5\`. Ensures containers restart after crashes. **Security** - don't run as root, use read-only root filesystem (\`--read-only\`), drop Linux capabilities (\`--cap-drop=ALL --cap-add=NET_BIND_SERVICE\`), use security options (\`--security-opt=no-new-privileges\`). Scan images for vulnerabilities. Use Docker Content Trust for image signing. **Updates** - use rolling updates (Kubernetes or Swarm) to update containers without downtime. Pull strategy (\`--pull always\`) ensures latest image. **Data persistence** - use named volumes for stateful services (databases). Use cloud storage (EBS, EFS) for production volumes. **Networking** - use overlay networks for multi-host communication. Use ingress load balancing (Swarm routing mesh) or a reverse proxy (Traefik, Nginx) for external traffic. **Secrets** - use Docker secrets (Swarm) or Kubernetes secrets. Never hardcode secrets in images. **Backup** - regularly backup volume data. Test restores. **Best practice:** start with a managed Kubernetes service (EKS, AKS, GKE) for production. Use Docker Compose for development. Use CI/CD to build and push images. Tag images with commit SHA (\`myapp:abc123\`) and version (\`myapp:v1.2.3\`). Use semantic versioning. Implement health checks. Set resource limits. Use liveness, readiness, and startup probes (Kubernetes) for advanced health checking. Use a service mesh (Istio, Linkerd) for advanced traffic management. Use GitOps for deployment. Monitor everything. Have a rollback strategy. Use canary or blue-green deployments for risk reduction.`,
    codeExplanation: `This shows **Docker production configuration**. **Production Dockerfile:** multi-stage build, non-root user, healthcheck, labels with version info. **Production compose (partial):** resource limits (\`deploy.resources.limits\`), restart policy (\`unless-stopped\`), security options (\`read_only: true\`, \`cap_drop: ALL\`, \`seccomp: docker-seccomp.json\`), logging driver (\`json-file\` with rotation), healthcheck, secrets (not hardcoded). **Kubernetes deployment:** the YAML shows a Kubernetes Deployment and Service. \`replicas: 3\` runs 3 instances. \`strategy.rollingUpdate\` defines zero-downtime deployment. \`resources.limits\` sets CPU/memory limits. \`livenessProbe\` and \`readinessProbe\` for health checking. \`Service\` of type \`ClusterIP\` exposes the app internally. **CI/CD with semantic tags:** GitHub Actions builds, tags with both \`latest\` and commit SHA (\`\${{ github.sha }}\`), pushes to registry, deploys to Kubernetes with the SHA tag. The Kubernetes manifest has the image tag as a parameter (can use kustomize or helm to set). **Docker Swarm production:** similar to compose but with \`deploy:\` options (replicas, resources, restart_policy, update_config for rolling updates, placement constraints for node selection). **Production checklist:** use a registry (Docker Hub, ECR, GCR), tag images properly, scan for vulnerabilities, set resource limits, configure logging, implement health checks, use secrets management, set up monitoring (CPU, memory, disk, network), configure backup for volumes, test rollback procedure, use rolling updates, enable Docker Content Trust, restrict container capabilities, use read-only filesystem, enable user namespace remapping for extra isolation. **Kubernetes is the standard for production container orchestration** - it provides auto-scaling, self-healing, service discovery, load balancing, rolling updates, and secret management. Start with a managed Kubernetes service (EKS, AKS, GKE) to reduce operational overhead. Use Helm for package management.**`
  },
  'cicd-fundamentals': {
    explanation: `**CI/CD (Continuous Integration and Continuous Delivery/Deployment)** automates the building, testing, and deployment of your application. CI automatically builds and tests code changes, ensuring they integrate well with the existing codebase. CD automatically deploys validated changes to production (or staging) environments.

**Continuous Integration (CI):** Developers merge code changes frequently (multiple times per day). Each merge triggers an automated build and test suite. This catches integration errors early, reduces merge conflicts, and gives rapid feedback. **Key CI practices:** maintain a single source repository, automate the build, make builds self-testing, keep builds fast (under 10 minutes), test in a clone of production environment, make it easy to get the latest deliverables. **Continuous Delivery (CD):** CI + automated deployment to staging environments. The code is always in a deployable state. A manual approval step before production deployment is typical. **Continuous Deployment:** Every change that passes CI is automatically deployed to production. No manual approval. Requires high test coverage and confidence in the pipeline. **CI/CD Pipeline stages:** **Source** (checkout code) -> **Build** (compile, install dependencies) -> **Test** (unit tests, linting, type checking, integration tests) -> **Quality** (code analysis, test coverage, security scan) -> **Package** (build Docker image, push to registry) -> **Stage** (deploy to staging, run E2E tests) -> **Production** (deploy to production, monitor). **Tools:** **CI/CD platforms:** GitHub Actions, GitLab CI/CD, Jenkins, CircleCI, Travis CI. **Artifact repositories:** Docker Hub, ECR, Nexus, Artifactory. **Pipeline as Code:** define the pipeline in a YAML file in the repository (GitHub Actions, GitLab CI). This version-controls the pipeline alongside the code. **Best practice:** start simple (build + test) and add stages incrementally. Keep pipeline fast (parallelize tests). Use caching for dependencies. Fail fast (fail early in the pipeline). Make the pipeline the only way to deploy (no manual SSH/deploys). Use environment variables for secrets. Use matrix builds for testing multiple versions. Use pipeline templates/shared configurations to reduce duplication. Implement quality gates (test coverage thresholds, linting rules). Review pipeline changes like code changes. Monitor pipeline performance. Alert on pipeline failures. Use deployment slots for zero-downtime deployments. Implement rollback capability. Use feature flags for gradual rollouts. Document the deployment process.`,
    codeExplanation: `This shows **CI/CD pipeline with GitHub Actions**. **Trigger:** on push to main and pull requests to main. **Jobs run in parallel:** lint, test, build. Test job depends on lint (faster feedback - fail early). **Lint job:** runs ESLint. **Test job:** runs unit tests with coverage. **Build job:** builds the application. **Deploy job:** runs only after all previous jobs pass AND only on push to main (not PRs). Steps: checkout, login to Docker registry, build and tag Docker image with commit SHA and latest, push image, deploy to Kubernetes using kubectl with the SHA tag (for traceability), and notify about deployment via Slack. **Caching:** \`actions/cache\` caches node_modules - keyed by package-lock.json hash. This speeds up subsequent runs (npm install takes seconds instead of minutes). **Secrets:** \`DOCKER_USERNAME\`, \`DOCKER_PASSWORD\`, \`KUBE_CONFIG\` are stored in GitHub Secrets and injected as environment variables. **Pipeline stages explained:** 1. Source: \`actions/checkout\` clones the repo. 2. Dependencies: \`npm ci\` installs exact versions from package-lock.json (faster and more reliable than npm install). 3. Quality: linting runs. 4. Test: unit tests with coverage. 5. Build: TypeScript compilation. 6. Build & Push Docker image. 7. Deploy to Kubernetes. 8. Notify via Slack. **Parallel execution:** lint, test, and build run in parallel (they don't depend on each other). Deploy waits for all three. **Fail fast:** if lint fails, test and build jobs show as skipped (not run). This gives instant feedback. **Best practice:** always use \`npm ci\` instead of \`npm install\` in CI (clean install, respects lockfile, faster). Use matrix builds to test across Node versions (\`matrix.node-version: [18, 20, 22]\`). Use concurrency to cancel in-progress runs when new commits are pushed. Use environment protection rules for production deployment (requires approval). Tag Docker images with both \`latest\` and the commit SHA. The SHA tag enables specific rollback. The \`latest\` tag is the current production. This pipeline follows the principle: **automated builds, tests, and deployments** - the only manual step is merging the PR. Everything else is automatic.**`
  },
  'nginx-basics': {
    explanation: `**Nginx** is a high-performance web server, reverse proxy, and load balancer. It's designed to handle many concurrent connections with low memory usage (event-driven, asynchronous architecture). Nginx is commonly used to serve static files, proxy requests to application servers (Node.js, Express), load balance traffic, terminate SSL/TLS, and cache responses. It's often placed in front of Node.js applications in production.

**Key features:** **Reverse proxy** - forwards requests to backend servers. \`proxy_pass http://localhost:3000\`. **Load balancing** - distribute traffic across multiple backend servers (round-robin, least connections, IP hash). **Static file serving** - efficiently serves static files without involving the app server. **SSL/TLS termination** - handles HTTPS, freeing the app server from encryption overhead. **Caching** - cache responses to reduce backend load. **Rate limiting** - limit requests per IP. **Access control** - allow/deny by IP. **URL rewriting** - modify URLs. **Gzip compression** - compress responses. **HTTP/2 support** - faster page loads with multiplexing. **Configuration structure:** \`nginx.conf\` includes \`http\` block (global settings, upstreams, servers). \`server\` blocks define virtual hosts (sites). \`location\` blocks define how specific URLs are handled. **Best practice:** use Nginx as a reverse proxy (not a replacement for Node.js). Deploy Nginx in front of your Node.js app. Use it for SSL termination, static files, caching, load balancing, and rate limiting. Don't run Nginx in the same container as your app. Use separate containers or separate services. Configure proper timeouts (proxy_read_timeout, proxy_connect_timeout). Set proper buffer sizes. Use gzip. Configure security headers. Use HTTPS with modern TLS versions. Monitor Nginx logs (access.log, error.log). Use \`nginx -t\` to test configuration before reloading. Use \`nginx -s reload\` for zero-downtime configuration changes. Use \`.d\` directories for modular configuration (sites-available, sites-enabled, conf.d). Use variables sparingly (Nginx variable resolution can have edge cases).`,
    codeExplanation: `This is a **production Nginx configuration** for a Node.js app. **HTTP block:** \`upstream backend\` defines the application servers (for load balancing). \`keepalive 32\` enables connection reuse. **Server block (port 80):** redirects all HTTP traffic to HTTPS (301). **Server block (port 443):** SSL configuration with modern TLS 1.3 only, secure ciphers, HSTS, OCSP stapling. \`location / \` proxies all requests to the backend upstream. \`proxy_http_version 1.1\` and \`proxy_set_header Upgrade/Connection\` support WebSocket connections. \`location /static/\` serves static files directly (with a 1-year cache for immutable content). \`proxy_cache\` enables caching of API responses. **Security headers:** \`add_header\` sets X-Frame-Options, X-Content-Type-Options, X-XSS-Protection, Referrer-Policy, Permissions-Policy, Content-Security-Policy. **Rate limiting:** \`limit_req_zone\` defines a rate limit zone (10 requests/second per IP). \`limit_req zone=mylimit burst=20 nodelay\` applies it (burst allows up to 20 excess requests, nodelay means excess requests are processed immediately but rate-limited). **Gzip:** enable gzip compression for text-based content (HTML, CSS, JS, JSON, SVG, fonts). **SSL:** modern configuration with TLS 1.3 only, strong ciphers, strict SNI, HSTS for 1 year, OCSP stapling, and SSL session caching. Use Let's Encrypt with certbot for free SSL certificates. Automation: certbot renews certificates automatically and runs \`nginx -s reload\`. **Testing:** \`nginx -t\` validates the configuration. \`nginx -s reload\` applies changes without dropping connections. This configuration balances **performance, security, and functionality** - it's production-ready for most Node.js applications. Adjust cache times, rate limits, and upstream servers based on your specific needs.**`
  },
  'nginx-reverse-proxy': {
    explanation: `**Nginx reverse proxy** is the most common production deployment pattern for Node.js applications. Nginx sits in front of your Node.js server, handling SSL, static files, load balancing, caching, and security. The Node.js server focuses on application logic while Nginx handles infrastructure concerns.

**Why use a reverse proxy:** **SSL/TLS termination** - Nginx handles HTTPS efficiently. Node.js handles HTTP internally (faster, simpler). **Static file serving** - Nginx serves static files directly (much faster than Node.js). **Load balancing** - distribute requests across multiple Node.js instances. **Caching** - cache responses at the proxy level, reducing application load. **Security** - hide internal server details, rate limiting, IP filtering, DDoS protection. **WebSocket proxying** - Nginx supports proxying WebSocket connections with proper Upgrade headers. **Multiple apps on one server** - route different domains/paths to different Node.js apps. **Standard ports** - bind to port 80/443 (privileged) and proxy to Node.js on high-numbered ports (no root needed for Node.js). **Configuration patterns:** **Proxy pass** - \`proxy_pass http://backend\` forwards requests. **Upstream** - defines backend servers for load balancing. **Location blocks** - different handling for different URL paths. **Buffering** - proxy_buffering controls response buffering. **Timeouts** - proxy_read_timeout, proxy_connect_timeout, proxy_send_timeout. **Headers** - proxy_set_header forwards original client IP, protocol, host. **Best practice:** set \`proxy_set_header X-Real-IP $remote_addr\` so Node.js knows the client's real IP. Set \`proxy_set_header X-Forwarded-Proto $scheme\` so Express knows if the original request was HTTPS. Use \`proxy_redirect off\` to prevent Nginx from rewriting redirects. Use \`proxy_buffering off\` for streaming responses. Use \`proxy_http_version 1.1\` for keepalive connections. Use \`upstream\` with \`keepalive\` for connection reuse. Use \`location = /health\` for a health check endpoint that bypasses caching and rate limiting. Monitor Nginx access logs for upstream response times (\`$upstream_response_time\`). Test proxy configuration with \`nginx -t\`. Use \`upstream\` with \`ip_hash\` for sticky sessions if needed (prefer stateless apps though).`,
    codeExplanation: `This Nginx configuration shows **reverse proxy patterns**. **Basic reverse proxy:** \`proxy_pass http://localhost:3000\` forwards all requests to Node.js on port 3000. \`proxy_set_header\` preserves original client info (real IP, protocol, host). **Upstream with multiple servers:** \`upstream backend\` defines three Node.js instances for load balancing. \`least_conn\` balances based on active connections. \`keepalive 32\` maintains connection pool for better performance. **WebSocket support:** \`proxy_http_version 1.1\`, \`proxy_set_header Upgrade $http_upgrade\`, \`proxy_set_header Connection "upgrade"\` - these headers enable WebSocket proxying. \`proxy_read_timeout 86400s\` prevents timeout on long-lived WebSocket connections. **API vs static files:** \`location /api/\` proxies API requests to the backend. \`location /static/\` serves static files directly from disk with caching headers. \`location / \` sends non-API, non-static requests to the backend (for SSR). **Buffering and performance:** \`proxy_buffering off\` for streaming endpoints. \`proxy_buffer_size 4k\`, \`proxy_buffers 8 4k\` for normal proxying. \`proxy_connect_timeout 60s\` limits connection establishment time. \`proxy_send_timeout 60s\` limits data sending time. \`proxy_read_timeout 60s\` limits waiting for response time. **Health checks:** \`location /health\` returns 200 with a simple text response (doesn't proxy to backend). This endpoint is used by load balancers to check Nginx health. **Client IP forwarding:** \`proxy_set_header X-Real-IP $remote_addr\` sends the original client IP. \`proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for\` adds to the forwarded chain. Node.js/Express needs \`app.set('trust proxy', true)\` to trust these headers and get the correct client IP from \`req.ip\`. **This pattern allows Node.js to focus on application logic** while Nginx handles infrastructure: SSL, static files, load balancing, caching, security, and WebSocket proxying. It also enables horizontal scaling - add more Node.js instances behind the upstream and Nginx automatically distributes traffic.**`
  },
  'nginx-performance': {
    explanation: `**Nginx performance optimization** focuses on maximizing throughput and minimizing latency. Nginx is already highly performant out of the box, but tuning it for your specific workload can significantly improve performance. Key areas: worker processes, buffering, caching, compression, keepalive, and SSL.

**Worker processes:** \`worker_processes auto\` auto-detects CPU cores. Set to the number of CPU cores. Each worker is a single-threaded process that handles many connections. \`worker_connections\` sets max connections per worker (default 512, can increase to 4096+). Total max connections = worker_processes * worker_connections. **Buffering:** \`proxy_buffering on\` buffers responses from the backend. This lets Nginx send responses to slow clients without keeping backend connections busy. Buffer size settings: \`proxy_buffer_size\`, \`proxy_buffers\`, \`proxy_busy_buffers_size\`. **Caching:** \`proxy_cache_path\` defines a cache storage. \`proxy_cache\` enables caching. Cache keys are based on URL and query parameters. Use \`proxy_cache_valid\` to set TTL by status code. Use \`proxy_cache_use_stale\` to serve stale cache when the backend is down (graceful degradation). **Compression:** \`gzip on\` compresses responses. Compress text-based content (HTML, CSS, JS, JSON, SVG). Don't compress already-compressed content (images, PDFs). Set \`gzip_comp_level 4-6\` (higher = more compression but more CPU). \`gzip_types\` lists what to compress. **Keepalive:** \`keepalive_requests 1000\` max requests per keepalive connection. \`keepalive_timeout 65\` seconds to keep idle connections open. **SSL performance:** use TLS 1.3 (faster handshake). Enable session caching (\`ssl_session_cache shared:SSL:10m\`). Enable session tickets (\`ssl_session_tickets on\`). Use OCSP stapling. Use modern cipher suites (fewer, faster ciphers). **Sendfile:** \`sendfile on\` enables efficient file serving (kernel-level file copying). \`tcp_nopush on\` optimizes packet sending for static files. **Open file cache:** \`open_file_cache max=1000 inactive=20s\` caches open file descriptors for static files. **Best practice:** benchmark with your specific workload. Monitor with Nginx Amplify or similar. Adjust worker processes and connections based on available CPU and memory. Use caching aggressively for static assets and cacheable API responses. Use gzip for text content. Enable keepalive. Use TLS 1.3 with session caching. Set proper buffer sizes. Use HTTP/2 for multiplexing. Consider using Brotli compression (better than gzip, ratio wise). Use a CDN for static assets. Monitor system resources (CPU, memory, disk I/O, network). Tune OS-level settings (net.core.somaxconn, net.ipv4.tcp_tw_reuse, fs.file-max). Profile with htop, iostat, netstat, and Nginx stub status module.`,
    codeExplanation: `This shows **Nginx performance configuration**. **Event model:** \`use epoll\` (Linux, most efficient). \`worker_connections 4096\` allows each worker to handle up to 4096 connections simultaneously (total 4096*4=16384 connections). \`multi_accept on\` accepts all new connections at once. **Sendfile and TCP:** \`sendfile on\`, \`tcp_nopush on\`, \`tcp_nodelay on\` optimize network packet sending. **Open file cache:** caches up to 1000 file descriptors for 20 seconds. \`open_file_cache_valid 30s\` checks cache validity. \`open_file_cache_min_uses 2\` only caches files accessed at least twice. **Gzip compression:** compress HTML, CSS, JS, JSON, SVG, fonts, XML. Level 5 (good balance). \`gzip_vary on\` sends Vary: Accept-Encoding header. \`gzip_proxied any\` compresses proxied requests too. **Brotli compression (if module is installed):** better compression ratio than gzip. \`brotli_static on\` serves pre-compressed .br files. \`brotli_types\` same as gzip. **Proxy caching:** \`proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=mycache:100m max_size=10g inactive=60m use_temp_path=off\` creates a 10GB cache with 100MB metadata zone. \`proxy_cache mycache\` enables it on API locations. \`proxy_cache_key "$scheme$request_method$host$request_uri"\` sets cache key. \`proxy_cache_valid 200 302 10m\` caches successful responses for 10 minutes. \`proxy_cache_use_stale error timeout\` serves stale cache when backend errors. \`add_header X-Cache-Status $upstream_cache_status\` adds header indicating HIT/MISS/STALE. **Rate limiting:** \`limit_req_zone $binary_remote_addr zone=api:10m rate=30r/s\` limits requests. \`limit_req zone=api burst=50 nodelay\` allows bursts. **SSL session cache:** \`ssl_session_cache shared:SSL:50m\` (cache up to ~50,000 sessions). \`ssl_session_timeout 4h\`. \`ssl_session_tickets on\`. Using TLS 1.3 reduces handshake to 1-RTT (or 0-RTT for returning clients). **Tune these values based on your specific workload and hardware** - there's no one-size-fits-all configuration. Monitor with Nginx stub_status module (\`/nginx_status\` endpoint) to see active connections, accepted, handled, and requests. Use Nginx Amplify for long-term monitoring and recommendations. Use \`ab\` or \`wrk\` for load testing. Profile with \`perf\` or \`flamegraphs\` for deep performance analysis. Performance gains often come from **caching and compression** rather than CPU tuning. Start with cache settings and measure impact before diving into worker process tuning.**`
  },
  'nginx-security': {
    explanation: `**Nginx security** protects your web applications from common attacks by configuring proper headers, access controls, rate limiting, and SSL/TLS settings. Nginx is often the first line of defense for your application - it processes requests before they reach your application server. A properly secured Nginx can block many attacks before they affect your application.

**Key security measures:** **Hide Nginx version** - \`server_tokens off\` prevents attackers from targeting version-specific vulnerabilities. **Limit request methods** - only allow GET, POST, HEAD; block TRACE, DELETE, PUT unless needed. **Limit request size** - \`client_max_body_size 1m\` prevents large payload attacks. **Rate limiting** - \`limit_req_zone\` and \`limit_conn_zone\` prevent brute force and DoS. **IP blacklisting/whitelisting** - allow or deny specific IPs or ranges. **User-agent filtering** - block known bad bots. **Security headers** - X-Frame-Options (clickjacking), X-Content-Type-Options (MIME sniffing), X-XSS-Protection, Content-Security-Policy, Referrer-Policy, Permissions-Policy, Strict-Transport-Security. **HTTPS** - enforce TLS 1.2/1.3 only, redirect HTTP to HTTPS. **SSL configuration** - strong ciphers, secure protocols, proper certificate management. **Access control** - restrict access to sensitive paths (/admin, /.git, /config) by IP or auth. **Limit exposed paths** - don't expose internal endpoints (/health, /metrics, /debug) publicly. **Prevent path traversal** - Nginx normalizes URLs by default. **DDoS protection** - rate limiting, connection limiting, timeouts. **Best practice:** follow a layered security approach. Configure all security headers. Enforce HTTPS. Use strong SSL ciphers and protocols. Implement rate limiting on all endpoints (stricter on auth endpoints). Restrict access to admin panels by IP or VPN. Use a Web Application Firewall (WAF) like ModSecurity or NAXSI. Monitor access and error logs for suspicious patterns. Regularly update Nginx (security patches). Use fail2ban to automatically block malicious IPs. Use Content Security Policy to prevent XSS. Use HSTS to force HTTPS. Use Certificate Transparency monitoring. Use separate log files for security events. Harden the OS (minimal packages, firewall, SELinux/AppArmor). Use read-only root filesystem for the Nginx container. Run Nginx as non-root user (if possible). Remove unused Nginx modules from build.`,
    codeExplanation: `This shows **Nginx security configuration**. **Basic security:** \`server_tokens off\` hides Nginx version. \`client_max_body_size 1m\` limits request body size. \`client_body_buffer_size 128k\` limits body buffering. \`large_client_header_buffers 4 8k\` limits header size (prevents header overflow attacks). **Security headers:** all OWASP-recommended security headers are set. \`Content-Security-Policy\` is strict (same-origin scripts only, no inline scripts, no eval). \`Referrer-Policy: strict-origin-when-cross-origin\`. \`Permissions-Policy\` disables all sensitive features (camera, microphone, geolocation). **SSL/TLS:** only TLS 1.3 (modern, secure). Strong cipher suites. HSTS for 1 year. OCSP stapling enabled. SSL session cache for performance. **Rate limiting:** two zones - auth endpoints (5 req/min) and general API (100 req/min). Stricter limits on auth. **Access control:** \`satisfy any\` allows access if either IP whitelist OR basic auth passes. \`auth_basic\` prompts for username/password. \`allow 10.0.0.0/8\` whitelists internal network. \`deny all\` blocks everything else. **Bot blocking:** \`map $http_user_agent $bad_bot\` identifies bad bots by user-agent. \`if ($bad_bot) { return 403 }\` blocks them. **Limiting connections:** \`limit_conn_zone $binary_remote_addr zone=conn_limit:10m\` tracks connections per IP. \`limit_conn conn_limit 10\` max 10 concurrent connections per IP. **Block common attacks:** \`location ~ \\.(git|env|svn|hg|svn)\` denies access to version control and env files. \`location ~ /\\.\` denies access to dotfiles (.htaccess, .gitignore). \`location /admin\` restricted to internal IPs only. **Logging:** separate log files for security events. \`log_format security\` includes request method, URI, status, body bytes, referrer, user-agent, and upstream response time. **Security is a continuous process** - keep Nginx updated, review logs regularly, update CSP headers as your application evolves, and follow OWASP recommendations. Automated scanning tools (OWASP ZAP, Nikto) can help identify missing security configurations. Use Mozilla Observatory to grade your security headers. Use SSL Labs to grade your TLS configuration. A perfect SSL Labs score (A+) requires: TLS 1.3 only (or 1.2+), strong ciphers, HSTS with long max-age, OCSP stapling, and no known vulnerabilities in the certificate chain.**`
  },
  'pm2-basics': {
    explanation: `**PM2** is a production process manager for Node.js applications. It keeps your application running forever, handles clustering, provides monitoring, and enables zero-downtime deployments. PM2 is the standard for running Node.js applications in production when not using container orchestration.

**Key features:** **Process management** - start, stop, restart, delete processes. **Auto-restart** - automatically restarts your app if it crashes. **Clustering** - run multiple instances across all CPU cores. **Log management** - logs are stored, rotated, and accessible via \`pm2 logs\`. **Startup script** - generate init script to restart PM2 on server reboot. **Graceful shutdown** - sends SIGINT, waits for app to close connections before force-killing. **Configuration file** (\`ecosystem.config.js\`) - declare all settings in a JS file. **Key commands:** \`pm2 start app.js\`, \`pm2 list\`, \`pm2 stop app\`, \`pm2 restart app\`, \`pm2 delete app\`, \`pm2 logs\`, \`pm2 monit\`. **Clustering:** \`pm2 start app.js -i max\` starts one instance per CPU core. PM2's built-in load balancer distributes requests. **Best practice:** use ecosystem.config.js. Use cluster mode. Implement graceful shutdown. Use \`pm2 startup\` for auto-start on boot. Use \`max_memory_restart\` to auto-restart on memory leaks. Use \`watch: false\` in production. Set \`NODE_ENV=production\`. Combine with Nginx reverse proxy.`,
    codeExplanation: `This \`ecosystem.config.js\` shows PM2 configuration. \`script: './dist/server.js'\` uses compiled JS. \`instances: 'max'\` uses all CPU cores. \`exec_mode: 'cluster'\` enables load balancing. \`autorestart: true\` always restart on crash. \`max_memory_restart: '500M'\` auto-restart on memory limit. \`kill_timeout: 5000\` - PM2 sends SIGINT, waits 5s, then force-kills. \`listen_timeout: 3000\` waits for app readiness. Separate error and output logs with timestamps. \`NODE_ENV: 'production'\`. \`pm2 startup systemd\` generates systemd service. \`pm2 save\` saves process list. **Graceful shutdown in app:** \`process.on('SIGINT', async () => { await server.close(); await prisma.$disconnect(); process.exit(0); })\`. PM2 + Nginx is the battle-tested combination for Node.js production on VMs.`
  },
  'pm2-clustering': {
    explanation: `**PM2 clustering** runs multiple instances of your Node.js app across all CPU cores. Node.js is single-threaded, so one instance uses one core. On a multi-core server, PM2 cluster mode starts a worker per core with a built-in round-robin load balancer sharing a single port.

**How it works:** PM2 forks your app into workers, each on a different CPU core. The load balancer distributes connections. If a worker crashes, PM2 restarts it. Use \`-i max\` for one worker per CPU core. **Stateless design:** cluster mode works best with stateless apps. For shared state, use Redis (sessions, caches). **Zero-downtime reload:** \`pm2 reload\` restarts workers one by one. \`pm2 gracefulReload\` waits for existing connections to finish. **Graceful shutdown:** app must handle SIGINT to close connections gracefully. **Memory limits:** \`max_memory_restart\` restarts workers exceeding the limit (catches memory leaks). **Best practice:** always use cluster mode in production. Implement graceful shutdown. Use Redis for shared state. Use \`--wait-ready\` to ensure app is ready before receiving traffic. Use \`pm2 reload\` for zero-downtime updates. For Dockerized apps, use orchestration-level scaling instead. PM2 cluster mode is simple, reliable, and well-understood for VM-based deployments.`,
    codeExplanation: `This shows PM2 cluster config. \`exec_mode: 'cluster'\` enables clustering. \`instances: 'max'\` uses all CPU cores. \`instance_var: 'INSTANCE_ID'\` sets an env variable for worker identity. \`--wait-ready\` waits for \`process.send('ready')\` before considering the worker started. **Graceful shutdown:** app listens for SIGINT, calls \`server.close()\` to stop accepting connections, waits for in-flight requests (with timeout), disconnects from services, then exits. **CLI commands:** \`pm2 start app.js -i max\`, \`pm2 reload app\` (zero-downtime), \`pm2 gracefulReload app\`, \`pm2 scale app 6\`. For WebSocket apps, use \`sticky: true\` in PM2 config (IP hash load balancing) or externalize state with Redis pub/sub. **Benefits:** full CPU utilization, resilience, zero-downtime deployments. **Drawbacks:** each worker has separate memory, shared state needs external services. PM2 cluster mode is the standard for Node.js on VMs. For containers, use Kubernetes/Docker Swarm scaling instead.`
  },
  'pm2-monitoring': {
    explanation: `**PM2 monitoring** provides real-time visibility into your Node.js application's performance, resource usage, and health. Built-in tools: \`pm2 monit\` (terminal dashboard), \`pm2 show\` (process details), \`pm2 logs\` (log streaming). PM2 Plus (commercial) adds a web dashboard, custom metrics, transaction tracing, and alerting across multiple servers.

**Built-in monitoring:** \`pm2 list\` shows all processes with status, CPU, memory, and uptime. \`pm2 show\` displays restarts count, PID, exec path, and environment. \`pm2 monit\` is a real-time terminal dashboard for CPU/memory per process. **Key metrics:** CPU usage (target <70-80%), memory (shouldn't grow unbounded), restarts (frequent restarts indicate crashes), event loop lag (>100ms indicates blocking), file descriptors, request rate, response time. **PM2 Plus:** custom metrics via \`pmx\` library, transaction tracing, error tracking, deployment history, alert rules. **Best practice:** set up monitoring from day one. Use PM2 Plus or integrate with existing tools (Datadog, New Relic, Prometheus + Grafana). Monitor trends, not just current values. Set up alerts for anomalies. Use structured logging for easier parsing. Implement health check endpoints. Use \`pm2-logrotate\` for log management. Track memory trends to catch leaks early. Monitor restart counts - they should be near zero in stable apps.`,
    codeExplanation: `This shows PM2 monitoring setup. \`pm2 monit\` is the built-in terminal dashboard. \`pm2 show app\` shows detailed process info - watch the restarts count. **PM2 Plus:** \`module: { name: 'app', metrics: { http: true, event_loop: true } }\` enables enhanced monitoring. Custom metrics: \`pmx.probe().metric('Active Users', () => count)\`. **Log management:** \`pm2 install pm2-logrotate\` with config: rotate at 100MB, keep 30 days, compress old logs. **Health check:** \`GET /health\` returns process health (uptime, memory, DB connectivity) for load balancers. **Prometheus integration:** \`pm2-metrics\` exposes Prometheus-style metrics. Scrape with Prometheus, visualize with Grafana - a free monitoring stack. **Monitoring checklist:** CPU/memory trends, restart counts, event loop lag, disk usage for logs. Use PM2 Plus for all-in-one or PM2 + Prometheus + Grafana for a free alternative.`
  },
  'pm2-production': {
    explanation: `**PM2 for production** configures PM2 for reliability, clustering, zero-downtime deployments, and infrastructure integration. Use \`ecosystem.config.js\` (version-controlled). Set \`NODE_ENV=production\`. Enable cluster mode (\`instances: max\`). Set memory limits. Configure graceful shutdown and log management.

**Zero-downtime deployment:** \`pm2 reload\` restarts workers one by one. \`pm2 gracefulReload\` waits for connections to drain. Combine with Nginx for additional connection draining during deployments. **Strategies:** rolling update (standard), blue-green (new instances on different port, switch with Nginx), canary (route % traffic to new version). **Startup:** \`pm2 startup systemd\` creates a systemd service. \`pm2 save\` saves process list for restoration on boot. **CI/CD:** use \`pm2 deploy\` for SSH-based deployments, or integrate PM2 commands in CI/CD pipeline. **Security:** run PM2 as non-root user. Use \`pm2 startup\` with sudo but run processes as regular user. Don't expose PM2's web interface publicly. **Best practice:** use ecosystem.config.js. Implement graceful shutdown. Set restart limits. Use \`pm2 save\` after changes. Test recovery by restarting the server. Have a documented runbook. Monitor restart counts. PM2 is battle-tested for production Node.js on VMs. For Docker/Kubernetes, use orchestration-level process management instead.`,
    codeExplanation: `This shows PM2 production configuration. \`ecosystem.config.js\` with cluster mode, memory limits, graceful shutdown timeout, environment variables, and log rotation. \`pm2 deploy\` configuration for SSH-based deployments: define key, user, host, repo, path, and post-deploy hook (\`npm install && npm run build && pm2 reload ecosystem.config.js\`). **Zero-downtime with Nginx:** during deployment, configure Nginx to drain connections from the old port before switching to the new one. **Startup:** \`pm2 startup systemd && pm2 save\`. **CI/CD pipeline step:** \`pm2 stop app && git pull && npm ci && npm run build && pm2 start app\`. Or simpler: \`pm2 reload ecosystem.config.js\`. **Rollback:** \`pm2 deploy ecosystem.config.js production revert 1\` reverts to previous deployment. **For Dockerized apps:** run Node directly (\`CMD ["node", "server.js"]\`) and let Docker orchestration handle process management. PM2 adds unnecessary complexity inside containers. PM2 shines when running Node.js directly on VMs with Nginx as reverse proxy.**`
  },
  'testing-fundamentals': {
    explanation: `**Software testing** verifies that your application works correctly and prevents regressions. A comprehensive testing strategy includes multiple levels: **unit tests** (test individual functions/modules in isolation), **integration tests** (test how modules work together, including database), and **end-to-end tests** (test complete user flows from the browser). Each level has different speed, cost, and confidence characteristics.

**The testing pyramid (bottom to top):** **Unit tests** (many, fast, cheap, <100ms each) - test pure functions, utility functions, and business logic. Mock external dependencies. **Integration tests** (fewer, slower, longer) - test API endpoints with real database, test service functions with real dependencies. **E2E tests** (few, slow, expensive, seconds each) - test critical user journeys through the full system (Cypress, Playwright). **Test structure (AAA):** **Arrange** (set up test data and preconditions), **Act** (execute the action being tested), **Assert** (verify the result). **Test coverage:** measures which code is executed during tests. High coverage is good, but 100% is not the goal - focus on critical paths and edge cases. **Mocking and stubbing:** replace real dependencies with controlled replacements. Mock external APIs, database queries, file system operations. **Test-driven Development (TDD):** write tests before code. Red (test fails) -> Green (make it pass) -> Refactor (improve code). **Best practice:** write tests that test behavior, not implementation. Use descriptive test names. Test one thing per test case. Test edge cases (empty input, null values, large inputs, special characters). Use factories/fixtures for test data. Keep tests independent (don't share mutable state). Run tests in CI. Use code reviews to enforce testing standards. Aim for the "testing trophy" (more integration tests than unit or E2E). Write tests that give you confidence to deploy on every commit.`,
    codeExplanation: `This shows **test structure**. **Unit test (Vitest):** \`describe\` groups tests, \`it\` defines a test case. \`expect(actual).toEqual(expected)\` is the assertion. \`vi.fn()\` creates a mock function. \`vi.mock('../src/db')\` mocks the database module. The test mocks the db, creates test data, calls the function, and verifies the result. **Integration test (Supertest + test DB):** \`beforeAll\` creates the app instance and connects to a test database. \`beforeEach\` seeds test data. \`request(app).post('/api/users').send({...})\` makes an HTTP request. Expect status 201 and verify the response body. \`afterEach\` cleans up test data. \`afterAll\` disconnects from test DB. **E2E test (Playwright):** launches a browser, navigates to the app, fills in a form, clicks submit, and verifies text appears on the page. **Test coverage:** \`npx vitest --coverage\` generates an HTML coverage report showing which lines are executed. Focus on untested critical paths. **The testing trophy model:** invest most in integration tests (they test how parts work together), have many unit tests (fast feedback for logic), and a few E2E tests (critical user journeys). Unit tests alone aren't enough - they miss integration issues. E2E tests alone are too slow and flaky. Integration tests give the best confidence-to-speed ratio.**`
  },
  'unit-testing': {
    explanation: `**Unit testing** tests individual units of code (functions, modules, classes) in isolation. Unit tests are fast, deterministic, and pinpoint exactly what failed. They're the foundation of a good testing strategy, providing rapid feedback during development.

**What to unit test:** Pure functions (same input always gives same output), business logic (validation, calculations, transformations), utility functions, edge cases (boundary conditions, error handling). **What NOT to unit test:** Framework internals (React, Express), database queries (test with integration tests), configuration, code that's trivial (getters/setters). **Frameworks:** Vitest (fast, Vite-native, recommended), Jest (standard), Mocha (flexible). **Matchers:** \`toBe\` (exact equality), \`toEqual\` (deep equality), \`toMatchObject\` (partial match), \`toContain\`, \`toThrow\`, \`toBeGreaterThan\`, \`toBeNull\`, \`toBeDefined\`, \`toHaveLength\`. **Mocking:** \`vi.fn()\` (mock function), \`vi.spyOn()\` (spy on existing method), \`vi.mock()\` (mock entire module). Use mocks to isolate the unit under test from its dependencies. **Spies:** verify that a function was called with specific arguments: \`expect(mockFn).toHaveBeenCalledWith(42)\`. **Test organization:** group by module/feature using \`describe\`. Each test case with \`it\` or \`test\`. Use \`beforeEach\`/\`afterEach\` for setup/teardown. **Best practice:** write testable code (pure functions, dependency injection, avoid global state). One assertion per behavior (but multiple related assertions are OK). Test descriptions should read as sentences: \`it('returns the sum of two numbers')\`. Keep tests simple - if a test is complex, the code might need refactoring. Use factories (Faker.js) for realistic test data. Run unit tests on every file change in development (watch mode). Aim for fast tests (<100ms each) so the suite completes in seconds.`,
    codeExplanation: `This shows **unit test patterns with Vitest**. **Pure function test:** \`calculateDiscount\` is tested with normal case, edge case (no discount), and boundary (exact threshold). \`test.each\` runs the same test with different inputs (table-driven tests). **Async function test:** use \`async\` test functions with \`await\`. \`expect(result).toEqual(expected)\`. **Mocking:** \`vi.mock('../src/db')\` mocks the db module. \`const mockGetUser = vi.fn().mockResolvedValue(userData)\` creates a mock that returns resolved data. \`expect(mockGetUser).toHaveBeenCalledWith(userId)\` verifies the mock was called correctly. **Dependency injection test:** \`const result = processOrder(inventory, { productId: 1, quantity: 10 })\` - inject mock inventory to isolate the function. **Error case:** \`expect(() => validateEmail('invalid')).toThrow('Invalid email')\` verifies errors are thrown. **Coverage:** run with \`--coverage\` to see uncovered lines. **Table-driven tests:** \`test.each([...])('...', (input, expected) => ...)\` efficiently tests multiple cases. **Isolation is key** - mock all external dependencies so failures are always in the unit being tested, not in its dependencies. Good unit tests are: fast, isolated, deterministic (same result every run), and test one behavior. They give rapid feedback during development and catch regressions immediately.**`
  },
  'integration-testing': {
    explanation: `**Integration testing** verifies that different parts of your application work together correctly. Unlike unit tests (which isolate individual units), integration tests test real interactions between modules, databases, APIs, and external services. They provide higher confidence than unit tests but are slower and more complex to set up.

**What to integration test:** API endpoints (request -> controller -> service -> database), database operations (CRUD, queries, migrations), middleware chains, authentication flows, external service integrations (with test doubles or mocks). **Test database:** Use a separate test database (parallel to your development DB) or use an in-memory database (SQLite for PostgreSQL apps, mongodb-memory-server). Run migrations before the test suite, clean data between tests. **Supertest:** the standard library for testing Express/HTTP APIs. \`const response = await request(app).get('/api/users').expect(200)\`. It starts the Express app internally and makes real HTTP requests. **Setup/teardown:** \`beforeAll\`: connect to test DB, run migrations. \`beforeEach\`: seed clean test data. \`afterEach\`: clean up data. \`afterAll\`: disconnect from test DB. **Factories:** use factories (Fixtures, Faker, or factory_bot-like libraries) to generate realistic test data. This avoids hardcoding data in each test. **Testing patterns:** test the happy path first (success case), then error cases (validation errors, auth errors, not found), then edge cases (empty results, pagination boundaries). **Best practice:** use a test database that mirrors production (same DB type, same schema). Clean data between tests (truncate tables, not just transactions). Use factories for data creation. Test API responses (status codes, response body structure, headers). Test error responses. Test rate limiting and auth. Keep tests independent. Run integration tests in CI but not on every file change (they're slower than unit tests). Integration tests give the best confidence-to-speed ratio - they catch real issues that unit tests miss (wrong config, missing migrations, incorrect error handling).`,
    codeExplanation: `This shows **integration test patterns**. **Setup:** \`beforeAll\` runs migrations (\`prisma db push --force\`) and creates the app. \`afterAll\` disconnects from the test DB and stops the app. **Per-test cleanup:** \`beforeEach\` truncates all tables (\`db.$executeRaw\` for PostgreSQL or use Prisma's deleteMany). This ensures each test starts with a clean state. **Seeding:** \`createTestUser\` and \`createTestPost\` are factory functions that create test data with default values overridable per test. \`faker.internet.email()\` generates realistic random data. **GET /api/users - success:** seeds a user, makes a GET request, expects 200, verifies the response includes the user's email. **POST /api/users - validation error:** sends invalid data (empty email), expects 400, verifies the error response structure. **GET /api/users/:id - not found:** requests a non-existent ID, expects 404. **Auth flow:** registers a user with POST, verifies token is returned, uses the token in Authorization header for subsequent requests. **Testing with Supertest:** \`request(app).post('/api/auth/login').send(credentials).expect(200)\` sends form data and checks the response. The app is imported directly (not started on a real port) - Supertest handles this internally. **Integration tests catch issues that unit tests miss:** wrong database schema, incorrect query syntax, middleware order problems, auth header parsing, error response format. They're the most valuable type of test for backend applications. Aim to cover all API endpoints with integration tests, especially the critical user flows.**`
  },
  'e2e-testing': {
    explanation: `**End-to-end (E2E) testing** tests complete user flows from the browser's perspective. It's the most realistic type of testing - it verifies that the entire system works together: frontend, backend, database, and external services. E2E tests use browser automation tools like Playwright or Cypress to simulate real user interactions.

**What to E2E test:** Critical user journeys (sign up, login, purchase flow), cross-cutting concerns (navigation, authentication), visually complex interactions (drag and drop, animations). **Avoid** testing every edge case via E2E (use unit/integration tests for those - they're faster and more reliable). **Playwright** (recommended): modern, fast, cross-browser (Chromium, Firefox, WebKit), auto-waits for elements. **Cypress:** popular, great debugging experience, but only Chromium-based browsers. **Common patterns:** **Page Object Model** - encapsulate page interactions in reusable classes. **Data-driven tests** - run the same test with different data. **Visual regression** - compare screenshots. **API preconditions** - use API calls to set up test state (instead of slow UI interactions). **Best practice:** focus on critical user journeys (happy path). Keep E2E tests minimal (they're slow and flaky). Use data-testid attributes for reliable selectors. Run E2E tests on a staging environment (not production). Use CI to run them. Retry flaky tests. Set proper timeouts. Use API calls for test setup (create user via API instead of filling registration form). Test in multiple browsers. Run tests in parallel. Use trace viewer for debugging failures. Record videos of failed tests. E2E tests give the highest confidence but are the most expensive - use them strategically for critical paths only.`,
    codeExplanation: `This shows **E2E test with Playwright**. **Configuration:** \`fullyParallel: true\` runs tests in parallel. \`retries: 2\` retries flaky tests. \`workers: 4\` uses 4 parallel workers. \`use.baseURL\` sets the app URL. **Page Object Model:** \`LoginPage\` class encapsulates login page interactions - \`goto()\`, \`fill()\`, \`click()\`, \`waitForURL()\`. Tests use \`new LoginPage(page)\` for clean, readable code. **Test:** navigates to login, fills credentials, submits, verifies redirect to dashboard and welcome message. **Component testing (Playwright CT):** test React/Vue components in isolation with Playwright. \`test('button click')\` mounts the button component, clicks it, verifies the counter updated. **API preconditions:** \`await request.post('/api/test/setup', { data: { ... } })\` creates test data via API before the test starts. This is faster than filling forms in the UI. **Visual regression:** \`await expect(page).toHaveScreenshot()\` compares the page against a stored screenshot. Fails if the page looks different (useful for detecting unintended visual changes). **Recording:** \`video: 'retain-on-failure'\` records video only for failed tests (helps debugging). **Selectors:** prefer \`getByRole\`, \`getByText\`, \`getByTestId\` (use data-testid for elements that are hard to select otherwise). Avoid CSS selectors tied to implementation. **Assertions:** \`expect(page.getByText('Welcome!')).toBeVisible()\` auto-waits for visibility. **E2E best practices:** use a dedicated test environment, seed data via API, test critical flows only, run in CI, use retries for flaky tests, record failures for debugging. E2E tests are your safety net - they catch integration bugs that unit and integration tests miss, but use them strategically due to their cost (time, maintenance, flakiness).**`
  },
  'tdd-bdd': {
    explanation: `**TDD (Test-Driven Development)** and **BDD (Behavior-Driven Development)** are development methodologies that put testing at the center of the development process.

**TDD (Test-Driven Development):** Write tests before writing production code. The cycle: **Red** (write a failing test), **Green** (write minimal code to pass the test), **Refactor** (improve code while tests pass). **Benefits:** forces you to think about design before coding, ensures testability, provides immediate feedback, creates a safety net for refactoring, reduces debugging time. **TDD is a design tool, not just a testing tool** - it leads to cleaner, more modular code because code must be testable. **When TDD works best:** unit-level development (utility functions, business logic), bug fixes (write a test that reproduces the bug, then fix). **BDD (Behavior-Driven Development):** Extends TDD by writing tests in natural language that describes user behavior. Uses \`Given/When/Then\` format. Tools: Cucumber (Gherkin syntax), Vitest with \`describe/it\` (BDD-style). **BDD focuses on behavior, not implementation** - tests describe what the system should do from the user's perspective. **Given** (preconditions), **When** (action), **Then** (expected outcome). **Acceptance Test-Driven Development (ATDD):** similar to BDD, tests are written collaboratively by developers, testers, and business stakeholders. **Best practice:** use TDD for new features and bug fixes. Write the test first - if it's hard to write, the design may need improvement. Keep the cycle tight (minutes, not hours). Refactor after each green test. Use BDD for acceptance tests that describe user-facing behavior. Don't be dogmatic - sometimes writing the code first is more practical (exploratory work, prototyping). The key value of TDD is not the tests themselves, but the improved code design that results from test-first thinking. BDD bridges the gap between technical and non-technical stakeholders by using natural language.`,
    codeExplanation: `This shows **TDD and BDD patterns**. **TDD cycle:** 1. Write a failing test (\`expect(add(2, 3)).toBe(5)\`). 2. Write the minimal function (\`const add = (a, b) => a + b\`). 3. Refactor if needed. **BDD with Cucumber:** Feature file in Gherkin syntax: \`Given the user is logged in\`, \`When they add an item to the cart\`, \`Then the cart should show 1 item\`. Step definitions map Gherkin steps to code. **TDD for bug fixes:** 1. Write a test that reproduces the bug (\`expect(calculateTotal([{ price: 10, quantity: 0 }])).toBe(0)\` - currently returns NaN). 2. Run test - it fails (bug confirmed). 3. Fix the code (\`if (item.quantity === 0) return 0\`). 4. Test passes (bug fixed). **Benefits of TDD:** the test suite serves as documentation (shows how the code should behave), enables confident refactoring, and catches regressions immediately. **Benefits of BDD:** tests are readable by non-technical stakeholders, focus on user value, and bridge communication gaps. **TDD is most effective at the unit level** (pure functions, business logic). For integration tests, BDD-style acceptance tests work well. The choice between TDD and BDD depends on your team and context - what matters is having a disciplined testing approach that gives you confidence in your code. The most important principle: **write tests before or alongside your code, not after**. Post-hoc testing often misses edge cases and design issues.**`
  },
  'web-performance-basics': {
    explanation: `**Web performance** is about making websites load fast and feel responsive. Performance directly impacts user experience, conversion rates, and SEO (Google uses Core Web Vitals as a ranking factor). The key metrics are: **LCP** (Largest Contentful Paint - loading), **FID/INP** (First Input Delay/Interaction to Next Paint - interactivity), **CLS** (Cumulative Layout Shift - visual stability).

**Core Web Vitals:** **LCP** should be <2.5s - measures loading performance (largest content element visible). **FID** <100ms or **INP** <200ms - measures interactivity (response to user input). **CLS** <0.1 - measures visual stability (unexpected layout shifts). **RAIL model:** **Response** (respond to user within 50ms), **Animation** (produce a frame in 10ms), **Idle** (maximize idle time), **Load** (deliver content within 5s). **Performance optimization strategies:** **Reduce bundle size** - code splitting, tree shaking, minification, compression (gzip/brotli). **Optimize images** - serve next-gen formats (WebP/AVIF), lazy load below-fold images, use responsive images with srcset, compress appropriately. **Reduce network requests** - bundle files, use HTTP/2 multiplexing, preconnect to origins. **Optimize rendering** - avoid layout thrashing, use CSS animations, debounce scroll/resize handlers. **Caching** - service workers, CDN caching, browser caching, API caching. **Best practice:** measure before optimizing (Lighthouse, Web Vitals library, Real User Monitoring). Focus on the metrics that matter most for your application. Optimize the critical rendering path. Use a performance budget (max 200KB JS, 100KB CSS, 1MB total page weight). Implement performance monitoring in production. Performance is a feature - invest in it from the start. It's much harder to retrofit performance later. The biggest gains come from reducing JavaScript bundle size and optimizing images.`,
    codeExplanation: `This code shows **performance measurement and monitoring**. **Lighthouse CI** runs automated audits in CI. \`assertions\` set performance budgets (LCP < 2.5s, TBT < 300ms, CLS < 0.1). \`--budget=performance-budget.json\` enforces bundle size limits (max 200KB JS, 100KB CSS, 1MB total). **Real User Monitoring (RUM):** \`web-vitals\` library captures actual user metrics. \`onCLS\`, \`onFID\`, \`onLCP\` functions send metrics to an analytics endpoint. \`navigator.sendBeacon\` ensures the data is sent even if the page is closing. **Performance observer:** \`performance.getEntriesByType('resource')\` monitors individual resource timings. \`PerformanceObserver\` with \`largest-contentful-paint\` and \`layout-shift\` entry types tracks Core Web Vitals programmatically. **Server timing:** \`res.setHeader('Server-Timing', 'db;dur=53, cache;dur=22')\` sends backend timing info that appears in browser DevTools Network tab. **Performance budgets prevent regressions:** if a PR adds too much JavaScript, the CI check fails. **Critical rendering path optimization:** inline critical CSS, defer non-critical JS, preload key resources (\`<link rel="preload">\`), and minimize render-blocking resources. **Performance culture:** make performance a team responsibility. Add performance checks to CI. Monitor in production. Set performance budgets. Regularly audit with Lighthouse. Fix regressions quickly. Performance is not a one-time optimization - it requires continuous attention.**`
  },
  'frontend-optimization': {
    explanation: `**Frontend optimization** focuses on making websites load fast and run smoothly in the browser. It covers everything from initial page load to runtime performance. With modern web applications shipping large amounts of JavaScript, optimization is critical for good user experience.

**Key areas:** **JavaScript optimization:** Reduce bundle size (code splitting, tree shaking, dynamic imports). Remove unused code (bundle analyzer). Use modern syntax (ES modules). Defer non-critical JS. **CSS optimization:** Critical CSS inlined, non-critical deferred. Remove unused CSS (PurgeCSS). Use CSS Grid/Flexbox (no layout library needed). **Image optimization:** Serve WebP/AVIF (with JPEG/PNG fallback). Use responsive images (\`srcset\` + \`sizes\`). Lazy load below-fold images (\`loading="lazy"\`). Use proper dimensions (prevent CLS). Use CDN for images. **Font optimization:** Self-host fonts (no external requests). Use \`font-display: swap\` (text visible during font load). Preload critical fonts. Subset fonts for languages used. **Code splitting:** Split by routes (React.lazy + Suspense). Split by components (dynamic imports). Split by vendor chunk (separate library updates from app code). **Caching:** Service worker for offline support and instant loading. Cache API responses. Use CDN for static assets. **Rendering optimization:** Virtual scrolling for long lists. Avoid layout thrashing (batch DOM reads/writes). Use \`requestAnimationFrame\` for animations. Defer expensive calculations. **Bundle analysis:** Use \`vite --analyze\` or webpack-bundle-analyzer to find large dependencies. Consider alternatives for heavy libraries (date-fns instead of moment, zustand instead of redux). **Best practice:** set a performance budget and enforce it in CI. Analyze your bundles regularly. Optimize the critical rendering path. Lazy load everything below the fold. Use modern image formats. Self-host fonts. Monitor with Real User Monitoring. Performance is a continuous investment, not a one-time task. Start with a Lighthouse audit, fix the biggest issues, and set up monitoring to prevent regressions.`,
    codeExplanation: `This shows **frontend optimization techniques**. **Code splitting with React.lazy:** \`const UserDashboard = React.lazy(() => import('./dashboard'))\` only loads the dashboard module when the route is visited. **Suspense** shows a fallback while loading. **Route-based splitting:** the router lazily loads each page component. **Image optimization:** \`loading="lazy"\` defers offscreen images. \`srcset\` serves different image sizes based on viewport. \`<picture>\` with \`<source type="image/webp"\> serves WebP with JPEG fallback. **Font optimization:** \`@font-face\` with \`font-display: swap\` ensures text is visible during font load. \`unicode-range\` subsets fonts to only the characters needed. **Virtual scrolling:** \`react-window\` renders only visible items (+ overscan) in a long list. For 10,000 items, only ~20 DOM nodes are created. This is essential for performance with large lists. **Bundle analysis:** \`vite --config vite.config.ts --mode analyze\` opens a visual representation of your bundle. Identify large libraries and find opportunities for code splitting. **CSS optimization:** \`PurgeCSS\` removes unused CSS (configured via Vite/postcss). \`critical\` extracts and inlines above-fold CSS. **Service worker:** cache static assets on first load. On subsequent loads, the page loads instantly from cache (even offline). \`workbox\` simplifies service worker generation. **Performance budget:** enforce maximum JS/CSS/image sizes. Fail CI builds that exceed the budget. **The biggest wins come from reducing JavaScript** - audit your bundle, remove unused libraries, split code by routes, and lazy load heavy components. Second biggest: optimize images (serve WebP, use proper sizes, lazy load). Third: optimize fonts (self-host, subset, font-display: swap).**`
  },
  'backend-performance': {
    explanation: `**Backend performance** optimization focuses on reducing API response times, increasing throughput, and handling more concurrent users. Backend performance bottlenecks typically involve database queries, CPU processing, network I/O, or external API calls.

**Key areas:** **Database optimization:** Add missing indexes. Optimize queries (avoid N+1, select only needed columns). Use connection pooling. Use read replicas for read-heavy workloads. Denormalize for read performance if needed. Partition large tables. **Caching:** Cache API responses in Redis. Use in-memory caching for frequently accessed data. Implement cache-aside pattern with appropriate TTLs. Cache rendered pages or fragments. **Async processing:** Offload expensive operations to background jobs (email, image processing, report generation). Use message queues (Bull, RabbitMQ, Kafka). **Connection management:** Use connection pooling for databases. Use keepalive connections. Close connections properly. **Compression:** Enable gzip/brotli compression for API responses. Use binary formats (MessagePack, Protocol Buffers) for internal services. **Load balancing:** Distribute traffic across multiple instances. Use horizontal scaling for stateless services. **Profiling and monitoring:** Use APM tools (New Relic, Datadog) to identify slow operations. Profile CPU and memory. Monitor GC pressure. Use flame graphs to find bottlenecks. **Computation optimization:** Use efficient algorithms. Cache computation results. Move CPU-intensive work to worker threads or separate services. **Network optimization:** Use HTTP/2. Enable keepalive. Use CDN for static/deterministic responses. Minimize serialization overhead. **Best practice:** measure before optimizing - use tools like autocannon for load testing and async_hooks for tracing. Focus on the 80/20 rule (20% of optimizations give 80% of gains). Start with database query optimization (biggest impact). Add caching next. Then look at application code optimization. Profile in production-like conditions. Set performance budgets for API response times (p99 < 200ms for critical endpoints). Monitor trends, not just current values. Performance optimization is iterative - measure, optimize, measure again.`,
    codeExplanation: `This shows **backend performance patterns**. **Database query optimization:** \`prisma.user.findUnique({ where: { id }, include: { posts: { take: 10, orderBy: { createdAt: 'desc' } } } })\` uses a JOIN instead of N+1 queries. Index on \`userId\` and \`createdAt\` supports the query. **Connection pooling:** \`new Pool({ connectionString, max: 20, idleTimeoutMillis: 30000 })\` reuses database connections. **Redis caching:** cache-aside pattern checks Redis first, falls back to database, stores result in cache with TTL. **Async processing with Bull:** CPU-intensive video processing is queued (\`videoQueue.add({ videoId })\`). A separate worker processes it. The API responds immediately while the task runs in the background. **Load testing with autocannon:** \`autocannon -c 100 -d 30 http://localhost:3000/api/users\` simulates 100 concurrent connections for 30 seconds. Reports requests/sec, latency (avg, p99), and throughput. **Compression middleware:** \`app.use(compression())\` enables gzip/brotli compression for responses. \`level: 6\` balances compression ratio and CPU usage. **Memory profiling:** \`node --inspect app.js\` enables Chrome DevTools debugging. The Memory tab shows heap snapshots. Look for objects that aren't being garbage collected (memory leaks). Common causes: global variables, event listeners not removed, closures holding large objects, unbounded caches. **Backend performance checklist:** optimize database queries first (they're usually the biggest bottleneck), add caching (Redis for hot data), use async processing for expensive operations, enable compression, use connection pooling, profile with APM tools, monitor p99 latency. Each optimization should be measured - if it doesn't improve metrics by a meaningful amount, revert it. Premature optimization adds complexity without value. Measure, identify the bottleneck, fix it, measure again.**`
  },
  'network-optimization': {
    explanation: `**Network optimization** reduces latency and bandwidth usage for data transfer between client and server. Network performance is critical for web applications - every millisecond of additional latency reduces user engagement. Optimization spans DNS resolution, TCP connections, TLS handshakes, HTTP requests, and data transfer.

**Key techniques:** **CDN (Content Delivery Network):** serves static assets from edge locations close to users. Reduces latency for static files (images, JS, CSS). **HTTP/2 and HTTP/3:** multiplexing (multiple requests over one connection), header compression, server push. HTTP/3 uses QUIC (UDP-based) for even faster connections. **DNS optimization:** use fast DNS providers. Reduce DNS lookups. Prefetch DNS for critical origins (\`<link rel="dns-prefetch">\`). **Preconnect:** \`<link rel="preconnect">\` initiates early TCP/TLS handshake with critical origins. **Resource hints:** \`preload\` (critical resources), \`prefetch\` (future navigation), \`prerender\` (next page). **Reduce request count:** bundle files, use CSS sprites, inline critical resources, use HTTP/2 multiplexing. **Reduce payload size:** gzip/brotli compression, minification, tree shaking, code splitting, proper image formats/sizes. **Optimize TLS:** use TLS 1.3 (1-RTT handshake), session resumption, OCSP stapling. **Connection reuse:** HTTP keepalive, connection pooling. **Data compression:** use compact serialization (MessagePack, Protocol Buffers) for internal services. Use compression for API responses. **Best practice:** use a CDN for static assets. Enable HTTP/2 or HTTP/3. Preconnect to critical origins. Reduce request count and payload size. Enable compression. Use resource hints for critical resources. Monitor network performance with Navigation Timing API and Resource Timing API. Optimize for the 95th percentile user, not the median. Network optimization is especially important for mobile users on slow connections - test on throttled networks (Slow 3G). Use tools like WebPageTest for detailed network performance analysis. The largest network gains come from: CDN (reduces latency by 50-200ms), compression (reduces size by 60-80%), and reducing total JavaScript (reduces parsing time and request count).`,
    codeExplanation: `This shows **network optimization patterns**. **CDN configuration (Cloudflare):** proxies traffic through edge nodes. Auto-minifies HTML/CSS/JS. Enables Brotli compression. Uses HTTP/2 and HTTP/3. Caches static assets at the edge. **Resource hints in HTML:** \`dns-prefetch\` resolves DNS early (no visible effect but helps). \`preconnect\` starts TCP/TLS handshake before the resource is needed (significant improvement). \`preload\` tells the browser to fetch critical resources immediately (fonts, hero images, critical CSS). \`prefetch\` hints at resources needed for the next page. **Connection pooling (Node.js):** \`keepAlive: true\` reuses TCP connections. \`keepAliveMsecs: 1000\` sends keepalive probes every second. \`maxSockets: 50\` max connections per host. \`maxFreeSockets: 10\` keeps 10 idle connections open. **HTTP/2 server (Node.js):** \`http2.createSecureServer\` creates an HTTP/2 server with built-in multiplexing. **Compression middleware:** \`compression({ level: 6, threshold: 1024, filter: shouldCompress })\` compresses responses >1KB. Skips compression for images and videos. **Network timing monitoring:** \`performance.getEntriesByType('navigation')\` provides DNS lookup time, TCP handshake time, TLS time, TTFB, and DOM load time. \`performance.getEntriesByType('resource')\` provides per-resource timing. **Metrics to track:** DNS time (<20ms), TCP time (<20ms), TLS time (<100ms), TTFB (<200ms from CDN), content download time (depends on size and connection speed). **Network optimization checklist:** use CDN (Cloudflare, Fastly, Akamai), enable HTTP/2 or HTTP/3, use resource hints (preconnect, preload), enable compression (Brotli, gzip), minimize request count (bundle, sprite, inline), optimize images (WebP, proper sizes), use connection pooling, monitor network timing, test on Slow 3G. The network is usually the biggest performance bottleneck - optimizing it gives the most visible improvement to users.**`
  },
  'performance-monitoring': {
    explanation: `**Performance monitoring** tracks your application's performance in real-time, detects regressions, and helps identify optimization opportunities. It encompasses Real User Monitoring (RUM) which measures actual user experiences, and Synthetic Monitoring which runs tests from controlled environments. Both are essential for understanding and maintaining performance.

**Real User Monitoring (RUM):** Captures performance data from actual users' browsers. **Tools:** web-vitals library, Google Analytics, Datadog RUM, New Relic Browser. **Metrics:** Core Web Vitals (LCP, FID/INP, CLS), TTFB, FCP, Time to Interactive, JS errors, network请求 timing. **Data collection:** send metrics via \`navigator.sendBeacon()\` or analytics API. Sample a percentage of users (not all - reduces cost and noise). **Synthetic Monitoring:** Run performance tests from controlled environments at regular intervals. **Tools:** Lighthouse CI, WebPageTest, Pingdom, Checkly. **Purpose:** catch regressions before they affect users, test from specific locations, generate consistent reproducible measurements. **APM (Application Performance Monitoring):** Server-side monitoring of application performance. **Tools:** Datadog, New Relic, Sentry (performance), OpenTelemetry. **Metrics:** request latency (p50, p95, p99), throughput, error rate, database query time, external API latency, garbage collection, CPU/memory usage. **Distributed tracing:** Track requests across microservices. Identify where latency is added in a distributed system. **Alerting:** Set up alerts for performance degradations (p99 latency >500ms, error rate >1%, throughput drops). Use anomaly detection for automatic thresholding. **Dashboards:** Visualize key metrics over time. Show trends (daily, weekly, monthly). Compare current metrics against baseline. **Best practice:** implement RUM from day one (you don't know what users are experiencing without it). Use synthetic monitoring for CI/CD performance gates. Use APM for server-side insights. Set up dashboards and alerts. Monitor trends, not just current values. Performance monitoring is an investment that pays for itself by catching regressions quickly - a slow page that goes unnoticed for weeks can cost significant revenue. The goal is to know when performance degrades and be able to pinpoint the cause quickly.`,
    codeExplanation: `This shows **performance monitoring setup**. **RUM with web-vitals:** \`onLCP(console.log)\`, \`onFID(console.log)\`, \`onCLS(console.log)\` capture Core Web Vitals from real users. Metrics are sent to an analytics endpoint using \`navigator.sendBeacon\` with \`type: 'text/plain'\` and connection information (effective type, RTT, downlink). **Synthetic monitoring (Checkly):** \`@checkly/cli\` defines browser checks that run every 10 minutes. The check navigates to the app, waits for the LCP element, asserts URL, and asserts no console errors. **APM with OpenTelemetry:** \`NodeTracerProvider\` enables distributed tracing. \`ExpressInstrumentation\` automatically traces Express requests. \`BatchSpanProcessor\` exports spans. The example shows an Express route with manual spans: \`tracer.startActiveSpan('db.query')\` wraps the database query. The span is ended when the query completes. OpenTelemetry exports spans to Jaeger, Zipkin, or cloud APM providers. **Alerting configuration (pseudo-code):** alert when p99 latency exceeds 500ms for 5 minutes, error rate exceeds 1%, or throughput drops below 100 req/s. **Dashboard metrics:** LCP trend (daily p75), p50/p95/p99 latency, error rate, throughput, database query time, external API latency, GC pause time. **Performance monitoring is about continuous improvement** - measure, set targets, optimize, verify improvement, repeat. Without monitoring, you're flying blind. With it, you can make data-driven optimization decisions and catch regressions before they impact users. Implement RUM first (user experience is what matters), then APM (for debugging), then synthetic monitoring (for CI/CD gates). Each layer provides different insights and together they give a complete picture of your application's performance.**`
  },
};
